window.HB_TR["luke"]["ks"]=["1. یوت تام واریاہو لوکو تمن چیزن ہُند اعلان ترتیب دِنہٕ خٲطرٕ اتھس منز رٔٹمُت یِم اسہِ منز یقینا پژھ تھاوان چھِ،\n2. یێلہِ تہِ تِمو اسہِ تام واتنوو، یِم گۅڈٕ پیٹھے چشم دید گواہ تہٕ کلامٕکۍ خادم ٲسۍ۔\n3.\\tمیہ تہِ اوس یہ جان باسان زِ گۅڈہ پیٹھے سارِنٕے چیزن ہنز مکمل سمجھ آسنہ کنۍ تہِ چھہ ژے ترتیب پٲٹھۍلیکھُن، بہترین تھیوفیلس،\n4. تاکہ تۅہہ گژھہِ تِمن چیزن ہُند یقین زانُن یِمن مَنٛز تۄہہِ ہدایت دِنہٕ آمٕژ چھِ۔\n5.\\tیہودیہِ کِس بادشاہ ہیرودیس سٕندِس زمانس مَنٛز اوس ابیاہس منز زکریا ناوُک اکھ پادٕر، تہٕ تسٕنز زنانہٕ ٲس ہارون سٕنزِ کورِ ہٕنز، تہٕ تٔمۍ سُند ناو اوس الزبتھ۔\n6. تہٕ تِم ٲسۍ دۅشوے خدایہِ سٕندِس برونہہ کُن نیک ، خداوند سٕندِس سارِنٕے حُکمن تہٕ احکامَن مُطٲبِق ٲسۍ بے عیب پٲٹھۍ۔\n7. تہٕ تمن اوس نہٕ کانہہ شُر، تکیازِ زِ الزبتھ ٲس بانجھ، تہٕ تم ٲسۍ دۄشوے ؤری وادن منز مبتلا گٔمٕتۍ۔\n8. تہٕ سپُد یہِ زِ یێلہِ سُہ پادٕرۍ سُند عہدٕ خدایہِ سٕندِس برونہہ کُن انجام دِیُت،\n9.\\tپادٕرۍ سٕندِس دفترس مُطٲبق اوس تٔمِس سٍتـ̡ بخور زالُن۔\n10.\\tتہٕ سارِوٕے لُکھ اوس بُورٕ وِزِ دُعا کران۔\n11.\\tتہٕ تس آو خداوند سُند اکھ فرشتہ نمودار یُس بخور کِس قربان گاہ کِس دچھنہِ طرفہٕ کھڑا اوس۔\n12.\\tتہٕ ییلہ زکریا یَن أمِس وُچھ، سُہ گوٚو پریشان تہٕ تس گوٚو خوف۔\n13.\\tمگر فرشتہ ووٚن أمِس زکریا زِ تۅہہِ ہُند دُعا چُھ بوزنہٕ آمُت۔ تہٕ تہنز زنانہٕ الزبتھ زیٚیہِ ژےٚ اکھ نیٚچُو، تہٕ ژٕ وَنُن أمِس جان ناو۔\n14. تہٕ ژے گژھہِ خوشی تہٕ خوشی حٲصل کرنہٕ۔ تہٕ واریاہ گژھن تٔمۍ سٕندِس زینہٕ پیٹھ خوش۔\n15. یێلہِ سُہ آسہِ خداوند سٕندِس نظرس منز عظیم تہٕ نہ شراب تہٕ نہ چُھہ شراب۔ تہٕ سُہ گژھہِ روح القدس سٍتـ̡ بٔرِتھ، ماجہ ہٕندِ رحمہٕ پیٹھٕ تہِ۔\n16.\\tتہٕ واریاہ بنی اسرائیل گژھن خداوند پننِس خداہس کُن پھیرُن۔\n17. تہٕ سُہ گژھہِ الیاس سٕندِ روحہٕ تہٕ طاقتہٕ سٍتـ̡ أمِس برونہہ کُن، مٲلن ہُند دِل بچن کُن پھیرنہٕ خٲطرٕ، تہٕ نافرمانن ہٕندِس دِلس کُن پھیرُن۔ خداوند سٕندِ خٲطرٕ تیار لُکھ تیار کرنہٕ خٲطرٕ۔ {حکمت: یا، حکمت}\n18.\\tتہٕ زکریا ہن ووٚن فرشتہٕ سٍتـ̡ کتھ پٲٹھـ̡ بہٕ پتاہ کٔرِتھ؟ تکیازِ بہٕ چُھس اکھ بُزرگ نفر، تہٕ میانہِ زنانہٕ چھے ؤری وادن منز مُتٲثِر۔\n19. تہٕ جواب دِنہٕ وٲلِس فرشتہٕ ووٚن أمِس زِ بہٕ چُھس جبرائیل، یُس خدایہ سٕندِس حضورس منز کھڑا چُھ۔ تہٕ بہٕ چُھس ژےٚ کتھ کرنہٕ خٲطرٕ تہٕ ژےٚ یِم خوشخبری دِنہٕ خٲطرٕ سوزنہٕ آمُت۔\n20.\\tتہٕ وُچھِو تۅہہِ کُنہِ دۅہہٕ یِم کتھ کرنہٕ یِنہٕ وٲلِس دۅہس تام کٔرِتھ تہٕ کتھ کٔرِتھ ہێکہِ نہٕ، تِکیازِ تۅہہِ چُھہ نہٕ میانین کلامَن پیٹھ پژھ تھاوان، یُس تِمن ہٕندِس وقتس مَنٛز پوٗرٕ سپدِ۔\n21. تہٕ لُکھ روٗد زکریا سُند پیاران تہٕ حٲران گٔیہِ زِ سُہ روٗد مندرس مَنٛز واریاہس کالس روٗدمُت۔\n22.\\tتہٕ ییلہ سُہ نیبر دِیوُت، سُہ ہیوٚک نہٕ تِمن سٍتـ̡ کتھ کٔرِتھ، تہٕ تِمو گوو زِ تٔمۍ اوس مندرس مَنٛز اکھ وژن وُچھمُت، تکیازِ تٔمۍ کٔر تِمن کُن اِشارٕ، تہٕ روٗد کُنہِ تہِ کُنہ\n23.\\tتہٕ سپُد یہِ زِ یُتھ تٔمۍ سٕنزِ خدمتہٕ ہٕندِ دۅہ مُکمل گٔیہِ، سُہ دراو پننِس گرس کُن۔\n24. تہٕ یِمو دۅہہٕ پَتہٕ گٔیہِ أمۍ سٕنزِ خانٛدارِنہِ الزبتھ حاملہٕ، تہٕ کورُن پانژَن رٮ۪تن پانَس پٲٹھۍ،\n25.\\tیِتھٕ پٲٹھـ̡ چُھہ خداوند میہ سٍتـ̡ یێلہِ سٍتـ̡\n26. تہٕ شیٚیِمہِ رٮ۪تس مَنٛز آو جبرائیل فرشتہٕ خدایہِ سٕندِ طرفہٕ گلیل کِس أکِس شہرس مَنٛز سوزنہٕ، یُس ناصرت ناو اوس،\n27. أکِس کنوارِس سٍتـ̡ یٔمِس أکِس شخٕصس سٍتـ̡ یٔمِس ناو یوسف اوس، یُس داؤد سٕندِس گرس سٍتـ̡ اوس۔ تہٕ کنواری سُند ناو اوس مریم۔\n28.\\tتہٕ فرشتہ آو أمِس نِش، تہٕ وونُن، ہاے ژے یُس واریاہ فضل چھُ، خداوند چُھہ ژے سٍتـ̡ بابرکت {چُھ} زنانن مَنٛز۔ {انتہایی ...: یا، مہربانی سان قبول، یا، واریاہ فضل سٍتۍ}\n29.\\tتہٕ ییلہ أمس وُچھ، سۅ گٔیہِ تٔمۍ سٕندِس کتھہِ پیٹھ پریشان، تہٕ کوٚرُن پننِس ذہنس منز زِ یہِ کُس کُس سلام گژھہِ آسُن۔\n30. تہٕ فرشتہٕ ووٚن أمِس زِ خوفہٕ نہٕ گژھ مریم، تکیازِ ژے چھے خدایہ سٕنز عنایت حٲصل کٔرمٕژ۔\n31.\\tتہٕ وُچھِو ژے پننِس رحمس مَنٛز حاملہٕ تہٕ اکھ نیٚچُو زیٚو، تہٕ تٔمِس ناو کٔرِو عیسیٰ سُند ناو۔\n32.\\tسُہ بٔڈ آسہِ، تہٕ یُس یُس تھدِ پٲٹھـ̡ سُند نیٚچُو وننہٕ ییہِ: تہٕ خداوند خدا دِیہِ أمِس پننِس مٲلِس داؤد سُند تخت۔\n33. تہٕ سُہ روزِ یعقوب سٕندِس گرس پیٹھ ہمیشہٕ خٲطرٕ۔ تہٕ تٔمۍ سٕنزِ بادشٲہی ہُند کانہہ اند۔\n34. اَمہِ پتہٕ ووٚن مریم فرشتس زِ یہِ کِتھہ پٲٹھۍ، بہٕ چُھس نہٕ کٲنسہِ انسانس زانان۔\n35. تہٕ فرشتہٕ دِیُت جواب تہٕ وونُن تٔمِس زِ روح القدس گژھہِ توے پیٹھ یِنہٕ، تہٕ اعلیٰ ترین سُند طاقت گژھہِ ژےٚ ژھایہِ، تێلہِ تہِ یُس مقدس چیز ژےٚ سٍتـ̡ پٲدٕ سپدِ، سُہ تہِ یُس خدایہِ سُند نیٚچُو وَننہٕ ییہِ۔\n36.\\tتہٕ وُچھِو تُہٕنزِ پِتٕرِ بٲے الزبتھ تہِ بُجرس مَنٛز اکھ نیچو زٲومُت، تہٕ یہِ چُھ أمِس سٍتـ̡ شیٚیِم رٮ۪تھ، یُس بانجھ وَننہٕ اوس یِوان۔\n37. تکیازِ خدایس سٍتـ̡ گژھہِ نہٕ کانہہ تہِ ناممکن۔\n38.\\tتہٕ مریمَن ووٚن، وُچھِو خداوند سٕنزِ دٲیر۔ چانہِ کلامَس مُطٲبِق آسہِ میانہِ خٲطرٕ۔ تہٕ فرشتہ ژاو أمِس نِش۔\n39.\\tتہٕ یِمن دۅہن گٔیہِ مریم وۅتھان تہٕ گٔیہِ جلدٕے پہٲڑی علاقس مَنٛز، یہوداہ کِس شہرس مَنٛز۔\n40. تہٕ ژاو زکریا سٕندِس گرس منز، تہٕ کوٚرُن الزبتھ سلام۔\n41.\\tتہٕ سپُد یہِ زِ ییلہ الزبتھ مریم سُند سلام بوز، بچہٕ ووت تٔمۍ سٕندِس رحمس مَنٛز۔ تہٕ الزبتھ ٲس روح القدس سٍتـ̡ بٔرِتھ:\n42.\\tتہٕ تٔمۍ کٔر بَڑِ آوازِ سٍتـ̡ کتھ تہٕ وونُن، تہٕ تُہٕندِ رحمُک پھل چھُکھ بابرک۔\n43. تہٕ یہ کتہِ چُھہ میانہِ خٲطرٕ، یُس میانہِ رب سٕنز موج میانہِ نِش یِن؟\n44.\\tکیازِ، یُتھُے چانہِ سلامٕچ آواز میانٮ۪ن کنن منز بوز، شُرِ ووت میٲنِس کُنہِ منز خوشی ہٕندِس کُنہِ وُچھ۔\n45. تہٕ بابرکت سُہ یُس ایمان اوس دِژمُت: تِکیازِ تِمن چیزن ہٕنز انجام گژھہِ یِم أمِس خداوند سٕندِ طرفہٕ وننہٕ آمٕژ ٲسۍ۔ {یہ...: یا، یُس مانان اوس زِ تتہِ}\n46.\\tتہٕ مریمَن ووٚن زِ میانہِ روح چُھ خداوند سٕندِس سٍتـ̡ بڑاوان،\n47. تہٕ میٲنۍ روح چُھ خدایہِ سٕندِس نجات دِنہٕ وٲلِس سٍتـ̡ خوش گومُت۔\n48.\\tتکیازِ أمِس چُھ پننہِ دٲیرِ ہٕندِس پست جایدادس سٍتـ̡ وُچھمُت، تکیازِ یێمہِ پٲٹھـ̡ سارِنٕے نسلہٕ سٍتـ̡ چُھہ مے بابرکت وَنان۔\n49. یُس طاقتور چُھ، یُس میہ سٍتـ̡ بٔڈ کٲم کٔرمٕژ چُھ۔ تہٕ مقدس {چُھ} تٔمۍ سُند ناو۔\n50.\\tتہٕ تٔمۍ سٕنز رحمت چھے تِمن پیٹھ یِم أمِس نسل در پیر کھوژان چھِ۔\n51. تٔمۍ کٔر پننہِ نرِ سٍتۍ طاقت ہاونہٕ۔ تٔمۍ چھُ تِہنٛدِس دِلَن ہٕنٛدِس تخیلس منٛز فخر پھٔٹِمُت۔\n52.\\tتٔمۍ کٔر طاقتور تہٕ تِمن ہٕندِس مقامس پیٹھ تھزر۔\n53.\\tتٔمۍ کٔر فاقہٕ بٔرِتھ اصل چیزو سٍتـ̡ بٔرِتھ۔ تہٕ امیر سُہ چھُ خٲلی سوزمُت۔\n54. تٔمۍ چُھ پنُن خادم اسرائیل، پننہِ رحمتہٕ کِس یادس مَنٛز رٔٹمُت۔\n55. یِتھٕ پٲٹھۍ تٔمۍ سانٮ۪ن مٲلن سٍتۍ، ابراہیمس سٍتـ̡ تہٕ تٔمۍ سٕندِس بولس سٍتـ̡ ہمیشہٕ خٲطرٕ کتھ کٔر۔\n56.\\tتہٕ مریم روٗد أمِس سٍتـ̡ تقریباً تریہ ریٚتھ، تہٕ گٔیہٕ پننِس گرس واپس۔\n57. وۅنۍ آو الزبتھ سُند پورٕ وقت زِ سۅ گژھہِ زٲلتھ دِنہٕ۔ تہٕ أمِس زاو اکھ نیٚچُو۔\n58.\\tتہٕ تٔمۍ سٕندٮ۪و ہمساین تہٕ تٔمۍ سٕندٮ۪و پِتٕرۍ بٲے بوز زِ خداوند کِتھ کٔنۍ اوس أمِس سٍتـ̡ سٮ۪ٹھاہ رحمت۔ تہٕ تِم ٲسۍ أمِس سٍتۍ خوش۔\n59.\\tتہٕ سپُد یہ زِ ٲٹھمہِ دۅہہ آیہ تِم شُرِس ختنہ کرنہِ ۔ تہٕ تِمو وَنُن أمِس مٲلہِ سٕندِس ناوس پیٹھ زکریا ۔\n60.\\tتہٕ تسٕنزِ ماجہ دیت جواب تہٕ وونُن، نہٕ {توتہ}۔ مگر تس ییہ جان وننہ۔\n61.\\tتہٕ تِمو ووٚن أمِس زِ تُہٕندِس رشتہ دارس منز چُھنہٕ کانہہ تہِ یُس یَتھ ناوٕ سٍتـ̡ وننہٕ یِوان چُھ۔\n62. تہٕ تِمو کٔر أمِس مٲلِس اشارٕ، زِ سُہ کِتھ کٔنۍ کرِ أمِس بُلاونہٕ۔\n63.\\tتہٕ تٔمۍ منگ لیکھنُک میز، تہٕ لیوکھُن زِ تٔمۍ سُند ناو چُھ جان۔ تہٕ تِمو کٔر سارِنٕے حٲران۔\n64.\\tتہٕ تٔمۍ سُند بوش آو یکدم کھولنہٕ، تہٕ تٔمۍ کٔر خدایہ سٕنز حمد کرنہٕ۔\n65.\\tتہٕ یِمن سارِنٕے أندۍ پٔکھۍ روزن وٲلِس سارِنٕے سٍتـ̡ خوف ووت تہٕ یِم سارِنٕے کَتھٕ گٔیہِ یہوداہ کِس سٲرِسٕے پہٲڑی مُلکس مَنٛز گٔیہِ۔ {اقوال: یا، چیز}\n66.\\tتہٕ یِمو سارِوٕے یِمو بوٗزِو تِمو دِل دِلَس مَنٛز وَنُن زِ یہِ کُس شُر آسہِ! تہٕ خداوند سُند اَتھٕ اوس أمِس سٍتـ̡ ۔\n67.\\tتہٕ تٔمۍ سُند مول زکریا اوس روح القدس سٍتـ̡ بٔرِتھ تہٕ وونُن پیشن گوئی،\n68. بابرکت {بنہ} اسرٲیلُک خداوند خدا۔ تکیازِ تٔمۍ چُھ پننین لوکن ہُند دورٕ کوٚرمت تہٕ نجات دِژمٕژ،\n69. تہٕ تُلُن سانہِ خٲطرٕ پننِس خادم داؤد سٕندِس گرس مَنٛز نجات ہُند سینگ تُلان۔\n70.\\tیِتھ کٔنۍ تٔمۍ پننین مقدس پیغمبرن ہٕندِس زبانہِ سٍتـ̡ کتھ کٔرِتھ، یُس دنیا شروع سپدنہٕ پیٹھٕ چُھ:\n71.\\tزِ اسہِ گژھہِ پننین دشمنن نِش تہٕ سارِنٕے نفرتَن ہٕندِس اتھہٕ نِش بچاونہٕ یُن۔\n72. پننین آباؤ اجدادن سٍتـ̡ رحمتُک انجام دِنہٕ خٲطرٕ، تہٕ تٔمۍ سُند مقدس عہد یاد تھاوُن۔\n73.\\tسُہ حلف یُس سُہ سٲنِس مٲلِس ابراہیمس سٍتـ̡ حلف کٔرِتھ چُھ،\n74.\\tیُس سُہ دِیہِ اسہِ دِنہٕ، یُس أسۍ پننین دُشمنن ہٕندِ اتھہٕ نِش نجات دِنہٕ یِنہٕ سٍتـ̡ بێیہِ خوفہٕ ورٲے أمِس خدمت کٔرِتھ،\n75. سانہِ زندگی ہٕندِس سارِنٕے دۅہہٕ تٔمِس برونہہ کُن پاکیزگی تہٕ نیکی سٍتـ̡ ۔\n76.\\tتہٕ ژے یِیہِ اعلیٰ سُند پیغمبر وننہٕ یُن، تکیازِ تُہۍ گژھِو خداوند سٕندِس بُتھِس برونہہ کُن تٔمۍ سٕنزِ وتہٕ تیار کرنہٕ خٲطرٕ۔\n77.\\tپننین لوکن تہندِ گۅنہہ معاف کرنہٕ سٍتـ̡ نجات ہُند علم دِنہٕ خٲطرٕ، {by: or, for}\n78. سانہِ خدایہ سٕنزِ نرم رحمتہٕ سٍتـ̡ یتھ منز تھزرس پیٹھ دۅہ چشمہ آو اسہِ سٍتۍ، {نرم...: یا، رحمتُک آنت} {دۅہ چشمہ: یا، آفتاب، یا، شاخ}\n79.\\tتِمن گاش دِنہٕ خٲطرٕ یُس اوندِپِس مَنٛز بِہِتھ تہٕ موتٕچ ژھایہِ مَنٛز بِہِتھ چھُ، سانین قدمن امن کِس وتہِ کُن وَتھ دِنہٕ خٲطرٕ۔\n80. تہٕ شُر گوٚو بٔڑِتھ تہٕ روٝحہِ سٍتـ̡ مضبوط، تہٕ روٗد اِسرٲیلِس سٍتـ̡ ظٲہر سپدنہٕ کِس دۅہس تام صحراہس مَنٛز۔","1. تہٕ تِمن دۅہن سپد یہ زِ سیزر آگسٹس سُند حکم نامہٕ آو دِنہٕ زِ سارِنٕے دنیاہس پیٹھ گژھہِ ٹیکس لگاونہٕ یُن۔ {ٹیکس: یا، اندراج}\n2. ({تہٕ} یہٕ ٹیکس اوس ساروی کھوتہٕ گوڑنتھ کرنہٕ آمُت ییلہٕ سائرینیس شامک گورنر اوس۔)\n3. تہٕ سارِنٕے گٔیہِ ٹیکس لاگنہٕ، پرٮ۪تھ أکِس پننِس شہرس منٛز۔ {ٹیکس: یا، اندراج}\n4. تہٕ یوسف تہِ ووت گلیل پیٹھٕ ناصرت شہرٕ نیبر یہوداہ کِس شہرس مَنٛز، یتھ بیت لحم ونان چھِ۔ (تکیازِ سُہ اوس داؤد سٕندِس گرس تہٕ نسبُک :)\n5. مریم سٕنزِ حمایتی زنانہٕ سٍتـ̡ ٹیکس دِنہٕ یُن، یُس بچہٕ سٍتـ̡ عظیم آسنہٕ سٍتـ̡ چُھ۔ {ٹیکس: یا، اندراج}\n6. تہٕ یِتھے پٲٹھۍ اوس یہِ زِ ییٚلہِ تِم تتہِ ٲسۍ، تِم دۅہ گٔیہِ پوٗرٕ زِ أمِس گژھہِ دِنہٕ۔\n7. تہٕ تٔمۍ دِژ پنُن گۄڈنیُک نیٚچُو، تہٕ لٔٹِتھ لٔگِتھ لٔگِتھ تہٕ تھووُن أکِس منٛگرَس مَنٛز۔ تکیازِ سراءِ منز ٲس نہ یمن ہنز کانہہ جاے۔\n8.\\tتہٕ أتھۍ ملکس منز ٲسۍ کھہس منز رٲژ پننین ریولن پیٹھ نظر تھاوان ٲسۍ۔ {وچھو: یا، رٲژ ہٕندِس واچس}\n9. تہٕ یِمن ہُند فرشتہٕ آو تِمن پیٹھ، تہٕ خداوند سُند جلال دراو تِمن اندۍ پکھۍ، تہٕ تِم گٔیہِ خوفہٕ۔\n10.\\tتہٕ فرشتن ووٚن تِمن زِ خوفہٕ نہٕ گژھُن، یُس سارِنٕے لُکن ہٕندِ خٲطرٕ آسہِ۔\n11. تِکیازِ چُھہ تۅہہِ سٍتـ̡ از دۅہہٕ داؤد سٕندِس شہرس مَنٛز زامُت، یُس مسیح خداوند چُھ۔\n12. تہٕ یہِ آسہِ تۅہہِ خٲطرٕ اکھ نشانی۔ ژیہ وُچھِو شُرِ پلون منز ؤلِتھ ؤلِتھ أکِس منٛگرس منز لٔگِتھ۔\n13.\\tتہٕ اچانک اوس فرشتس سٍتـ̡ آسمانی فوجُک اکھ بٔڈ بٔڈ یُس خدایہِ سٕنز حمد کران اوس تہٕ وونُن،\n14. خدایہ سُند جلال تہٕ زمینس پیٹھ امن تہٕ انسانن خٲطرٕ نیک خواہش۔\n15.\\tتہٕ سپُد یێلہِ فرشتہٕ یِمن نِش جنتس مَنٛز ژٔلِتھ گٔیہِ، پٔرِو اَکھ أکِس سٍتـ̡ وۆن، أسـ̡ وُچھو بیت اللحمس کُن تہِ، تہٕ وُچھو یہِ چیز یُس سپدُن چُھ، یُس خداوند اسہِ زانمُت چُھ۔ {دی شیفرڈز: Gr. the men the Shepherds}\n16. تہٕ تِم آیہِ جلدی سان تہٕ وُچھِکھ مریم، تہٕ یوسف تہٕ بچہٕ أکِس منٛگرَس مَنٛز لٔگِتھ۔\n17.\\tتہٕ ییلہ تِمو وُچھمُت، تِمو کٔر سُہ قول یُس تِمن أمِس شُرس متعلق وننہٕ آمُت اوس۔\n18.\\tتہٕ یِمو سارِوٕے بوزان اوس تِمن کتھن پیٹھ حٲران یِم تِمن چرواہو وَننہٕ آمٕتۍ ٲسۍ۔\n19.\\tمگر مریم تھوو یم سٲری چیز تہ پننس دلس منز سوچان۔\n20.\\tتہٕ گٔیہِ چرواہ واپس، تِمن سارِنٕے چیزن ہٕندِ خٲطرٕ یِم تِمو بوزمٕژ تہٕ وُچھمٕژ ٲس، یِتھ کٔنۍ تِمن وَننہٕ آمٕژ ٲس۔\n21.\\tییلہ شُرِ سٕندِ ختنہ کرنہٕ خٲطرٕ ٲٹھ دۅہ گٔیہ، تٔمِس آو عیسیٰ مسیح ناو وننہٕ، یُس رحمس منز حاملہ گژھنہٕ برونہہ فرشتہ سُند ناو اوس۔\n22. تہٕ ییلہ موسیٰ سٕندِ شریعت مُطٲبق تٔمۍ سٕندِ پاکیزگی ہٕندِ دۅہ مُکمل گٔیہ، تِمو أنۍ سُہ یروشلمس مَنٛز، یُس خداوند سٕندِس برونہہ کُن پیش کرنہٕ خٲطرٕ۔\n23. (یِتھ کٔنۍ زَن خداوند سٕندِس شریعتس مَنٛز لیکھنہٕ آمُت چُھ، یُس پرتھ کانہہ مرد یُس رحم کھولان چُھ، سُہ گژھہِ خداوند سٕندِ خٲطرٕ پاک وننہٕ یُن؛)\n24.\\tتہٕ خداوند سٕندِس شریعتس مَنٛز وننہٕ آمٕژ مُطٲبق قربانی پیش کرٕنۍ، کچھوَن ہُند اکھ جورٕ یا زٕ بچہٕ کبوتر۔\n25.\\tتہٕ وُچھ یروشلمس مَنٛز اوس اَکھ شخٕص یٔمۍ سُند ناو اوس شمعان۔ تہٕ یۅہے شخٕص اوس عادل تہٕ پرہیزگار، یُس اسرٲیلِچ تسلی ہُند انتظار کران اوس، تہٕ روح القدس اوس تس پیٹھ۔\n26. تہٕ روح القدس سٕندِ دٔسۍ آو أمِس ظٲہر کرنہٕ زِ سُہ گژھِ نہٕ خداوند سُند مسیح وُچھنہٕ برونہہ موُت وُچھُن۔\n27. تہٕ سُہ آو روٝحہِ سٍتـ̡ مندرس مَنٛز، تہٕ یێلہِ مٲلِس ماجہ شُر عیسیٰ سٕندِس سٍتـ̡ أنِتھ، یێلہِ شریعت کِس رسمَس مُطٲبِق أمِس سٕندِ خٲطرٕ کٲم کرنہٕ خٲطرٕ،\n28.\\tتێلہِ تُل سُہ پنٕنِس نرِ منز، تہٕ کوٚرُن خدایہ سُند دُعا تہٕ وونُن،\n29.\\tخداوند، وۅنۍ گژھ پنُن خادم پننہِ کلامٕ مُطٲبق امن سان نیرُن:\n30. تکیازِ میانیو أچھو چُھہ تُہند نجات وُچھمُت،\n31. یُس ژے سارِنٕے لُکن ہٕندِس بُتھِس برونہہ کُن تیار کورمُت چھُ۔\n32.\\tغیر قومن ہٕندِس گاشس تہٕ تُہنزِ قوم اسرٲیلٕچ شان ہاونہٕ خٲطرٕ گاش۔\n33.\\tتہٕ یوسف تہٕ تسٕنزِ ماجہ گٔیہِ تِمن چیزن پیٹھ حٲران یِم أمِس مُتلق وننہٕ آمٕتۍ ٲسۍ۔\n34. تہٕ شمعون کٔر تِمن برکت تہٕ ووٚنُن پننہِ ماجہِ مریم، وُچھِو، یہِ {شُر} چُھ اسرٲیلِس مَنٛز واریہن لوٗکن ہٕندِس زوال تہٕ دُبارٕ زندٕ گژھنہٕ خٲطرٕ تیار۔ تہٕ أکِس نشانہٕ خٲطرٕ یٔمِس خلاف کتھ گژھہِ کرنہٕ؛\n35.\\t(آ، تلوار گژھہِ تۅہہِ ہندِس روحس منز تہِ ژٔلِتھ،) یُتھ واریاہن دلن ہٕندِ خیالن ہُند ظٲہِر سپدِ۔\n36.\\tتہٕ اَکھ حنا ٲس یۅسہٕ عسر قبیلٕچ کوٗر ٲس، یۅسہٕ فانوئیل سٕنز کوٗر ٲس، سۅ ٲس واریاہ وٲنسہِ، تہٕ ٲسٕس أکِس خانٛدارس سٍتـ̡ کُنوارِ پٲٹھـ̡ سَتھ ؤری روزان۔\n37.\\tتہٕ سۅ ٲس تقریباً ژورن ؤرین ہٕنز بیواہ ، یۅسہٕ نہٕ مندرٕ منزٕ نیران ٲس بلکہ ٲس رٲژ تہٕ دۅہہٕ روزٕ تہٕ دعاہٕ سٍتـ̡ خدایہِ سٕنز خدمت کران۔\n38.\\tتہٕ تٔمۍ یِتھٕ سٍتـ̡ یِتھٕ پٲٹھـ̡ خداوند سُند شُکر ادا کٔرِتھ، تہٕ یِمن سارِنٕے سٍتـ̡ یِم یروشلمس مَنٛز نجات ژھاران ٲسۍ۔ {یروشلم: یا، اسرائیل}\n39.\\tتہٕ یێلہِ تِمو خداوند سٕندِ شریعت مُطٲبق سارِوٕے کُن کٲم کٔر، تِم گٔیہِ گلیل کُن پننِس شہرس ناصرتس مَنٛز واپس۔\n40. تہٕ شُر گوٚو بٔڑِتھ، تہٕ رٔژ دٲیرٕ سٍتـ̡ بٔرِتھ تہٕ خدایہِ سُند فضل اوس أمِس پیٹھ۔\n41. وۅنۍ اوس تٔمۍ سُند مول موج پریتھ وریہِ فسح کِس عید کِس موقعس پیٹھ یروشلم گژھان۔\n42. تہٕ ییلہ سُہ بَہہ وُہُر اوس، تِم گٔیہِ دعوتُک رسم مُطٲبِق یروشلم کُن۔\n43. تہٕ ییلہ تِمو دۅہ پوٗرٕ کٔرِتھ، یێلہِ تِم واپس آو، شُر عیسیٰ مسیح روٗد یروشلمس مَنٛز پتھ کُن۔ تہٕ یوسف تہٕ تٔمۍ سٕنزِ ماجہ ٲس نہٕ اتھ متعلق خبر۔\n44.\\tمگر تِمو گٔیہِ أمِس صحبتس منز آسُن، أکِس دۅہُک سفر گٔیہِ۔ تہٕ تِمو ژھانڈ أمِس پننین رشتہ دارن تہٕ واقفن منٛز۔\n45. تہٕ ییلہ نہٕ سُہ لٔبِتھ تِمو دُبارٕ یروشلمس کُن واپس أمِس ژھانڈنہٕ خٲطرٕ۔\n46.\\tتہٕ سپُد یہ زِ تریہ دۅہہ پَتہٕ وُچھ سُہ مندرس منز، ڈاکٹرن منز بِہتھ، دۅشوے ٲسۍ بوزان تہٕ تمن سوال پرژھان۔\n47.\\tتہٕ یُس أمِس بوزان اوس تٔمۍ سٕندِس فہم تہٕ جوابس پیٹھ حٲران گٔیہِ۔\n48.\\tتہٕ ییلہ تِمو أمِس وُچھ، تِم گٔیہِ حٲران: تہٕ تسٕنزِ ماجہ ووٚن أمِس زِ نیچو، ژے کیازِ کٔر اسہِ سٍتـ̡ یِتھ سٍتـ̡ س وُچھ، چانہِ مول تہٕ مے چھُکھ ژےٚ غم۔\n49.\\tتہٕ تٔمۍ ووٚن تِمَن زِ ژے کِتھہٕ کٔنۍ چھُ مےٚ ژھانڈان؟ ژیہ چھکھ نہ یہ زِ میہ گژھہِ پننس مٲلۍ سٕندِس کاروبارس متعلق آسُن؟\n50.\\tتہٕ تِمو اوس نہٕ سُہ کلام سمجِتھ یُس تٔمۍ تِمن سٍتـ̡ کتھ کٔرمٕژ۔\n51. تہٕ سُہ ووت تِمن سٍتـ̡ تہٕ آو ناصرت تہٕ روٗد تِمن ہٕندِس تابع۔\n52.\\tتہٕ حضرت عیسیٰ علیہ السلام ہٕندِس حکمتس تہٕ قدس سٍتـ̡ ہُریوو تہٕ خدایہ سٕندِس سٍتـ̡ تہٕ انسانس سٍتـ̡ ہُریر۔ {قد: یا، وٲنسہِ}","1. وۅنۍ اوس ٹائبیریس سیزر سٕندِ دورِ حکومتہٕ کِس پنٛدٲہمس ؤریس منز، پونٹیئس پیلاطس یہوداہُک گورنر، تہٕ ہیرودیس اوس گلیلُک ٹیٹرارک، تہٕ تٔمۍ سُند بوے فلپ ٹیٹرارک تہٕ ٹراکونائٹس کِس علاقس منز، تہٕ لیسانیاس ابیلینُک ٹیٹرارک، {ٹیٹرارک: یا، ژورن صوبن ہُند گورنر}\n2. اناس تہٕ قیافہ بٔڈۍ پادٕرۍ آسنہٕ کِنۍ، خدایہِ سُند کلام آو یوحنا سٕندِس نیچوِس زکریا سٕندِس نیچوِس بیابانس مَنٛز۔\n3. تہٕ سُہ آو اردن کِس سٲرۍسٕے ملکس مَنٛز، گۅنہن ہٕنزِ معٲفی خٲطرٕ توبہ کرنٕچ تبلیغ کٔرِتھ۔\n4. یِتھ کٔنۍ زَن یِسعیاس نبی سٕندِس کلامَن ہٕنزِ کتابہِ مَنٛز لیکھنہٕ آمُت چھُ، یُس بیابانَس مَنٛز فریاد دِنہٕ وٲلِس سٕنز آواز چھُ، خداوند سٕنز وتھ تیار کرٕن، تٔمۍ سٕنزِ وَتھ کٔرِو سیدٕ۔\n5. پرٮ۪تھ وادی گژھہِ بٔرِتھ تہٕ پرٮ۪تھ پہاڑ تہٕ بالہٕ یِن بۄن کرنہٕ۔ تہٕ ٹیڑھ گژھن سیود کرنہٕ، تہٕ کھرٕ وتہٕ گژھن ہموار کرنہٕ۔\n6. تہٕ سارِنٕے ماز گژھہِ خدایہِ سٕنز نجات وُچھان۔\n7.\\tتێلہِ ووٚن تٔمِس بپتسمہ دِنہٕ خٲطرٕ یُس أمِس بپتسمہ دِنہٕ خٲطرٕ برونہہ کُن آمُت اوس، اے سانپَن ہٕنزِ نسل، یێمہِ چُھہ ژلہٕ یِنہٕ وٲلِس قہر نِش ژلنہٕ خٲطرٕ خبردار کورمُت؟\n8. تێلہِ کٔرِو توبہٕ لایق پھل دِنہٕ، تہٕ پانس اندر گژھ نہٕ یہ ونُن زِ اسہِ چُھہ ابراہیم پننِس مٲلس سٍتـ̡ ، کیازِ بہٕ چُھس ژے ونان زِ خدا چُھہ یِمن کنن سٍتـ̡ ابراہیمس نِش اولاد پٲدٕ کرنُک قٲبل۔ {لایق: یا، مِلُن}\n9. تہٕ وۅنۍ تہِ چُھ کُلٮ۪ن ہٕندِس موٗلس پیٹھ کُلہٕ تراونہٕ آمُت: تَمہِ کِنۍ چُھ پرٮ۪تھ کُل یُس نہٕ اصل پھل دِوان چُھ، سُہ چُھ ژٹنہٕ یوان تہٕ نارس مَنٛز تراونہٕ یِوان۔\n10.\\tتہٕ لوکو پرژھ أمِس زِ أسۍ کیا کرو تیلہٕ؟\n11. سُہ چُھ جواب دِوان تہٕ تِمن ونان زِ یُس زٕ کوٹ چُھ، سُہ دِیُن أمِس دِنہٕ یُس نہٕ کانہہ تہِ آسہِ۔ تہٕ یُس ماز آسہِ، سُہ گژھہِ یۅہے کرُن۔\n12. پَتہٕ آو پبلکن تہِ بپتسمہ دِنہٕ خٲطرٕ، تہٕ وونُکھ أمِس آقا، أسۍ کیا کٔرِو؟\n13.\\tتہٕ تٔمۍ ووٚن تِمن سٍتـ̡ یُس تۅہہِ مقرر کرنہٕ آمُت چُھ، تمہِ سٍتـ̡ چُھہ نہٕ تُہٕندِس سٍ\n14.\\tتہٕ سپاہِ تہِ ووٚن أمِس نِش تہٕ اسہِ کیا کرُن؟ تہٕ تٔمۍ ووٚن تِمَن زِ کٲنسہ تہِ نفرس سٍتـ̡ تشدد کرُن، نہ کرو اپُز الزام لگاونہٕ۔ تہٕ روزِو پننہِ تنخواہ پیٹھ مطمعین۔ {تشدد کرو...: یا، کانہہ تہِ انسان تراوُن نہٕ خوفس منز} {اجرت: یا، الاؤنس}\n15.\\tتہٕ یێلہِ لُکھ وۅمید ٲس، تہٕ سارِنٕے لُکھ اوس یوحنا سٕندِس دِلس مَنٛز سوچان، چاہے سُہ مسیح اوس، کِنہٕ نہ۔ {توقعس منز: یا، سسپنس منز} {مَضموٗن: یا، استدلال، یا، بَحَث}\n16.\\tیوحنا دیُت جواب تہٕ وونُن سارِنٕے سارِنٕے سٍتـ̡ بہٕ چُھس ژے آبہٕ سٍتـ̡ بپتسمہ دِوان۔ مگر میانہِ کھۅتہ زیادہ طاقتور یُس یمۍ سٕندِ کھورِ ہُند لوٚٹ بہٕ چھُس نہٕ یلہٕ تراونس لایق: سُہ کرِ ژے روح القدس تہٕ نارٕ سٍتـ̡ بپتسمہ دِنہٕ:\n17.\\tیمۍ سُند پنُن پنُن پنُن فرش صاف کرِ، تہٕ سُہ کرِ پنُن فرش صاف کٔرِتھ، تہٕ کٕنُک جمع کرِ۔ مگر سُہ چُھس نارٕ سٍتۍ دزان نہٕ یُس نہٕ بٔرِتھ۔\n18.\\tتہٕ بییہ واریاہ کتھٕ کٔر تٔمۍ سٕنزِ نصیحتس مَنٛز تبلیغ۔\n19.\\tمگر ہیرودیس سٕندِس بٲے فلپس سٕنزِ زنانہِ ہیرودیاس سٕنزِ زنانہٕ خٲطرٕ تہٕ تِمن سارِنٕے بُراین خٲطرٕ یِم ہیرودیشن کٔرۍمٕتۍ،\n20.\\tسارِوٕے کھۄتہٕ زیادٕ یہ زِ تٔمۍ کٔر جان جیلس منز بند۔\n21. وۅنۍ ییلہ سارِنٕے لُکھ بپتسمہ دِنہٕ آو، یہِ سپُد عیسیٰ مسیح تہِ بپتسمہ دِنہٕ تہٕ دُعا کرنہٕ سٍتـ̡ آو اسمانس کھولنہٕ،\n22.\\tتہٕ روح القدس ووت أمِس پیٹھ کۅتر ہٕندۍ پٲٹھۍ، تہٕ اسمانہٕ پیٹھٕ دراو اکھ آواز، یُس وَنُن زِ ژٕ چُھکھ میون پیاری نیٚچُو۔ ژے منز چُھس بہٕ خوش گومُت۔\n23. تہٕ حضرت عیسیٰ علیہ السلام گۆو ترہ وُہُر وٲنسہِ، یُس یوسف سُند نیچو اوس، یُس ہیلی سُند نیچو اوس،\n24.\\tیُس مَتتھ سُند نیچو اوس، یُس {لیوی سُند نیٚچُو} اوس، یُس {میلچی سُند نیٚچُو} اوس، یُس {یُس یوسفُن نیچو} اوس، یُس {یوسفُن نیچو} اوس،\n25.\\tیُس متاتھیاس سُند نیچو اوس، یُس {آموس سُند نیچو} اوس، یُس {نعوم سُند نیچو} اوس، یُس {اسلی سُند نیچو} اوس، یُس ناگ سُند نیچو اوس،\n26.\\tیُس ماتھ سُند نیچو اوس، یُس {متاتھیاسُن} سُند نیچو اوس، یُس {سمیعی سُند نیچو} اوس، یُس {یوسفُن نیچو} اوس، یُس یہوداہ سُند {نیچو} اوس،\n27.\\tیُس جوانا سُند نیچو اوس، یُس {ریسا سُند نیچو} اوس، یُس {زوروبابیل سُند نیچو} اوس، یُس نیری سُند {نیچو} اوس، یُس نیری سُند نیچو اوس،\n28.\\tیُس میلچی سُند نیچو اوس، یُس عدی سُند {نیچو} اوس، یُس {کُسم سُند نیچو} اوس، یُس {ایلمودامُن} سُند نیچو اوس، یُس {ایر سُند نیچو} اوس،\n29.\\tیُس یوس سُند نیچو اوس، یُس {الیعزر سُند نیچو} اوس، یُس {یورِمُن} سُند نیچو اوس، یُس {لیوی سُند نیچو} اوس، یُس {لیوی سُند نیچو} اوس،\n30.\\tیُس {شمعون سُند نیٚچُو} اوس، یُس {یہوداہ سُند نیچو} اوس، یُس {یوسُن} سُند نیچو اوس، یُس {الیاقیمُن} سُند نیچو اوس، یُس {الیاقیمُن نیچو} اوس،\n31. یُس میلیا سُند نیچو اوس، یُس مینان سُند نیچو اوس، یُس متاتھا سُند نیچو اوس، یُس ناتھن سُند نیچو اوس، یُس داؤد سُند نیچو اوس، یُس داؤد سُند نیچو اوس،\n32.\\tیُس یسیٰ سُند نیچو اوس، یُس عبید سُند نیچو اوس، یُس {بوز سُند نیچو} اوس، یُس {سلمن سُند نیچو} اوس، یُس {ناسن سُند نیچو} اوس،\n33.\\tیُس امیناڈاب سُند نیچو اوس، یُس {اَرَم سُند نیٚچُو} اوس، یُس فارس سُند نیچو اوس، یُس یہوداہ سُند {نیٚچُو} اوس،\n34. یُس یعقوب سُند نیچو اوس، یُس اسحاق سُند نیچو اوس، یُس ابراہیم سُند نیچو اوس، یُس ثارا سُند نیچو اوس، یُس ناخور سُند نیچو اوس۔\n35.\\tیُس سَروُخ سُند {نیچو} اوس، یُس {راگُوُن} سُند نیچو اوس، یُس {ہیبر سُند نیچو} اوس، یُس {سالا سُند نیچو} اوس،\n36.\\tیُس کاینان سُند نیچو اوس، یُس {ارفکسادُن} سُند نیچو اوس، یُس {سیم} سُند نیچو اوس، یُس {نوے سُند نیچو} اوس، یُس {لامیخُن نیچو} اوس،\n37.\\tیُس متھوسلا سُند نیچو اوس، یُس حنوک سُند نیچو اوس، یُس {نیچو} اوس یُس مللیل سُند نیچو اوس، یُس کینان سُند نیچو اوس، یُس {کینان سُند نیچو} اوس،\n38.\\tیُس عینوس سُند نیچو اوس، یُس سیٹھ سُند {نیچو} اوس، یُس {آدم سُند نیچو} اوس، یُس خدا سُند {نیٚچُو} اوس۔","1. تہٕ عیسیٰ مسیح روٝحہِ پاک سٍتـ̡ بٔرِتھ آو اردن پیٹھٕ واپس، تہٕ آو روٝحہِ سٍتـ̡ بیابانس مَنٛز نِنہٕ،\n2. ژتٲجی دۅہن شیطان سٕندِس فتنہ سٍتـ̡ ۔ تہٕ تِمن دۅہن اوس نہٕ تٔمِس کیٚنٛہہ تہِ کھٮ۪وان: تہٕ ییٚلہِ یِم ختم گٔیہِ، پتہٕ اوس أمِس فاقہٕ کھٮ۪وان۔\n3. تہٕ شیطانن ووٚن أمِس زِ اگر تہٕ ژٕ خدایہِ سُنٛد نیٚچُو چھُ، تیٚلہِ دِیُن یہِ کٔنہِ روٹی بَناوُن حُکُم۔\n4. تہٕ حضرت عیسیٰ علیہ السلام دِیُت أمِس جواب دِتھ زِ یہِ چُھ لیکھنہٕ آمُت زِ انسان روزِ نہٕ صرف روٹی سٍتـ̡ بٔلکہِ خدایہِ سٕندِ پرٮ۪تھ کُنہِ کلامَس سٍتـ̡ زندٕ۔\n5.\\tتہٕ شیطانن ہٲو أمِس أکِس تھدِس بالس پیٹھ نِتھ تہٕ ہٲوِن أمِس أکِس لمحس منز دنیاہٕچ سارِنٕے بادشٲہی ۔\n6.\\tتہٕ شیطانن ووٚن أمِس زِ بہٕ دِیہٕ ژےٚ سٲرٕے طاقت تہٕ تِمن ہُند جلال تہٕ یِمن ہُند جلال دِنہٕ۔ تہٕ یٔمِس بہٕ دِیہٕ بہٕ یہِ دِنہٕ۔\n7. تێلہِ چُھہ ژے میانہِ پوٗزا کٔرِو، سارِنٕے آسہِ تُہٕندِس سٍتـ̡ ۔ {پوٗزا کٔرِو: نتہٕ پیوٚو میانہِ برونہہ کُن}\n8.\\tتہٕ حضرت عیسیٰ علیہ السلام دِیُت جواب تہٕ وونُن زِ یێلہِ بێیہِ پَتہٕ نیرُن، شیطان، تێلہِ چُھہ لیکھنہٕ آمُت، تہٕ تێہہ کٔرِو خداوند پنُن خدا، تہٕ تٔمِس سٍتـ̡ کرٕنـ̡ عبادت کرٕنـ̡ ۔\n9. تہٕ سُہ اوٚن سُہ یروشلم، تہٕ تھووُن سُہ ہیکل کِس تینتٲلس پیٹھ، تہٕ وونُن أمِس زِ اگر تہٕ خدا سُند نیٚچُو چھُو، تیٚلہِ تراوُن پنُن پان اَتہِ پیٹھ۔\n10.\\tیِہ چُھہ لیکھنہٕ آمُت، سُہ دِیہِ تۅہہِ ہٕندِس فرشتن ہُند ذمہٕ دِنہٕ۔\n11.\\tتہٕ تِمن ہٕندِس اتھس مَنٛز تُلِتھ تُہٕندِس اتھس منز، نتہٕ کُنہِ ساتہٕ کُنہِ تہِ وِزِ ژیہ کُنہِ سٍتـ̡ پَنُن کھۄر ٹاس دِنہٕ۔\n12. تہٕ حضرت عیسیٰ علیہ السلام ووٚن أمِس جواب دِتھ زِ یہِ چُھہ وننہٕ آمُت زِ ژے گژھ نہٕ خداوند پنُن خدایہ آزماونہٕ۔\n13.\\tتہٕ ییلہ شیطانن سورے فتنہ ختم کٔر، سُہ ژاو أمِس نِش أکِس کالس خٲطرٕ۔\n14. تہٕ عیسیٰ مسیح آو روح سٕندِس طاقتہٕ سٍتـ̡ گلیلس مَنٛز واپس، تہٕ تٔمۍ سٕنز شہرت گٔیہِ أندۍ پٔکۍ سٲرۍسٕے علاقس مَنٛز۔\n15.\\tتہٕ سُہ اوس تِہندِس عبادت خانن مَنٛز پرناوُن، سارِنٕے سٍتـ̡ سٍتـ̡ پر\n16.\\tتہٕ سُہ آو ناصرت، یتہِ أمِس پرورش ٲس کٔرمٕژ، تہٕ سُہ اوس سبت دۅہہٕ عبادت خانس مَنٛز تہٕ پرنہٕ خٲطرٕ کھڑا گومُت۔\n17.\\tتہٕ تٔمِس آو پیغمبر عیسیٰ سٕنز کتاب دِنہٕ۔ تہٕ ییلہ تٔمۍ کتاب کھولو، تمس لٔب سۄ جاے ییتہ یہ لیکھنہٕ آمت اوس،\n18. خداوند سُند روح چُھہ میہ پیٹھ، کیازِ تٔمۍ چُھہ میہ غریبن تام انجیل واتناونہٕ خٲطرٕ مسح کورمُت۔ تٔمۍ چُھ مے سوزمُت دِل شفا دِنہٕ خٲطرٕ، قٲدٮ۪ن نجات دِنٕچ تبلیغ کرنہٕ خٲطرٕ، تہٕ اَنٮ۪ن ہٕندِس گاش بحال کرنہٕ خٲطرٕ، یِمن زخمن ہٕندِس آزاد کرنہٕ خٲطرٕ سوزمُت،\n19.\\tخداوند سٕندِس قابل قبول ؤریس ہنز تبلیغ کرٕنۍ۔\n20.\\tتہٕ تٔمۍ کٔر کتاب بند، تہٕ تٔمۍ دِژ بییہ وزیرس تہٕ بیوٹھ۔ تہٕ یِمن سارِنٕے یِمن ہٕنزِ نظرٕ ٲس أمِس کُن گٔژھمٕژ۔\n21. تہٕ تٔمۍ ہیوٚت تِمن وَنُن زِ یہِ دۅہ چُھ یہِ صحیفہٕ تہندٮ۪ن کنن مَنٛز پوٗرٕ سپدان۔\n22.\\tتہٕ سارِوٕے گٔیہِ أمِس گوٲہی تہٕ تٔمۍ سٕندِس ٲسِس منزٕ نیرن وٲلِس مہربان کلامس پیٹھ حٲران گٔیہِ۔ تہٕ تِمو ووٚن، کیا یہِ چھُنہٕ یوسف سُند نیچو؟\n23.\\tتہٕ تٔمۍ ووٚن تِمَن یِمن وَنُن یِہ محاورہٕ، طبیب، پَنُن پَنُن شفا دِیُن، یُس تہِ اسہِ کفرناؤمس مَنٛز بوزمُت چُھ، سُہ تہِ کرُن یێلہِ تہِ کٔرِو پننِس ملکس مَنٛز۔\n24.\\tتہٕ وۆنُن زِ بہٕ چُھس وَنُن زِ کانہہ تہِ نبی چُھ نہٕ پننِس ملکس مَنٛز قبول سپدان۔\n25.\\tمگر بہٕ چُھس ژیہ اکھ پزر ونان زِ الیاس سٕندِس زمانس مَنٛز آسہٕ واریاہ بیواہ اسرٲیلِس مَنٛز، ییلہ اسمانس تریہ ؤری تہٕ شیہ ریتن بند کرنہٕ آو، ییلہ سٲرۍسٕے زمینس منز بٔڈ قحط اوس۔\n26.\\tمگر یِمو منزٕ اوس نہٕ الیاس سوزنہٕ آمُت، سوائے سریپتاہس کُن، یُس سِدونُک اکھ شہر، أکِس زنانہِ نِش یۅسہٕ بیواہ ٲس۔\n27.\\tتہٕ واریاہ کوڑھ ٲسۍ اسرٲیلس مَنٛز الیسیس پیغمبر سٕندِس زمانس مَنٛز۔ تہٕ یِمو منزٕ آو نہٕ کانہہ تہِ پاک کرنہٕ، شامُک نعمان بچٲوِتھ۔\n28.\\tتہٕ یِمو سارِوٕے یہِ کتھ بوزِتھ گٔیہِ غصہٕ سٍتـ̡ بٔرِتھ،\n29.\\tتہٕ ووٚتھ تہٕ دِژُن أمِس شہرٕ منزٕ نٮ۪بر تہٕ نِیوُن سُہ بالہٕ کِس نِش یتھ پیٹھ تِہُند شہر اوس بناونہٕ آمُت، یُتھ تِم أمِس کلہٕ کُن ترٛٲوِتھ۔ {برو: یا، ایج}\n30.\\tمگر سُہ گۆو تِمن منزٕ پٔکِتھ پَنُن وَتھ،\n31.\\tتہٕ آو گلیل کِس أکِس شہرس کفرناؤمس مَنٛز تہٕ سبت دۅہہٕ ہیچھناوُن تِمَن ہیچھناوُن۔\n32.\\tتہٕ تِم گٔیہِ تٔمۍ سٕندِس نظریہٕ سٍتـ̡ حٲران: تکیازِ تٔمۍ سُند کلام اوس طاقتہٕ سٍتـ̡ ۔\n33.\\tتہٕ یہِ عبادت خانس مَنٛز اوس اَکھ شخٕص، یٔمِس أکِس ناپاک شیطان سُند روح اوس، تہٕ تٔمِس بَڑِ آوازٕ سٍتـ̡ کرٛٮ۪کھ دِژٕن،\n34.\\tیہ ونُن زِ اسہِ کُنہ اسہِ کیا چُھہ ژے سٍتـ̡ سٍتـ̡ عیسیٰ مسیح ناصری سٍتـ̡ ژیہ چھکھ اسہِ تباہ کرنہِ آمت؟ بہٕ چُھس ژٕ زانان ژٕ کُس چُھ؛ خدایہ سُند پاک۔ {لیٹ...: یا، دور}\n35.\\tتہٕ حضرت عیسیٰ علیہ السلام دِژ أمِس ملامت تہٕ وونُن زِ پَنُن رٔٹِو تہٕ أمِس نِش نٮ۪بر نیرُن۔ تہٕ ییٚلہِ شیطانن أمِس درمِس منٛز ترٛٲو، سُہ دراو أمِس منٛز، تہٕ دِتُن نہٕ أمِس دَگ دِنہٕ۔\n36.\\tتہٕ تِم سارِوٕے گٔیہِ حٲران تہٕ وَنُن پانہٕ أکِس سٍتـ̡ کتھ باتھ کٔرِتھ، یہِ کیا چُھہ لفظ! تِکیازِ سُہ چُھ اِختِیار تہٕ طاقتہٕ سٍتـ̡ ناپاک روحن حُکُم دِوان، تہٕ تِم چِھ نیبر نیران۔\n37.\\tتہٕ تٔمۍ سٕنز شہرت گٔیہِ أندۍ پٔکھۍ مُلکہٕ کِس پرٮ۪تھ جایہ۔\n38.\\tتہٕ سُہ ووٚتھ عبادت خانہٕ منزٕ تہٕ ژاو شمعون سٕندِس گرس منز۔ تہٕ سائمن سٕنزِ زنانہِ ہٕنز موج گٔیہٕ سٮ۪ٹھاہ تپھ۔ تہٕ تِمو کٔر أمِس خٲطرٕ التجا ۔\n39.\\tتہٕ سُہ کھڑا أمِس کُن تہٕ دِتُن تپھ۔ تہٕ یہ تروو أمِس تہٕ فوراً ووٚتھ تہٕ کٔرٕن تِمن ہٕنز خدمت۔\n40. وۅنۍ ییلہ آفتاب لوسُن، تم سٲری یِم مختلف بیمارین منز مبتلا ٲسۍ، تم أنِتھ تمس نِش۔ تہٕ تٔمۍ تھووُن تِمن منز پرٮ۪تھ أکِس پیٹھ اتھہٕ، تہٕ کوٚرُن تِمن شفا۔\n41. تہٕ شیطان تہِ دراو واریاہو منز، کرٛٮ۪کھ دِتھ تہٕ وَنُن زِ تُہۍ چُھکھ مسیح خدا سُند نیٚچُو۔ تہٕ تٔمۍ دِژ نہٕ تِمن کتھ کرنہٕ خٲطرٕ، تِکیازِ تِمن ٲس پتاہ زِ سُہ اوس مسیح۔ {کتھ کرُن...: یا، یہ ونُن زِ تم ٲسۍ تس مسیح زانان}\n42.\\tییلہ دۅہ آو سُہ دراو تہٕ أکِس ریگستانس مَنٛز ووت تہٕ لُکھ لُکھ أمِس ژھانڈان تہٕ أمِس نِش آو تہٕ رُکٲوِتھ تہٕ رُکٲوِتھ زِ سُہ گژھِ نہٕ تِمن نِش نیرُن۔\n43. تہٕ تٔمۍ ووٚن تِمن زِ بہٕ پزِ باقین شہرن تہِ خدایہِ سٕنز بادشٲہی ہٕنز تبلیغ کرٕنۍ، تِکیازِ بہٕ چُھس سوزنہٕ آمُت۔\n44. تہٕ تٔمۍ کٔر گلیل کِس عبادت خانن مَنٛز تبلیغ۔","1. تہٕ سپُد یہِ زِ یێلہِ لُکھ خدایہِ سُند کلام بوزنہٕ خٲطرٕ أمِس پیٹھ دباو دِیُت، سُہ اوس جنیسارٹ کِس جھیلس نِش کھڑا ،\n2.\\tتہٕ وُچھ زٕ جہازٕ جھیلس نِش کھڑا مگر گاڈٕ ہٲرۍ ٲسۍ تِمو منزٕ نیبر تہٕ ٲسۍ جال چھلان۔\n3.\\tتہٕ سُہ ژاو أکِس جہازس منز، یُس شمعون سُند اوس، تہٕ دُعا کٔرِن أمِس دُعا زِ سُہ کٔرِن زمینہٕ منزٕ رژھ کھنڈ دِنہٕ۔ تہٕ سُہ بیوٹھ تہٕ لوکن ہیچھناوُن جہازٕ منٛز۔\n4.\\tوۅنۍ ییلہ سُہ کتھ کٔرِتھ درٛاو، تٔمۍ ووٚن شمعنس زِ سٍتـ̡ ژٔلِتھ\n5.\\tتہٕ شمعون ووٚن أمِس جواب دِتھ، مالک، أسۍ کٔر سارِوٕے رٲژ محنت، تہٕ چُھس نہٕ کیٚنٛہہ تہِ نِمُت، توتہِ چُھس چانہِ کلامَس سٍتـ̡ بہٕ جال تراوُن۔\n6. تہٕ ییلہ تمو یہ کٔرۍ، تمو رٔٹۍ گاڈن ہُند اکھ بٔڈ تعداد: تہٕ تِمن ہٕندِس جالس بریک۔\n7.\\tتہٕ تِمو دِژ تِمن ہٕندِس شٔریٖکَس اِشارٕ، یِم بیٚیِس جہازس منز ٲسۍ، زِ تِم گژھن یِن تہٕ تِمن مدد۔ تہٕ تِم آیہ، تہٕ دۅشوے جہازٕ بٔرِتھ تہ تِم ہیوٚتُن ڈوبُن۔\n8.\\tییلہ شمعون پطرس وُچھ، سُہ پیوٚو عیسیٰ سٕندِس کۅٹھن پیٹھ تہٕ وونُن، میہ نِش گژھ دور۔ تکیازِ بہٕ چُھس اکھ گۅنہگار انسان، اے خدا۔\n9.\\tتکیازِ سُہ اوس حیران، تہٕ تس سٍتۍ موجود سارِنٕے گاڈَن ہٕندِس ڈرٛافٹس پیٹھ یِم تِمو نِمٕتۍ ٲسۍ۔\n10.\\tیِتھے پٲٹھـ̡ یعقوب تہٕ یوحنا سٕندِ نیچوِ، یِم شمعنس سٍتـ̡ شریک ٲسۍ۔ تہٕ حضرت عیسیٰ علیہ السلام ووٚن شمعنس زِ خوفہٕ نہٕ گژھ۔ اَمہ پتہٕ کٔرِو تُہۍ نفرن رَٹان۔\n11. تہٕ ییلہ تِمو پنٕنۍ جہازٕ زمینس پیٹھ أنۍ، تِمو ترٲوۍ سارِنٕے تہٕ أمِس پتہٕ۔\n12.\\tتہٕ سپُد یێلہِ سُہ أکِس شہرس مَنٛز اوس، وُچھ أکِس کوڑھس سٍتـ̡ بٔرِتھ انسان، یُس عیسیٰ مسیح سٕندِس بُتھِس پیٹھ پیوٚو تہٕ تٔمِس کٔرٕن التجا کٔرِتھ وونُن، خداوند، اگر ژٕ چاہِ، تہٕ ژٕ ہێکہٕ مے پاک کٔرِتھ۔\n13. تہٕ تٔمۍ تروو پنُن اَتھٕ تہٕ کوٚرُن أمِس اَتھٕ تہٕ وونُن، بہٕ کرٕ ژٕ پاک۔ تہٕ فوراً ژاو کوڑھ أمِس نِش۔\n14.\\tتہٕ أمِس دِژ أمِس حکم زِ سُہ کٔرِن کٲنسہ تہِ کٲنسہ تہِ وَنُن، مگر گژھ تہٕ پادٕرِس نِش ہٲوِن پنُن پان تہٕ موسىٰ سٕندِ حُکُم مُطٲبِق کٔرِن تِمن ہٕنزِ گوٲہی دِنہٕ خٲطرٕ۔\n15.\\tمگر یوت یوت تٔمۍ سٕنز شہرت گٔیہ، تہٕ بٔڈۍ لٔگۍ بٔڈۍ یِمن ہٕنزِ بیماریَن ہٕندِ دٔسۍ شفا دِنہٕ خٲطرٕ۔\n16. تہٕ سُہ ژاو بیابانس مَنٛز، تہٕ کٔرٕن دُعا۔\n17.\\tتہٕ یہِ سپُد أکِس خاص دۅہٕ، یێلہِ سُہ ہیچھناوان اوس، یێلہِ فریسی تہٕ شریعت ہٕندِ ڈاکٹر بِہِتھ ٲسۍ، یِم گلیل، یہوداہ تہٕ یروشلم کِس پرٮ۪تھ شہرو منزٕ نیران ٲسۍ، تہٕ خداوند سُند طاقت اوس یِمن شفا دِنہٕ خٲطرٕ موجود۔\n18.\\tتہٕ وُچھِتھ اوٚن مردو أکِس بسترس منز اکھ نفر یُس فالج اوس نِنہٕ آمُت، تہٕ تِمو ژھانڈان زِ أمِس انٛدرٕ أنِتھ تہٕ أمِس برونہہ کُن تھووُن۔\n19.\\tتہٕ ییلہ نہٕ تِمن ہٕندِس بٔڈِس سٍتـ̡ کُنہِ سٍتـ̡ أنِتھ، تِمو گٔیہِ مکانس پیٹھ، تہٕ ترووُن سُہ کُنہِ سٍتـ̡ عیسیٰ ہس برونہہ کُن۔\n20. تہٕ ییلہ تٔمۍ تِہُند ایمان وُچھ، تٔمۍ ووٚن أمِس زِ انسان، تُہند گۅناہ چُھہ ژے معاف۔\n21.\\tتہٕ کاتب تہٕ فریسیو ہیوٚت استدلال کرُن زِ یہِ کُس چُھ یُس کُن کُس ہیکہِ گۅنہہ معافی دِتھ، مگر صرف خدایہ؟\n22. مگر ییلہ حضرت عیسیٰ علیہ السلام تِہٕندِس خیالس وُچھِ، تٔمۍ ووٚن تِمن جواب دِتھ زِ تۅہہِ کیا وجہ چُھہ دِلَس مَنٛز؟\n23.\\tیہ ونُن چھا سہل زِ چانہِ گۅناہ گژھہِ معاف۔ یا ونُن، تھوٚد تھوٚد تہٕ پکُن؟\n24. مگر یێلہِ تۅہہِ زانہِ زِ انسان سٕندِس نیٚچوِس چُھ زمینس پیٹھ گۅنہٕ معافی دِنُک اختیار حٲصِل کٔرِتھ، (تٔمۍ ووٚن فالج وٲلِس بیمارس سٍتـ̡ )بہٕ چُھس ژے ونان زِ وۅتھٕ وُتھ، تہٕ تُلِو پنُن کُنہِ\n25.\\tتہٕ سُہ ووٚتھ یِمن برونہہ کُن، تہٕ تُل یُس تٔمِس پیٹھ لٔگِتھ تہٕ خدایہ سٕندِس حمد کٔرِتھ دراو پننِس گرس کُن۔\n26. تہٕ تِم گٔیہِ سارِوٕے حٲران، تہٕ تِمو کٔر خدایہِ سٕنز حمد تہٕ خوفہٕ سٍتـ̡ بٔرِتھ وونُن، أسـ̡ از تام عجیب چیز وُچھمٕتۍ۔\n27.\\tیِمو کامہِ پَتہٕ وُچھ سُہ درٛاوُن، تہٕ وُچھُن لیوی ناوُک اکھ پبلِکن یُس رسم و رواج رٔٹِتھ بِہِتھ اوس۔\n28. تہٕ سُہ ترٲوِتھ سارِنٕے سٍتـ̡ ووٚتھ، تہٕ أمِس پَتہٕ پَتہٕ۔\n29.\\tتہٕ لیوی ین بنوو أمِس پننِس گرس مَنٛز اکھ بٔڈ دعوت: تہٕ تِمن سٍتـ̡ بِہتھ تہٕ باقین ہٕنز بٔڈ صحبت۔\n30.\\tمگر تِہٕندِس کاتب تہٕ فریسیو کٔر تٔمۍ سٕندٮ۪ن شاگردن خلاف بڑبڑاوان زِ ژیہ کیازِ چھِو پبلکنن تہٕ گۅنہگارن سٍتـ̡ کھیوان تہٕ چیوان ؟\n31.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمن جواب دِتھ یِمن ہُند طبیبُک ضوروٗرَتھ چُھہ نہٕ۔ مگر تم یم بیمار چھہِ۔\n32. بہٕ آو نہٕ نیکوکارن بُلکہِ گۅنہگارن توبہ کرنہٕ خٲطرٕ۔\n33. تہٕ تِمو ووٚن أمِس زِ یوحنا سٕندِ شٲگِر کیازِ چھِ اکثر روزٕ تھاوان، تہٕ دُعا کران تہٕ یِتھے پٲٹھۍ چھِ فریسیَن ہٕندِس شٲگِرِس روزٕ تھاوان۔ مگر تُہۍ چھِو کھٮ۪وان تہٕ چٮ۪وان؟\n34.\\tتہٕ تٔمۍ ووٚن تِمَن زِ مہرازٕ آسہِ تِمن سٍتـ̡ مہرازٕ سٍتـ̡ روزٕ تھاوُن؟\n35.\\tمگر یِم دۅہ یِن یِمن نِش مہرازٕ نِش نِنہٕ، تہٕ تِمن دۅہن روزٕ روزُن۔\n36. تہٕ تٔمۍ کٔر تِمن خٲطرٕ اکھ تمثیل تہِ۔ کانہہ تہِ انسان چھہ نہ نوِ پلوک اکھ ٹُکرہ پرانہِ پیٹھ لاگان۔ اگر بییہِ آسہِ، تیلہِ چھہ نوو دۅشوے کرایہ بناوان، تہ یُس ٹُکرہ نٔوِس منزہ {نِنہٕ آمُت} چھُ، سہ چھہ نہ پرانہِ سٍتۍ متفق آسان۔\n37.\\tتہٕ کانہہ تہِ انسان چھُنہٕ پرانہِ بوتلن منز نوو شراب تراوان۔ نتہ گژھہِ نوو شراب بوتلہِ پھٔٹِتھ تہ وہراونہ تہ بوتلہِ ختم گژھن۔\n38.\\tمگر نوو شراب گژھہِ نٔوۍ بوتلن منز تراوُن۔ تہٕ دۄشوے چِھ محفوظ۔\n39.\\tکانہہ تہِ انسان یُس پرانہِ شرابُک شراب} چُھس نہٕ سیدِ سٍتـ̡ نوو یژھان: تکیازِ سُہ چُھ ونان زِ پرون چُھ بہتر۔","1.\\tتہٕ گۆو گۅڈنچہ لٹہِ دویمہ سبت دۅہہ زِ سُہ گۆو مکایہ کھہَن منز۔ تہٕ تٔمۍ سٕندٮ۪و شٲگِرَو تُلِکھ مکایہِ ہٕندِس کَن تہٕ کھٮ۪وان تہٕ کھٮ۪وان تہٕ تِمن ہٕندِس اَتھن مَنٛز رٔگِتھ دِوان۔\n2. تہٕ فریسیو منزٕ کینہہ ووٚن تِمن زِ سبت دۅہہٕ کیازِ چُھہ یُس نہٕ حلال چُھہ؟\n3.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمن جواب دِتھ زِ تۅہہ کیا پٔرِو نہٕ یُتھ داؤد یُس داؤد اوس تہٕ یِم أمِس سٍتـ̡ ٲسۍ۔\n4.\\tکِتھہ پٲٹھـ̡ گۆو سُہ خدایہ سٕندِس گرس مَنٛز، تہٕ نِیُن تہٕ کھیوٚن تِمن تہٕ یِمن سٍتـ̡ پانس سٍتـ̡ ٲس۔ یُس نہ کھیوٚن حلال چھہ بلکہ صرف پادٕرین ہندِ خاطرہ؟\n5. تہٕ تٔمۍ ووٚن تِمن زِ انسان سُند فرزند چُھ سبت ہُند رب تہِ۔\n6.\\tتہ سپد بییِس سبت دۅہہ تہِ زِ سُہ اوس عبادت خانس منز اژان تہٕ ہیچھناوُن: تہٕ اَکھ شخٕص اوس یٔمۍ سُند دٔچھُن اتھہٕ مرزاونہٕ آمُت۔\n7.\\tتہٕ کاتب تہٕ فریسی ٲسۍ أمِس وچھان، کیا سبت دۅہہٕ کٔرِہ سُہ ٹھیٖک۔ تاکہ تِمن لٔبِتھ أمِس خلاف کانہہ الزام لٔبتھ۔\n8.\\tمگر سُہ اوس تِہٕندِس خیالس زانان، تہٕ وونُن أمِس شخصس یٔمِس مرزاونہٕ آمُت اَتھٕ اوس، تھوٚد تھوٚد تہٕ کھڑا گٔژھِو۔ تہٕ سُہ ووٚتھ تہٕ کھڑا کھڑا۔\n9. اَمہِ پَتہٕ ووٚن عیسیٰ علیہ السلام تِمَن زِ بہٕ پرژھہٕ ژےٚ اَکھ چیز۔ کیا سبت دوہ چھا نیکی کرُن یا بد کرُن جٲیز؟ زندگی بچاونہٕ خٲطرٕ، یا {یہ} تباہ کرنہٕ خٲطرٕ؟\n10.\\tتہٕ یِمن سارِنٕے کُن نظر دِتھ ووٚن أمِس شخصس زِ پَنُن اَتھٕ پھٔہلٲوِو۔ تہٕ تٔمۍ کٔر یہ: تہٕ تٔمۍ سُنٛد اَتھٕ آو بییِس پٲٹھۍ پوٗرٕ پٲٹھۍ بحال کرنہٕ۔\n11. تہٕ تِم گٔیہِ پاگل پن سٍتـ̡ بٔرِتھ۔ تہٕ کٔرٕکھ اَکھ أکِس سٍتـ̡ کتھ باتھ یُس تِم عیسیٰ سٍتـ̡ کٔرِتھ۔\n12.\\tتہٕ تِمن دۅہن سپد سُہ دُعا کرنہٕ خٲطرٕ أکِس پہاڑس منز دُعا کرنہٕ خٲطرٕ، تہٕ روٗد سارِوٕے رٲژ خدایہ سٕندِ خٲطرٕ دُعا کران۔\n13.\\tتہٕ ییلہ دۅہ آو تمٔۍ پنہٕ نِس شٲگِرَن بُلاونہٕ، تہٕ تِمو منزٕ ژٲر تٔمۍ باہ تہِ، یِمن ہُند ناو تہِ تٔمۍ رسولن ہُند ناو دِتھ۔\n14. سائمن، (یس تٔمۍ پیٹر تہٕ ناو تھوو،) تہٕ اینڈریو تٔمۍ سُند بوے جیمز تہٕ جان، فلپ تہٕ بارتھولومیو،\n15. میتھیو تہٕ تھامس، جیمز سُند {نیچو}، تہٕ شمعون اوس زیلوٹس ونان،\n16. تہٕ یہوداہ یعقوب سُند بوے تہٕ یہوداہ اسکریوٹ، یُس غدار تہِ اوس۔\n17.\\tتہٕ سُہ آو تِمن سٍتـ̡ بۄن تہٕ میدانس مَنٛز کھڑا تہٕ پننین شاگردن ہٕندِس صحبتس منز، تہٕ سٲرۍسٕے یہوداہ تہٕ یروشلم منزٕ تہٕ صور تہٕ صیدون کِس سمندری بٹھہٕ پیٹھ، یِم أمِس بوزنہٕ خٲطرٕ تہٕ تِمن ہٕنزِ بیمارِ نِش شفا حٲصل کرنہٕ خٲطرٕ آیہ۔\n18.\\tتہٕ یِم ناپاک روحن سٍتـ̡ پریشان گٔیہِ، تہٕ تِم گٔیہِ شفا ۔\n19.\\tتہٕ سارِوٕے ہجوم کٔر أمِس اَتھٕ لاگنٕچ کوٗشش، تکیازِ أمِس نِش گٔیہِ نیکی تہٕ کٔرٕن سارِنٕے شفا۔\n20.\\tتہٕ تٔمۍ تُل پننین شاگردن کُن نظر تہٕ وونُن، بابرکت آسُن غریب، تکیازِ تۅہہِ چُھ خدایہ سٕنز بادشٲہی ۔\n21. بابرکت {کیا تۅہہ} چھکھ وۅنۍ فاقہٕ: تکیازِ ژیہ گژھہِ پورٕ۔ بابرکت {کیا تۅہہ} یُس وۅنۍ روان چُھ، تکیازِ تم گژھہِ اسن۔\n22. بابرکت چُھہ تۅہہ، یێلہِ لُکھ تۅہہِ سٍتـ̡ نفرت، تہٕ ییلہ تۅہہِ پننہِ صحبتہٕ نِش الگ کرِ، تہٕ تُہُند ناو بد قرار دِن، اِنسان سٕندِس نیٚچوِس خٲطرٕ۔\n23.\\tاَمہِ دۅہہٕ کٔرِو خۅش تہٕ خوشی سٍتـ̡ وۄٹھ دِوُن، تکیازِ تُہند ثواب چُھہ آسمانس مَنٛز واریاہ زیادٕ، تکیازِ یِتھے پٲٹھۍ چھُ تِہندِ مٲلِس پیغمبرن سٍتـ̡ تہندِس مٲلِس سٍتـ̡ بٔڈِتھ دِژمُت۔\n24.\\tمگر ہا ہا تۅہہِ یُس امیر چھُ! تکیازِ ژیہ میلہِ تسلی دِنہٕ۔\n25.\\tافسوس چھکھ ژے یُس بٔرِتھ چھُ! تکیازِ تۅہہ گژھہِ فاقہٕ۔ ہا ہا ژے یُس وۅنۍ اسُن چھُ! تِکیازِ تُہۍ گژھِو ماتم تہٕ روُن۔\n26.\\tافسوس چھہ ژے ییلہ سٲری انسان چانہِ متعلق رژھ رژھ کتھ کرن! یِتھے پٲٹھۍ اوس تِہندِ مٲلۍ پٲٹھۍاپُز پیغمبرن سٍتـ̡ تہِ کٲم کٔرمٕژ۔\n27. مگر بہٕ چُھس ژے ونان یُس بوزان چُھ، پننین دشمنن سٍتـ̡ محبت کرُن، تِمن سٍتـ̡ کرو نیکی یُس تۅہہِ سٍتـ̡ نفرت کران چُھ،\n28. تِمن ہٕندِ خٲطرٕ کٔرِو دُعا یِم تۅہہِ بد دُعا کران چھِ۔\n29.\\tتہٕ یُس تۅہہِ اَکہِ گِلِس پیٹھ دِیہِ، سُہ دِیہِ بییِس تہِ دِنہٕ۔ تہٕ یُس تُہُند پوشہٕ تُلِتھ چھُ، سُہ کرِ نہٕ تُہند کوٹ تہِ نِنُک منع ۔\n30.\\tیُس تہِ پرٮ۪تھ أکِس انسانس دِیُن یُس تۅہہِ نِش منگان چُھ، تہٕ یُس تُہند مال نِوان چُھ، سُہ کرِ نہٕ دُبارٕ پرژھنہٕ۔\n31. تہٕ یِتھٕ پٲٹھۍ تُہۍ یژھان چھِو زِ انسان گژھن تۅہہِ سٍتـ̡ تہِ کرُن۔\n32.\\tیێلہِ تہِ چُھہ تِمن سٍتـ̡ محبت کران یُس تۅہہِ محبت کران چُھ، تێلہِ کیا چُھہ شُکر؟ تکیازِ گۅنہگار تہِ چُھ تِمن سٍتـ̡ محبت کران یُس تِمن سٍتـ�\n33.\\tتہٕ اگر تِمن سٍتـ̡ نیکی کٔرِو یُس تۅہہِ سٍتـ̡ نیکی کران چُھہ، تێلہِ کیا چُھہ شُکر؟ تکیازِ گۅنہگار تہِ چھہِ یۅہے کران۔\n34.\\tتہٕ یێلہِ تِمن دِوان چھِو یِمن ہُند میلنٕچ وۅمید چھِو، تێلہِ کیا چُھہ شُکر؟ تکیازِ گۅنہگار تہِ چھہِ گۅنہگارن تہِ دِوان، تیوت دُبارٕ حٲصل کرنہٕ خٲطرٕ۔\n35.\\tمگر پَنٕنـ̡ دُشمن سٍتـ̡ محبت کرُن، تہٕ نیکی کٔرِو تہٕ دِیُن دِیُن، دُبارٕ کُنہِ تہِ وۅمید کٔرِتھ۔ تہٕ تُہُند اجر آسہِ واریاہ زیادٕ، تہٕ تُہۍ بٔنِو اعلیٰ سٕندِ اولاد، تکیازِ سُہ چُھ کافرن تہٕ بد کارن سٍتـ̡ مہربان آسان۔\n36. تێمہِ کِنۍ گژھِو رحم کٔرِتھ، یێلہِ چُھہ تُہند مول تہِ رحم کرُن۔\n37.\\tفیصلہ کرو نہ، تہٕ یِیہِ نہٕ فیصلہ کرنہٕ: مذمت کرو نہٕ تہٕ یِیہِ نہٕ مذمت کرنہٕ: معافی دِیِو، تہٕ یِیہِ معافی دِنہٕ۔\n38. دِیُن، تہٕ یِیہِ دِنہٕ یِیہِ۔ رٔژ پیمائش، دباونہٕ آمٕژ، تہٕ رٔلِتھ تہٕ ژٔلِتھ ژٔلِتھ، مرد دِیہِ تُہنزِ چھۅکہِ منٛز۔ تکیازِ یۅہے پیمانہ تہِ ژیہ میلان چھیہ، یہ ییہ بییہ ژیہ میننہ یُن۔\n39.\\tتہٕ تٔمۍ کٔر تِمن سٍتـ̡ اکھ تمثیل، کیا انہِ ہُند رہنُمٲیی ہیکہِ کٔرِتھ؟ کیا تِم دۅشوے گژھن نہٕ کھۅنہِ منز؟\n40.\\tشاگرد چُھنہٕ پننِس آقا سٍتـ̡ زیادٕ آسان مگر یُس کامل آسہِ، سُہ گژھہِ پننِس آقا سٍتـ̡ آسُن۔ {یہ...: یا، گژھہِ پننس آقا سٕندِس طورس پیٹھ کامل کرنہٕ}\n41.\\tتہٕ ژے کیازِ چُھہ پننِس بٲے سٕنزِ اچھن منز موجود موٹ وچھان، مگر سُہ بیم یُس پننہِ اچھن منز چُھہ نہٕ وچھان؟\n42. یا تہٕ ژٕ کِتھ کٔنۍ ہیکِو پننِس بٲیس ؤنِتھ، بھائی، بہٕ کٔڈِتھ ژےٚ أچھن منٛز موجود گاش کٔڑِتھ، ییٚلہِ نہٕ ژے پانس پانس أچھن منٛز موجود گاش وچھان چھُ۔ ژے منافق، گۅڈٕ کٔڑِو پننہِ اچھِ منزٕ شعاعہٕ، تہٕ پتہٕ کٔرِو صاف پٲٹھۍ وُچھُن یُس بٲے سٕنزِ اچھِ منز موجود چھُ۔\n43. تکیازِ اصل کُل چُھہ نہٕ خراب پھل دِوان۔ نہ چھہ بدعنوان کُل اصل پھل دوان۔\n44. تکیازِ پریتھ کُل چُھ پننہِ پھلہٕ سٍتـ̡ زانان۔ تکیازِ کانٹٮن منز چھہ نہ انسان انجیر جمع کران، نہ چھہ کُنہِ {انگور: Gr. a graps}\n45.\\tاکھ نیک انسان چُھ پننِس دِلہٕ کِس نیک خزانہٕ منزٕ نیران یُس اصل چُھ نیران۔ تہٕ بدکار انسان چُھ پننہِ دِلٕکہِ بد خزانہٕ منزٕ سُہ نیران یُس بُرٕ چُھ، تکیازِ دِلٕچ کثرت سٍتـ̡ چُھ تٔمۍ سُند اوس کتھ کران۔\n46. تہٕ ژے کیازِ چُھکھ میہ وَنُن، خداوند، تہٕ یِم کتھ بہٕ ونان چھِ، تِم کتھ چھِنہٕ کٔرِتھ؟\n47. یُس تہِ میانہِ نِش یِیہ، تہٕ میانہِ کتھ بوزِتھ تہٕ یِم کرِ، بہٕ ہاوٕ ژے ہٲوِتھ سُہ کُس ہِش چُھ:\n48.\\tسُہ چُھ أکِس اِنسان ہٕندۍ پٲٹھۍ، یُس مکانہٕ بنوومُت تہٕ سرٛوٚن کھٔنِتھ کٔرِن کٔنہِ پتھرس پیٹھ بُنیاد تراوُن: تہٕ ییلہ سٔہلاب ووٚتھ، نالہٕ ووت تتھ مکانس پیٹھ زورٕ سان ٹاس تہٕ ہیوٚک نہٕ ہلٲوِتھ، تکیازِ یہِ اوس أکِس کَنہِ پتھرس پیٹھ بُنیاد تھاوان۔\n49. مگر یُس بوزان چُھ، تہٕ چُھ نہٕ کران، سُہ چُھ تِتھِس انسانس ہیوٗ یُس بُنیاد ورٲے زمینس پیٹھ مکانہٕ بنوومُت چُھ۔ یتھ خلاف نالہٕ زورٕ سان ٹاس دِژ، تہٕ یکدم پیوٚو یہ۔ تہٕ تمہ مکانک کھنڈرات اوس واریاہ زیادٕ۔","1. وۅنۍ ییلہ تٔمۍ لُکن ہٕندِس سامعینن منز پنٕنۍ تمام کتھ ختم کٔرۍ، سُہ ژاو کفرناؤمس مَنٛز۔\n2.\\tتہٕ أکِس مخصوٗص صد سُند نوکر، یُس أمِس عزیز اوس، اوس بیمار تہٕ مرنہٕ خٲطرٕ تیار۔\n3. ییلہ تٔمۍ عیسیٰ مسیحس متعلق بوز، تمٔۍ سوٗزۍ یہودین ہٕندۍ زِٹھۍ أمس نِش، تہٕ تٔمِس دِژ التجا زِ سُہ ییہ تہٕ پنہٕ نِس خادمس شفا دِنہٕ۔\n4. تہٕ ییلہ تِم عیسیٰ مسیحس نِش وٲتۍ، تِمو کٔر أمِس فوراً التجا کٔرِتھ زِ سُہ چُھ یٔمِس خٲطرٕ یہِ کرُن:\n5. تکیازِ سُہ چُھ سانہِ قومس سٍتـ̡ محبت کران، تہٕ تٔمۍ چُھ اسہِ اکھ عبادت گاہ بنوومُت۔\n6. پَتہٕ گۆو عیسیٰ مسیح تِمن سٍتـ̡ ۔ تہٕ ییلہ سُہ وۅنۍ گرٕ نِش دوٗر اوس نہٕ، سُہ سوٗزۍ أمِس نِش یار، تہٕ وونُن زِ خداوند، پانس مہ مہ پریشان: کیازِ بہٕ چُھس نہٕ اتھ لایق زِ ژٕ گژھِ میانہِ چھتہِ تَل اژُن۔\n7.\\tتێلہِ اوس نہ میہ پانہ ژے نِش یِنس لایق زانمُت، مگر کُنہِ لفظس منز ونُن، تہٕ میون خادم گژھہِ شفا ۔\n8.\\tکیازِ بہٕ تہِ چُھس اَکھ انسان یُس اِقتدارس تل تھاونہٕ آمُت چُھ، تہٕ بہٕ چُھس أکِس وَنُن، گژھ تہٕ سُہ چُھس نیران۔ تہٕ بییِس نِش آو تہٕ سُہ چُھ یِوان؛ تہٕ میٲنِس خادمَس کٔرِو یہِ تہٕ سُہ کرُن۔ {اکھ: Gr. This Man}\n9.\\tییلہ حضرت عیسیٰ علیہ السلام یِم کتھ بوز، سُہ گوو أمِس وُچھِتھ حٲران تہٕ پھیُرُن تہٕ وونُن تِمن لُکن یِم أمِس پٲٹھۍ، بہٕ چُھس ژےٚ وَنُن، بہٕ چُھس نہٕ تۅہہِ سٍتـ̡ وُچھمُت، نہٕ اسرٲیلِس مَنٛز چُھہ نہٕ۔\n10.\\tتہٕ یِم سوزنہٕ آمٕتۍ ٲسۍ، یِم گرس منز واپس آمٕتۍ ٲسۍ، وُچھ نوکر سُہ پوٗرٕ بیمار اوس۔\n11.\\tتہٕ پَتہٕ سپُد سُہ أکِس شہرس مَنٛز ناین ناو۔ تہٕ تٔمۍ سٕندِ واریاہ شٲگِر گٔیہِ أمِس سٍتۍ، تہٕ واریاہ لُکھ گٔیہِ۔\n12.\\tوۅنۍ ییلہ سُہ شہر کس دروازس نزدیک ووت، وُچھ اَکھ مردہ نِش نِنہٕ، یُس ماجہ ہُند کُنی نیچو اوس، تہٕ سۅ ٲس بیواہ تہٕ شہرٕکۍ واریاہ لوٗکھ ٲسۍ أمِس سٍتۍ۔\n13. تہٕ ییلہ خداوند أمِس وُچھ، أمِس کٔر أمِس پیٹھ رحم تہٕ وونُن نہٕ روُن۔\n14.\\tتہٕ سُہ آو تہٕ اَتھٕ لٔگِتھ تہٕ یِم نِش رٔٹِتھ گٔیہِ۔ تہٕ تٔمۍ ووٚن، نوجوان، بہٕ چُھس ژےٚ وَنُن وَنُن۔ {بیئر: یا، تابوت}\n15.\\tتہٕ یُس موٗدمُت اوس، ووٚتھ تھوٚد تہٕ ہیوٚتُن بولُن۔ تہٕ تٔمۍ واتنوو سُہ پنٛنہِ ماجہِ نِش۔\n16. تہٕ سارِنٕے سٍتـ̡ گۆو خوف، تہٕ تِمو کٔر خدایہِ سُند حمد تہٕ وَنُن زِ اسہِ مَنٛز چُھ اَکھ بۆڈ پیغمبر پٲدٕ سپدان۔ تہٕ یہ زِ خداین چُھ پننین لوکن ہُند دور۔\n17.\\tتہٕ تٔمۍ سٕنز یہ افواہ گٔیہِ سٲرۍسٕے یہوداہس تہٕ أندۍ پٔکۍ سٲرۍسٕے علاقس مَنٛز۔\n18.\\tتہٕ یوحنا سٕندٮ۪و شاگردو ہٲوۍ أمِس یِم سارِنٕے چیز۔\n19.\\tتہٕ یوحنا بُلٲوِتھ پننیو زٕ شٲگِرِو حضرت عیسیٰ ہس نِش یِنہٕ وٲلِس نِش یُس یا أسۍ چھِ بیاکھ ژھانڈان؟\n20. ییلہ مرد أمِس نِش وٲتۍ، تِمو ووٚن زِ یوحنا بپتسمہ دِنہٕ آمُت چُھہ اسہِ تۅہہِ نِش سوزمُت، یہِ وَنُن زِ ژٕ چھُکھ یُس یُن یُن؟ یا أسۍ چھِ بیاکھ ژھانڈان؟\n21.\\tتہٕ أتھۍ ساعتس منز کٔر تٔمۍ واریاہن بیمارین تہٕ آفتن تہٕ بد روحن ہُند علاج۔ تہٕ واریہن {یِمَن} انہٕ ٲسۍ، تٔمۍ دِژ گاش۔\n22. تێمہِ پَتہٕ وۆن عیسیٰ علیہ السلام تِمن جواب دِتھ تہٕ وَنُن زِ یوحنا کیاہ وُچھمُت تہٕ بوزمُت چھُ۔ کِتھہ پٲٹھـ̡ چُھہ انہِ وُچھان، لنگرِ چُھہ پکان، کوڑھ چُھہ پاک سپدان، بہرِ بوزان چُھ، مُردٕ چُھہ زندٕ کرنہٕ یوان، غریبن ہٕندِ خٲطرٕ چُھ انجیل ہٕنز تبلیغ کرنہٕ یوان۔\n23. تہٕ بابرکت چُھ، یُس نہٕ میہ سٍتـ̡ ناراض گژھہِ۔\n24.\\tتہٕ ییلہ یوحنا سٕندِ قاصد نیرِ، تٔمۍ ہیوٚت یوحنا سٕندِس بارس منز لُکن سٍتـ̡ کتھ کرٕن، ژیہ کیا گۆو بیابانس مَنٛز وُچھنہٕ خٲطرٕ؟ ہوہس سٍتۍ ہلاونہٕ آمُت اکھ سرۍ؟\n25.\\tمگر ژیہ کیا وُچھنہٕ خٲطرٕ گٔیہِ؟ نرم پلو لٲگِتھ اکھ شخٕص؟ وُچھِو تِم یِم خوبصورتی سان پوشاک لاگان چھِ، تہٕ نازک پٲٹھۍ روزان چھِ، چھِ بادشاہن ہٕندِس دربارس منز۔\n26.\\tمگر ژیہ کیا گۆو وُچھنہٕ خٲطرٕ؟ اکھ پیغمبر؟ آ، بہٕ چُھس ژےٚ وَنُن، تہٕ پیغمبر سٕندِ کھۅتہٕ زیادٕ۔\n27.\\tیہِ چھُ یٔمِس مُتلق لیکھنہٕ آمُت چھُ، وُچھ، بہٕ چُھس پنُن پیغامبر تۅہہِ برونہہ کُن سوزان، یُس تۅہہِ برونہہ کُن وتھ تیار کرِ۔\n28. یێلہِ بہٕ چُھس ژےٚ ونان زِ یُس زنانہٕ سٍتـ̡ پٲدٕ سپدان چُھ، تِمن مَنٛز چُھنہٕ یوحنا بپتسمہ دِنہٕ وٲلِس سٍتـ̡ کانہہ بۆڈ پیغمبر آسان، مگر یُس خدا سٕندِس بادشاہتس مَنٛز کم از کم چُھ، سُہ چُھ تٔمِس کھوتہٕ بٔڈ آسان۔\n29.\\tتہٕ یِمو سارِوٕے لُکھ بوٗزِ، تہٕ پبلِکنو کٔر خدایہِ سُند بپتسمہ دِنہٕ، یُس یوحنا سٕندِ بپتسمہ سٍتـ̡ بپتسمہ دِنہٕ آو۔\n30. مگر فریسیو تہٕ وکیلو کٔر پانس خلاف خدایہِ سُند مشورٕ رد، تہٕ تٔمۍ سُند بپتسمہ دِنہٕ آو۔ {مسترد کرنہٕ: یا، مایوس} {خلاف...: یا، پانس اندر}\n31. تہٕ خداوند ووٚن، تیلہِ کمہِ سٍتـ̡ بہٕ یێمہِ زمانہٕ کین نفرن ہُند ہشر کٔرِتھ؟ تہٕ تِم کِتھہٕ پٲٹھۍ چھِ؟\n32.\\tتِم چھِ شُرین ہٕندۍ پٲٹھۍ، یِم بازرَس مَنٛز بِہِتھ چھِ، تہٕ اَکھ أکِس بُلاونہٕ خٲطرٕ ونان چھِ، أسۍ چھِو ژےٚ نژان تہٕ تۅہہ چُھہ نہٕ نژان۔ أسۍ چھِ ژےٚ خٲطرٕ ماتم کٔرمٕژ، تہٕ ژےٚ روو نہٕ۔\n33. یوحنا بپتسمہ دِنہٕ وول آو نہٕ روٹی کھٮ۪وان تہٕ نہ شراب چیٚنہٕ۔ تہٕ تُہۍ چھِو ونان زِ أمِس چُھ اکھ شیطان۔\n34.\\tانسان سُند فرزند چُھ کھٮ۪وان تہٕ چیوان ۔ تہٕ تُہۍ چھِو وَنُن، وُچھِو اکھ لالچی انسان، تہٕ اکھ شراب، یُس پبلکن تہٕ گۅنہگارن ہُند دوس چھُ!\n35.\\tمگر حکمت چھے تٔمۍ سٕندِس سارِنٕے شُرین ہٕندِس سٍتـ̡ جٲیز۔\n36.\\tتہٕ فریسیو منزٕ اوس أکۍ سُہ أمِس سٍتـ̡ کھٮ۪نہٕ خٲطرٕ یژھان۔ تہٕ سُہ گوٚو فریسی سٕندِس گرس منز، تہٕ بیوٹھ ماز کھٮ۪نہٕ۔\n37.\\tتہٕ وُچھِو شہرس مَنٛز اَکھ زنانہٕ، یۄسہٕ گۅنہگار ٲس، یێلہِ أمِس پتاہ گۆو زِ عیسیٰ مسیح چُھہ فریسی سٕندِس گرس مَنٛز مازس پیٹھ بِہتھ، اَنُن مرہمُک اکھ الباسٹر ڈبہٕ،\n38.\\tتہٕ وُچھن تٔمۍ سٕندِس قدمن نِش وُنُن، تہٕ لوٚگُن اوٚش سٍتـ̡ کھۅر واش کٔرِتھ، تہٕ کٔرٕن تٔمۍ سٕندِس کلہٕ سٍتـ̡ مَلہٕ سٍتـ̡ بوسہ دِنہٕ، تہٕ کورُن مرہم سٍتـ̡ مسح کرنہٕ۔\n39.\\tیێلہِ یێلہِ یێمہِ فریسی أمِس حُکُم دِژمُت اوس تٔمِس وُچھمُت، تٔمِس وۆن پانَس مَنٛز وَنُن زِ یہِ نَفر اگر سُہ پیغمبر آسہِ، تێلہِ آسہِ ہا زانان زِ یہِ کُس تہٕ کمہِ قسمٕچ زنانہٕ چُھہ یُس أمِس اتھہٕ لاگان چُھ، کیازِ سُہ چُھ گۅنہگار۔\n40. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تس جواب دِتھ زِ شمعن، میہ چُھہ ژے کینہہ ونُن۔ تہٕ سُہ چُھ ونان، مالک، وَنُن۔\n41.\\tاکھ خاص قرض دِنہٕ وول اوس ییمِس زٕ قرٕض دار ٲسۍ: أکِس اوس پانژھ ہتھ پینس تہٕ بیٛاکھ پنژاہ۔\n42.\\tتہٕ ییلہ تِمن دِنہٕ خٲطرٕ کینہہ تہِ اوس نہٕ، تٔمۍ کٔر یِم دۄشوٕے صاف پٲٹھۍ معاف۔ تَمہِ کِنۍ وَن مےٚ زِ یِمو منٛزٕ کُس کرِ أمِس ساروٕے کھۄتہٕ زیادٕ محبت؟\n43.\\tشمعون دیُت جواب تہٕ وونُن، بہٕ چُھس باسان زِ {سُہ}، یٔمِس سٍتـ̡ تٔمِس سارِوٕے کھۄتہٕ زیادٕ معافی دِژمٕژ۔ تہٕ تٔمۍ ووٚن تٔمِس زِ ژے چُھ صحیح فٲصلہٕ دِژمُت۔\n44.\\tتہٕ سُہ پھیُر زنانہِ کُن تہٕ وونُن شمعنس کُن، ژیہ چھے یہِ زنانہٕ وچھان؟ بہٕ ژاو چانہِ گرس منز، ژے دیت نہ میہ پننین کھۅرن آب مگر تمۍ واش کٔرِتھ میٲنس کھۅر واش کٔرۍمٕتۍ، تہٕ کلہٕ سٍتۍ صاف کٔرۍ۔\n45.\\tژے دیت نہ میہ کانہہ بوسہ: مگر ینہ پیٹھہ میہ اژنہ آمت چھیہ نہ یہ زنانہِ میانین کھورن بوسہ دوان۔\n46.\\tمیانہِ کلہٕ تیٖلہٕ سٍتـ̡ ژے کٔر نہٕ مسح کٔرِتھ، مگر أمِس زنانہِ کٔر میانین کھۅرن مرہم سٍتـ̡ مسح کرنہٕ۔\n47. اَمہِ مۄکھٕ چُھس بہٕ ژے وَنُن زِ تٔمۍ سٕندِ گۅناہ یِم واریاہ چھِ، چھِ معاف۔ تکیازِ تس اوس واریاہ محبت کران: مگر یمس کم کم معافی دِنہٕ یوان چھ، {یۅہے} چھہ کم محبت کران۔\n48.\\tتہٕ تٔمۍ ووٚن أمِس زِ تۅہہِ گۅناہ چھِ معاف۔\n49.\\tتہٕ یِم أمِس سٍتـ̡ مازس پیٹھ بِہتھ ٲسۍ، تِمو ہیوٚت پانس اندر وَنُن، یہِ کُس چُھ یُس گۅناہ تہِ معافی دِوان چُھ؟\n50. تہٕ تٔمۍ ووٚن زنانہِ زِ تُہند ایمان چُھ ژے بچٲومُت۔ امن سان گژھ۔","1. تہٕ امہ پتہ سپد یہ زِ سُہ گۆو پریتھ شہرس تہٕ گامس منز، خدایہ سٕنزِ بادشٲہی ہٕنز بشارت دِوان تہٕ دِوان تہٕ باہ ٲسۍ تس سٍتـ̡ ،\n2.\\tتہٕ کینہہ زنانہٕ، یِم بد روحو تہٕ بیماریو نِش شفا ٲس گٔمٕژ، مریمن بُلوو مگدلِن، یِمو منزٕ ستھ شیطان گٔیہِ،\n3.\\tتہٕ جوانا، یُس چُزا ہیرودس سٕندِس سٍتـ̡ زنانہٕ، تہٕ سوسانا تہٕ باقٕے واریاہ یِمو أمِس سٍتـ̡ تِمن ہٕندِس مالہٕ سٍتـ̡ خدمت کٔر۔\n4. تہٕ ییلہ واریاہ لُکھ جمع گٔیہِ، تہٕ پرٮ۪تھ شہرٕ منزٕ أمِس نِش آیہ، تٔمۍ کٔر أکِس تمثیلس سٍتـ̡ کتھ کرنہٕ:\n5.\\tاکھ وونہٕ وول دراو پنن بیول وونہِ، تہٕ ییلہ تٔمۍ وونہٕ ووت، کینہہ پیوٚو وتہِ اندۍ پکھۍ۔ تہ یہ آو لوٚگ تہ ہوہس منز لوٚگ جاناوار۔\n6.\\tتہٕ کینہہ پیوٚو أکِس کَنہِ پتھرس پیٹھ۔ تہ ییلہ یہ پھوٚل ووٚتھ، یہ گوٚو مرز، تکیازِ اتھ منز ٲس نمی کم۔\n7.\\tتہٕ کینہہ پیوٚو کانٹَن منز۔ تہٕ اتھ سٍتۍ گٔیہ کانٹہٕ پھٔٹۍ، تہٕ دوٚپ دِتھ۔\n8. تہٕ باقٕے پیوٚو اصل زمینس پیٹھ، تہٕ پھٔلِتھ پھٔلِتھ ہتھ گنہٕ پھلہٕ۔ تہٕ ییلہ تٔمۍ یِم کتھہٕ ووٚن، تٔمۍ ووٚن کٔرِتھ، یُس بوزنہٕ خٲطرٕ کَن چُھ، سُہ بوزُن۔\n9.\\tتہٕ تٔمۍ سٕندٮ۪و شٲگِرَو پرژھ أمِس زِ یہِ تمثیل کیا آسہِ؟\n10. تہٕ ووٚن تۅہہِ خدایہ سٕنزِ بادشٲہی ہٕندِس اسرار زاننہٕ خٲطرٕ دِنہٕ آمُت، مگر تمثیلن مَنٛز باقین ہٕندِس خٲطرٕ۔ زِ وچھتھ ما آسہِ نہ وچھان، تہ بوزان آسہِ نہ تم سمجھان۔\n11. وۅنۍ چُھ تمثیل یہ: بیول چُھ خدایہ سُند کلام۔\n12.\\tوتہِ اندۍ پکھۍ تم چھہِ بوزان۔ اَمہِ پَتہٕ چُھ شیطان یِوان، تہٕ تِہٕندِس دِلَس مَنٛز کُن کلام نِش نِش نِنہٕ، یێلہِ گژھن تِم یِمن ہُند ایمان تہٕ نجات دِنہٕ۔\n13.\\tتِم چِھہ کنہِ پتھرس پیٹھ، یُس بوزان چُھ، کلام چُھ خوشی سان وصول کران۔ تہٕ یِمن ہُند کانہہ موٗل چُھنہٕ، یُس کینژَس کالس پژھ تھاوان چھُ، تہٕ فتنہ وِزِ چھُ ختم گژھان۔\n14. تہٕ یُس کانٹَن مَنٛز پیوٚو سُہ چھُ تِم یِم بوزان چھِ، نیران چھِ، تہٕ زندگی ہٕنزِ خیالات، دولت تہٕ لذتن سٍتـ̡ گٔژھِتھ چھِ، تہٕ کُنہِ تہِ پھل دِوان چھِ۔\n15.\\tمگر یہ زِ اصل زمینس پیٹھ چھہِ تم یِم ایماندار تہٕ نیک دلس منز، کلام بوزِتھ رژھراوان تہٕ صبر سٍتۍ پھل دِوان۔\n16.\\tکانہہ تہِ انسان ییلہ شمعہ زٲلِتھ آسہِ، تہٕ کُنہِ بسترس تَل کٔرِتھ تھپھ کٔرِتھ۔ مگر شمعدان پیٹھ تھووُن {یہ}، تاکہ یم اندر اژان چھہِ تم گژھن گاش وچھتھ۔\n17. تکیازِ کانہہ تہِ راز چھہ نہ، یُس ظٲہر گژھہِ نہ۔ نہ چھہ {کانہہ چیز} ژوٗرِ روزان، یُس نہ معلوم گژھہِ تہ نیبر کُن یِن۔\n18.\\tتێلہِ کِتھہ پٲٹھـ̡ بوزُن، یێمہِ سٍتـ̡ یُس آسہِ، سُہ ییہِ دِنہٕ۔ تہٕ یُس نہٕ أمِس نِش آسہِ، سُہ یُس أمِس نِش نِش نِنہٕ یُس أمِس نِش باسان چھُ۔ {سیمیتھ...: یا، سوچان زِ أمِس چُھ}\n19.\\tتمہ پتہ آو أمس نِش موج تہٕ تٔمۍ سٕندِس بٲے نِش، تہٕ ہیوٚک نہٕ أمِس نِش پریس کرنہٕ خٲطرٕ یِتھ۔\n20.\\tتہٕ أمِس وَننہٕ آمُت زِ تُہٕنزِ موج تہٕ تُہٕندِ بٲے چھِ تۅہہِ وُچھنُک خواہش۔\n21. تہٕ تٔمۍ دِژ جواب تہٕ تِمن وونُن، میانہِ موج تہٕ میٲنۍ بٲے چھِ یِم خدایہِ سُند کلام بوزان چھِ، تہٕ یہِ کران چھِ۔\n22.\\tوۅنۍ گۆو اکہ دۅہہ زِ سُہ گۆو پننین شاگردن سٍتـ̡ ٲبی جہازس منز، تہٕ تٔمۍ ووٚن تِمن زِ أسۍ گژھو جھیل کِس دوٚیمس اندس کُن۔ تہٕ تِمو کٔر شروع۔\n23.\\tمگر ییلہ تِم سفر کٔرۍ، سُہ گۆو شوٚنگتھ: تہٕ جھیلس پیٹھ واو ہُند اکھ طوفان۔ تہٕ تِم ٲسۍ {آبہٕ سٍتۍ} بٔرِتھ تہٕ خطرس منز۔\n24.\\tتہٕ تِم آیہِ أمِس نِش تہٕ ووٚنُن زِ آقا، آقا، أسۍ چھِ ماران۔ تمہ پتہ ووٚتھ ووٚتھ، تہ واو تہ آبس پیٹھ لۅتہِ لوٚگ، تہ تِم گٔیہ رُک، تہ اتہِ گۆو سکون۔\n25.\\tتہٕ تٔمۍ ووٚن تِمَن کَتہِ چُھہ تُہند ایمان؟ تہٕ تِم گٔیہِ خوفزدہ گٔژھتھ اکھ أکِس وَنُن، یہِ کُس انسان چھُ! تکیازِ سُہ چُھ ہواہن تہٕ آبس تہِ حُکُم دِوان، تہٕ تِم چھِ أمِس اطاعت کران۔\n26.\\tتہٕ تِم وٲتۍ گدارِنس کِس ملکس منز، یُس گلیلس خلاف ختم چھُ۔\n27.\\tتہٕ ییلہ سُہ بٔنِس کُن درٛاو، تٔمِس سمکھیوو شہرٕ نیبر أکِس شخٕصس سٍتۍ، یٔمِس واریاہ کالہٕ شیطان اوس، تہٕ اوسُس نہٕ کُنہِ تہِ مکانس مَنٛز روزان بلکہ قبرن مَنٛز۔\n28.\\tییلہ تٔمۍ عیسیٰ مسیح وُچھ، سُہ کٔر کرٛٮ۪کھ تہٕ پیوٚو أمِس برونہہ کُن تہٕ بَڑِ آوازِ سٍتـ̡ وونُن، عیسیٰ مسیح، ژے سٍتـ̡ کیا چُھہ ژے سٍتـ̡ کرُن؟ بہٕ چھُس ژےٚ التجا کران، مے کٔر نہٕ عذاب۔\n29. (تکیازِ تٔمۍ اوس ناپاک روحس انسانس منزٕ نیرنُک حکم دِتمُت۔ اکثر اوس أمِس رٔٹمُت: تہٕ سُہ اوس زنجیر تہٕ زنجیر لٲگِتھ تھاونہٕ آمُت۔ تہٕ تٔمۍ کٔر بینڈس بریک، تہٕ شیطان آو بیابانن منٛز کڑنہٕ۔)\n30. تہٕ حضرت عیسیٰ علیہ السلام پرژھ أمِس زِ تُہند ناو کیا چُھ؟ تہٕ تٔمۍ ووٚن، لشکر: تکیازِ أمس منٛز ٲسۍ واریاہ شیطان دٲخل گٔمٕتۍ۔\n31.\\tتہٕ تِمو کٔر أمِس التجا زِ سُہ کرِ نہٕ تِمن سٍتـ̡ سرٛنِس مَنٛز نیرنُک حُکُم۔\n32. تہٕ اَتہِ اوس پہاڑس پیٹھ واریہن سورن ہُند اکھ کھیٚول کھٮ۪وان، تہٕ تِمو کٔر أمِس التجا زِ سُہ دِیہِ تِمن منز اژنہٕ خٲطرٕ۔ تہٕ تٔمۍ کوٚر تمن تکلیف۔\n33.\\tپتہٕ دراو شیطان انسانس منز، تہٕ ژاو سورس منز، تہٕ کھیٚول ژوٚل أکِس کھڑایہِ جایہِ پٮ۪ٹھٕ جھیلس منز، تہٕ گٔیہٕ گُلہٕ گٔیہِ۔\n34.\\tییلہ تِمو وُچھ زِ کیا سپدان اوس، تِم ژٔلِتھ گٔیہِ شہرس تہٕ دیرس مَنٛز۔\n35.\\tپتہٕ گٔیہِ تِم نیٚبرِ وٕچھنہٕ خٲطرٕ زِ کیا آو کرنہٕ۔ تہٕ آو عیسیٰ ہس نِش، تہٕ وُچھ سُہ انسان، یٔمِس نِش شیطان ژٔلِتھ ٲسۍ، عیسیٰ سٕندِس قدمن نِش بِہِتھ، پلو لٲگِتھ تہٕ تٔمۍ سٕندِس صحیح ذہنس منٛز: تہٕ تِم گٔیہِ کھوژان۔\n36.\\tیِمو تہِ وُچھمُت تِمو تہِ وُچھِتھ یُس شیطان سٍتـ̡ اوس، کمہِ سٍتـ̡ چُھہ شفا دِنہٕ آمُت۔\n37.\\tاَمہِ پتہٕ کٔر اَندۍ پٔکھۍ گَدارِنٕکۍ سٲرۍسٕے لٔگِس أمِس نِش نیرنہٕ خٲطرٕ التجا ۔ تکیازِ تِم آیہ سٮ۪ٹھاہ خوفہٕ سٍتۍ نِنہٕ: تہٕ سُہ ووت جہازس منز، تہٕ آو واپس واپس۔\n38.\\tیُس شخٕص یٔمِس نِش شیطان ژٔلِتھ دِنہٕ آمُت اوس، تٔمِس کٔر أمِس سٍتـ̡ گُزٲرِتھ مگر حضرت عیسیٰ علیہ السلام سُہ یہِ ؤنِتھ دِژمُت،\n39.\\tپننِس گرس مَنٛز واپس، تہٕ ہٲوِو خداین کِس سٍتـ̡ کٲژاہ بٔڈ کٲم کٔرمٕژ۔ تہٕ سُہ پوٚک پنٕنـ̡ وتہٕ، تہٕ سٲرۍسٕے شہرس منز شایع کورُن عیسیٰ مسیحن سٍتـ̡ کٲژاہ بٔڈ کٲم کٔرمٕژ۔\n40. تہٕ سپُد یہِ زِ یێلہِ عیسیٰ آو واپس دِنہٕ، لُکو کٔر أمِس {خوشی سان} استقبال کرنہٕ، تِکیازِ تِم ٲسۍ سٲری أمِس پیاران۔\n41.\\tتہٕ وُچھِتھ آو یَرس ناوُک اَکھ شخٕص تہٕ سُہ اوس یہِ عبادت خانہٕ ہُند حُکُمران تہٕ سُہ پیوٚو عیسیٰ سٕندِس قدمن نِش تہٕ دِژُن أمِس گَرَس مَنٛز۔\n42. تکیازِ أمس ٲس اکھ کُنی کور، تقریباً باہ وُہُر، تہٕ سۄ ٲس مران۔ مگر ییلہ سہ گٔیہِ لوکھ أمس ہجوم۔\n43.\\tتہٕ أکِس زنانہِ ہُند خونُک مسلہٕ، یٔمۍ پنُن سورُے زُو طبیبن پیٹھ گُزٲرمُت اوس، تہٕ ہیوٚک نہٕ کانہہ تہِ شفا دِنہٕ۔\n44.\\tپَتہٕ آو تہٕ لوٚگ تٔمۍ سٕندِس پلوس کِس اندس تھپھ کٔرِتھ، تہٕ یکدم لوٚگ أمِس خونُک مسلہٕ۔\n45. تہٕ حضرت عیسیٰ علیہ السلام ووٚن، کُس اوس میہ اتھہٕ لوگمُت؟ ییلہ سارِوٕے انکار کٔر، پطرس تہٕ أمِس سٍتـ̡ موجود لوکو وۆن، مالک، ہجوم ہٕندِس ہجوم سٍتـ̡ ژے ہٕندِس دٔپِس تہٕ دباونہٕ آمُت، تہٕ وَنُن، کُس چُھس میہ اتھہٕ لوگمُت؟\n46.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن، کٲنسہِ چُھہ میہ اتھہٕ وُچھمُت، تکیازِ بہٕ چُھس سمجھان زِ نیکی چھے میہ نِش ختم گٔمٕژ۔\n47.\\tتہٕ ییلہ زنانہِ وُچھ زِ سۅ ٲس نہٕ ژوٗرِ روزمژ، سۅ آیہِ تھرتھر کٔرِتھ تہٕ أمِس برونہہ کُن پیوٚو، تٔمۍ کٔر أمِس سارِنٕے لوٗکَن برونہہ کُن اعلان زِ أمِس کتھ وجہہ کِنۍ ٲس أمِس اتھہٕ لاگمٕژ، تہٕ کِتھہ کٔنۍ گٔیہِ سُہ جلدی ٹھیٖک۔\n48.\\tتہٕ تٔمۍ ووٚن أمِس ، کور، رژھرٕن: چانہِ ایمانن چُھہ ژے پوٗرٕ پٲٹھۍ۔ امن سان گژھ۔\n49.\\tییلہ سُہ وُنہِ تہِ کتھ کٔرِتھ، یێلہِ چُھہ یہِ وَنُن زِ تُہٕنز کوٗر چھے مٔرِتھ۔ مصیبت چھیہ نہ مالک۔\n50. مگر ییلہ حضرت عیسیٰ علیہ السلام بوٗزِ، تٔمِس دِژ جواب دِتھ زِ خوفہٕ مہٕ کرُن: صرف ایمان، تہٕ سُہ گژھہِ صحت یاب کرنہٕ۔\n51. تہٕ ییلہ سُہ گرس منز آو، تس آو نہٕ پطرس تہٕ جیمز تہٕ یوحنا تہٕ کورِ ہٕندِس مول تہٕ موج سٍتـ̡ اژنہٕ خٲطرٕ کانہہ تہِ نفر۔\n52.\\tتہٕ سارِوٕے روُن تہٕ دِژ أمِس ماتم مگر تٔمۍ ووٚن، روو نہٕ۔ سۅ چھیہ نہ مٔرۍ، مگر شوٚنگتھ چھیہ۔\n53. تہٕ تِمو اوس أمِس طنز کرنہٕ خٲطرٕ اسُن، یہ زٲنِتھ زِ سۄ ٲس موٗدمٕژ۔\n54.\\tتہٕ تٔمۍ کٔرِن تِم سارِنٕے نیبر، تہٕ رٔٹِتھ أمِس اَتھٕ تھپھ کٔرِتھ وُچھُن، وُچھُن وُچھُن۔\n55.\\tتہٕ تٔمۍ سُند روح آو دُبارٕ تہٕ سُہ ووٚتھ سُہ سُہ دِیُت أمِس ماز دِنُک حُکُم۔\n56.\\tتہٕ تٔمۍ سُند مول موج گٔیہ حٲران: مگر تٔمۍ دِژ تِمن حکم زِ تِم پزِ نہٕ کٲنسہ تہِ شخصس وَنُن زِ کیا آو کرنہٕ۔","1. تمہ پتہ بُلوو تٔمۍ پننین بہن شاگردن یکجا تہٕ دِژن تمن سارنٕے شیطانن پیٹھ طاقت تہٕ اختیار تہٕ بیمارِ علاج کرنہٕ خٲطرٕ۔\n2. تہٕ تٔمۍ سوٗزۍ تِم خدایہِ سٕنزِ بادشٲہی ہٕنز تبلیغ کرنہٕ خٲطرٕ، تہٕ بیمارن شفا دِنہٕ خٲطرٕ۔\n3.\\tتہٕ تٔمۍ ووٚن تِمَن زِ تِمن ہٕندِس سفرس خٲطرٕ نِیُن نہٕ کانہہ تہِ، نہ لٔرِتھ تہٕ نہ کھورِ تہٕ نہ پٲنسہٕ۔ نہ چھہ زہ کوٹ۔\n4. تہٕ یُس تہِ گرس منز اژان چھِو، تتہِ روزِ روزُن تہٕ نیرِو۔\n5. تہٕ یُس نہٕ تۅہہِ قبول کرِ، ییلہ تہٕ تُہۍ تمہِ شہرٕ منزٕ نیرِو، تِمن خلاف گوٲہی دِنہٕ خٲطرٕ کٔرِو پنٕنِس کھورِ پیٹھٕ گردِ ہٹٲوِتھ۔\n6. تہٕ تِم دراو تہٕ گٔیہِ شہرن مٔنزۍ گٔیہِ، انجیل ہٕنز تبلیغ کٔرِتھ تہٕ کُنہِ جایہِ شفا دِوان۔\n7. وۅنۍ ہیرودس بُوز تٔمِس سٍتـ̡ یُس تٔمِس سٍتـ̡ کرنہٕ آمُت چُھ، تہٕ سُہ گوو پریشان، تکیازِ کینژن متعلق اوس یہِ وننہٕ آمُت زِ یوحنا اوس مُردٕ منزٕ زندٕ گومُت۔\n8.\\tتہٕ کینژَن منز اوس الیاس ظٲہر گومُت۔ تہٕ باقین ہٕندِس سٍتـ̡ زِ پرانہِ پیغمبرن منز آو اَکھ دُبارٕ زندٕ۔\n9. تہٕ ہیرودیس ووٚن، یوحنا چُھس میہ کلہٕ ژٹمُت، مگر یہِ کُس چُھ، یٔمِس مُتلق بہٕ یِژھ کتھ بوزان چُھس؟ تہٕ سُہ اوس أمِس وُچھُن یژھان۔\n10.\\tتہٕ رسولو ییلہ تم واپس آۓ، تمِس ووٚن سُہ سورُے یُس تمو کورمُت اوس۔ تہٕ تٔمۍ نیو تِم تہٕ ژاو أکِس ریگستانی جایہِ یُس بیت سیدہ ناو اوس۔\n11. تہٕ لُکھ ییلہ تِمن پتاہ لٔگِتھ تہٕ تِمن کٔرٕن خدایہِ سٕنزِ بادشٲہی ہٕنز کتھ تہٕ یِمن شفا دِنٕچ ضرورت ٲس۔\n12.\\tتہٕ ییلہ دۅہ ژلُن ہیوٚت، تمہ پتہ آیہ باہ تہٕ وونُن أمِس زِ ہجوم ژٔلِتھ ژٔلِتھ یُتھ تِم اندۍ پکھۍ قصبن تہٕ ملکن منز گٔژِھتھ روزن تہٕ رٔٹِتھ، تکیازِ أسۍ چھِ یتہِ أکِس ریگستانس مَنٛز۔\n13.\\tمگر تٔمۍ ووٚن تِمن کھٮ۪نہٕ خٲطرٕ۔ تہٕ تِمو ووٚن، اسہِ نِش چھِ نہٕ پانژھ روٹی تہٕ زٕ گاڈٕ علاوٕ زیادٕ۔ مگر اسہِ گژھِ یمن سارِنٕے لوٗکن خٲطرٕ ماز انن۔\n14.\\tتکیازِ تِم ٲسۍ تقریباً پانژھ ساس نفر۔ تہٕ تٔمۍ ووٚن پننین شاگردن زِ تِم بِہتھ پنژاہ دٔہلہِ تام أکِس صحبتس منٛز۔\n15.\\tتہٕ تِمو کٔر یۅہے تہٕ بِہتھ سارِنٕے بیوٹھ۔\n16.\\tامہ پتہ رٔٹۍ پانژھ روٹی تہٕ زٕ گاڈ، تہٕ آسمانس کُن نظر دِتھ دِژ تمن برکت تہٕ بریک، تہٕ دیتُن شاگردن ہٕندِس بٔڈس برونہہ کُن تھاونہٕ خٲطرٕ۔\n17.\\tتہٕ تِمو کھیوٚو تہٕ سارِنٕے گٔیہِ بٔرِتھ تہٕ تِمن ہٕندِس نِش باقٕے باہ ٹوٗکرِ تُلنہٕ۔\n18.\\tتہ سپد یہ سپدُن، ییلہ سُہ کُنی زُن دعا کران اوس، تٔمۍ سٕندۍ شٲگِر ٲسۍ أمِس سٍتۍ، تہٕ تٔمۍ پرژھ تِمن زِ بہٕ کُس چُھس لوکھ ونان چھُس؟\n19. تِمو ووٚن جواب دِتھ، یوحنا بپتسمہ دِنہٕ وول؛ مگر کینہہ {ونان}، الیاس؛ تہٕ باقٕے چھِ {ونان} زِ پرانہِ پیغمبرن مَنٛز چُھ اَکھ دُبارٕ زندٕ گومُت۔\n20.\\tتٔمۍ ووٚن تِمَن، مگر تُہۍ کُس چُھس ونان زِ بہٕ چھُس؟ پطرس ووٚن جواب دِتھ خدایہ سُند مسیح۔\n21.\\tتہٕ تٔمۍ دِژ تِمن پیٹھ سختی سان حملہٕ، تہٕ دِتُن حکم زِ سُہ وَنُن کٲنسہ تہِ شخصس یہِ کتھ ونن۔\n22.\\tیہ ونِتھ زِ انسان سُند فرزند گژھہِ واریاہن چیزن ہُند شکار سپدُن، تہٕ بزرگن تہٕ بٔڈۍ کاہرینن تہٕ کاتبن نِش گژھِ رد کرنہٕ یُن، تہٕ مارنہٕ یُن، تہٕ تریمہِ دۅہہ گژھہِ زندٕ کرنہٕ یُن۔\n23.\\tتہٕ تٔمۍ ووٚن سارِنٕے سارِنٕے یِمن سارِنٕے پَتہٕ یِنہٕ یِنہٕ وٲلِس سٍتـ̡ سُہ پانس نِش انکار کرُن، تہٕ روزِ دۅہہٕ پنُن صلیب تُلِتھ تہٕ میانہِ پتہٕ پٲٹھۍ۔\n24. یُس تہِ پَنُن زُو بچاوِ، سُہ گژھہِ سُہ رٲوِتھ تہٕ یُس میانہِ خٲطرٕ پنُن زُو راوِ، سُہ گژھِ سُہ بچاوُن۔\n25.\\tانسان کیا فٲیدٕ چُھ، اگر سُہ سورے دنیا حٲصل کرِ، تہٕ پان راوراوِ، یا کٔرِتھ دِنہٕ؟\n26. یُس تہِ میانہِ تہٕ میانین کلامَن سٍتـ̡ شرم گژھہِ، سُہ گژھہِ انسانہٕ سُند فرزند شرمندہ سپدُن، یێلہِ سُہ پننِس جلال سٍتـ̡ تہٕ مٲلہِ سٕندِس تہٕ مقدس فرشتن ہٕندِس سٍتـ̡ ییہِ شرمندٕ۔\n27.\\tمگر بہٕ چُھس ژے اکھ پزر ونان زِ ییتہِ چھہِ کینہہ کھڑا روزان، یُس نہ خدایہ سٕنز بادشٲہی وُچھِتھ موتُک مزہ چکھ۔\n28.\\tتہٕ یِمو کلامَو پَتہٕ ٲٹھہِ دۅہہٕ پَتہٕ گۆو تٔمۍ پطرس تہٕ یوحنا تہٕ یعقوب نِش تہٕ ووت أکِس پہاڑس پیٹھ دعا کرنہٕ خٲطرٕ۔ {اقوال: یا، چیز}\n29.\\tتہ ییلہ سہ دعا کران اوس، تسند پوشاک اوس سفید، تہ پوشاک اوس سفید۔\n30.\\tتہٕ وُچھ أمِس سٍتـ̡ دۄن نفرن سٍتـ̡ کتھ کرنہٕ، یِم موسیٰ تہٕ الیاس ٲسۍ۔\n31.\\tیُس جلال سٍتـ̡ ظٲہر گوو، تہٕ کورُن پننہِ مرنہٕ کِس بارس مُتعلِق یُس سُہ یروشلمس مَنٛز پورٕ کرُن۔\n32.\\tمگر پطرس تہٕ أمِس سٍتـ̡ یِم أمِس سٍتـ̡ ٲسٕن، تہٕ یێلہِ تِم بیدار گٔیہِ، تِمو وُچھ تٔمۍ سُند جلال تہٕ أمِس سٍتـ̡ کھڑا زٕ نفر۔\n33. تہٕ یێلہِ تِم أمِس نِش نیرِ، پطرس ووٚن عیسیٰ مسیحس زِ یێلہِ روزُن چُھ اسہِ خٲطرٕ اصل: تہٕ أسۍ بناوو تریہ خیمہ ۔ اکھ تۅہہِ خٲطرٕ، تہٕ اکھ موسیٰ سٕندِ خٲطرٕ، تہٕ اکھ الیاس سٕندِ خٲطرٕ: یہ چھنہٕ خبرے زِ تٔمۍ کیا ووٚن۔\n34.\\tییلہ سہ یتھہ پاٹھۍ کتھ کران اوس، اوٚبر آو تہ تمن ژھایہِ تہ تمن لوٚگ اوٚبرس منز اژنہٕ وِزِ کھوژان۔\n35.\\tتہٕ اَکھ آواز دراو اوٚبرٕ منز، یہِ چُھ میون پیاری نیچو، بوزو أمِس۔\n36. تہٕ ییلہِ آواز پتھ کُن گٔیہ، عیسیٰ مسیح آو کُنی زُن لبنہٕ۔ تہٕ تِمو تھوو نزدیک، تہٕ تِمن دۅہن اوس نہٕ کٲنسہ تہِ کٲنسہ تہِ تِمن چیٖزن ہُند وُچھمُت۔\n37.\\tتہٕ سپُد یہِ زِ دٔیمہِ دۅہہ ییلہ تِم بالہٕ پیٹھٕ بۄن وٲتِتھ، واریاہ لُکھ گٔیہِ أمِس سٍتـ̡ سمکھنہٕ۔\n38.\\tتہٕ وُچھِتھ دِژ صحبتُک أکۍ شخٕص دِتھ وَنُن زِ مالک، بہٕ چھُس ژےٚ گُزٲرِتھ پننِس نیچوِس وُچھان، تکیازِ سُہ چھُ میون کُنی شُر۔\n39. تہٕ لو، اکھ روح چُھ أمس رٹان، تہٕ سُہ چُھ اچانک کرٛٮ۪کھ دوان۔ تہ یہ چھہ تس پھٹان زِ سہ چھہ بییہ جھاگ نیران، تہ زخم چھہ تس نش مشکل سان نیران۔\n40.\\tتہٕ میہ کٔر پننین شاگردن درخواست زِ تم کٔرِن أمس کٔڑِتھ کٔرِتھ۔ تہٕ تِم ہیوٚک نہٕ۔\n41. تہٕ حضرت عیسیٰ علیہ السلام ووٚن جواب دِتھ زِ اے کافر تہٕ بدکار نسل، بہٕ کُس کالس روزٕ ژے سٍتـ̡ تہٕ ژے سٍتـ̡ روزُن؟ پنُن نیچو أنِو یور ۔\n42.\\tتہٕ ییلہ سُہ وُنہِ یِنہٕ وول اوس، شیطانن ترٛٲو سُہ تہٕ دِژ أمِس تہٕ دِژٕنـ̡ ۔ تہٕ حضرت عیسیٰ علیہ السلام کٔر ناپاک روحس ملامت تہٕ شُر کوٚرُن شُر شفا تہٕ کوٚرُن دُبارٕ پننِس مٲلِس نِش۔\n43. تہٕ تِم سٲری گٔیہِ خدایہ سٕندِس طاقتور طاقتس پیٹھ حٲران۔ مگر یێلہِ تِم سارِنٕے کُنہِ چیزس پیٹھ حیران گٔیہِ یُس عیسیٰ مسیح کران اوس، تٔمۍ ووٚن پننین شاگردن ،\n44.\\tیِم کَتھٕ گٔژھِن تُہٕندِس کنَن مَنٛز بٔرِتھ، تِکیازِ اِنسان سُند فرزند یِیہِ اِنسانن ہٕندِس اتھس مَنٛز دِنہٕ۔\n45.\\tمگر تِمو ٲس نہٕ یہِ کتھ سمجھ تہٕ یہ ٲس تِمن نِش ژوٗرِ تھونہٕ آمٕژ، تہٕ تِمو گٔیہِ أمِس امہِ کلامَس مُتلق پرژھنہٕ نِش کھوژان۔\n46.\\tاَمہ پَتہٕ گۆو تِمن مَنٛز اکھ استدلال پٲدٕ، یِمو منزٕ کُس کُس گژھہِ سارِوٕے کھۄتہٕ بوٚڈ آسُن۔\n47.\\tتہٕ حضرت عیسیٰ علیہ السلام یُس تِہٕندِس دِلُک خیال وچھِتھ رٔٹِتھ اکھ شُر رٔٹِتھ تہٕ کوٚرُن أمِس سٍتـ̡ ۔\n48.\\tتہٕ ووٚنُن تِمن زِ یُس تہِ میانہِ ناوٕ سٍتـ̡ یہِ شُر میلہِ سُہ چُھہ سُہ چُھہ میہ وصول کٔرِتھ، تہٕ یُس تہٕ یُس میہ سُہ رٔٹِتھ آسہِ، سُہ چُھہ سُہ رٔٹِتھ یُس میہ سارِوٕے سٍتـ̡ سُہ چُھہ سُہ رٔٹِتھ تہٕ یُس\n49. تہٕ یوحنا دیُت جواب تہٕ وونُن، مالک، اسہِ وُچھ تُہندِ ناوٕ سٍتـ̡ شیطان کڈان۔ تہٕ أسۍ چھِ أمِس منع کران، تِکیازِ سُہ چُھ نہٕ اسہِ سٍتـ̡ پٲٹھ\n50. تہٕ حضرت عیسیٰ علیہ السلام ووٚن أمِس زِ یُس نہٕ اسہِ خلاف چُھہ سُہ چُھہ اسہِ خٲطرٕ۔\n51.\\tتہٕ ییلہ وق آو أمِس رٔٹنہٕ یُن، تٔمۍ کٔر یروشلم گژھنہٕ خٲطرٕ بُتھ تھپھ کٔرِتھ،\n52.\\tتہٕ سوٗزۍ تٔمِس بُتھِس برونہہ کُن قاصد تہٕ تِم گٔیہِ أمِس خٲطرٕ تیار کرنہٕ خٲطرٕ سامری ہٕندِس أکِس گامس مَنٛز۔\n53.\\tتہٕ تِمو کٔر نہٕ سُہ قبول، تکیازِ تٔمۍ سُند بُتھ اوس یُتھ زن سُہ یروشلم گژھِ۔\n54.\\tییلہ تٔمۍ سٕندٮ۪و مرید یعقوب تہٕ یوحنا وُچھ، تِمو ووٚن، خداوند، کیا ژٕ کٔرِکھ أسۍ اسمانہٕ پیٹھٕ نار وسُن تہٕ تِمن زٲلِتھ دِنُک حُکُم دِیُو، یِتھٕ پٲٹھۍ الیاس اوس دِژمُت؟\n55.\\tمگر سُہ پھیُر تہٕ دِژُن تِمن ملامت تہٕ وونُن، ژیہ چھے نہٕ پتاہ زِ تُہۍ کمہِ روحہٕ سٍتـ̡ چھِو۔\n56. تکیازِ انسان سُند فرزند چُھ نہٕ انسانن ہٕنز زندگی تباہ کرنہٕ خٲطرٕ آمُت بلکہ چُھ تِمن بچاونہٕ خٲطرٕ آمُت۔ تہٕ تِم گٔیہِ بیٚیِس گامس منٛز۔\n57.\\tتہٕ سپد یہِ زِ ییلہ تِم وتہِ پکان ٲسۍ، أکۍ انسانن ووٚن أمِس زِ خداوند، ییتہِ ژے گژھِ، بہٕ کٔرٕ تتہِ تہِ پَتہٕ۔\n58.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن أمِس زِ پۅژھہٕ پٲٹھـ̡ چُھہ پٲٹھـ̡ پى۪ٹھـ̡ مگر انسان سٕندِس فرزندس چُھ نہٕ کتہِ کلہٕ تراوُن۔\n59.\\tتہٕ تٔمۍ ووٚن بییِس سٍتـ̡ میانہِ پٲٹھۍ۔ مگر تٔمۍ ووٚن، خداوند، میہ دِژ گۅڈٕ گژھ تہٕ میون مول دفن۔\n60. عیسیٰ مسیحن ووٚن أمِس زِ مُردٕ گژھن پنٕنـ̡ مُردٕ دفن کرنہٕ، مگر گژھ تہٕ خدایہِ سٕنزِ بادشٲہی ہٕنز تبلیغ کٔرٕنـ̡ ۔\n61.\\tتہٕ بییِس ووٚن، خداوند، بہٕ کٔرٕ تۅہہِ پتہٕ۔ مگر میہ گژھ گۅڈہ یمن الوداع کٔرتھ، یم میٲنس گرس منز چھہِ۔\n62. تہٕ حضرت عیسیٰ علیہ السلام ووٚن أمِس زِ کانہہ تہِ انسان چُھہ ہلَس پیٹھ اتھہٕ تھٲوِتھ تہٕ پتھ کُن نظر دِتھ چُھہ نہٕ خدایہ سٕنزِ بادشٲہی خٲطرٕ لایق۔","1.\\tیِمو کامہِ پَتہٕ کٔر خداوند باقٕے ستتھ تہِ مقرر تہٕ سوٗزِن تِم زٕ تہٕ زٕ پننِس بُتھِس برونہہ کُن پرٮ۪تھ شہرس تہٕ مقامس مَنٛز، ییتہِ سُہ پانہٕ یِیہِ۔\n2.\\tتَمہِ کِنۍ ووٚن تِمن زِ فصلہٕ چھُ پٔزۍ پٲٹھۍ واریاہ زیادٕ، مگر مزدور چھِ کم۔\n3. پَنٕنہِ وَتہٕ پٔکِو: وُچھِو بہٕ چُھس ژےٚ رامہٕ ہٕندِس مَنٛز دانٛدٕ بٔنِتھ سوزان۔\n4. نہ پرس تُلُن، نہ سِکرِپ، تہٕ نہ بوٗٹ: تہٕ وتہِ کُنہِ تہِ نفرس سلام۔\n5.\\tتہٕ یُس تہِ گرس مَنٛز اژِو، گۅڈٕ وَنُن زِ یَتھ گرس مَنٛز گژھہِ امن۔\n6. تہٕ یێلہِ سُہ دُبارٕ تُہٕندِس سٍتـ̡ دُبارٕ پۯاوُن۔\n7.\\tتہٕ أتھۍ گرس منز روزِو تِتھۍ چیز کھٮ۪وان تہٕ چیوان یِم دِوان چھِ، تکیازِ مزدور چُھ پننہِ کرایہ ہُند لایق۔ گَرٕ گَژھُن نہٕ۔\n8.\\tتہٕ یُس تہِ شہرس مَنٛز اژِو، تہٕ تِم چِھ تِم چیٖز کھٮ۪وان یِم تۅہہِ برونہہ کُن تھاونہٕ آمٕتۍ چھِ۔\n9. تہٕ یِمن بیمارن ہُند شفا دِیُن، تہٕ تِمن ونُن زِ خدایہِ سٕنز بادشٲہی چھے تۅہہِ نزدیک آمٕژ۔\n10.\\tمگر یُس تہِ شہرس منز اژِو، تہٕ تِم نہٕ تۅہہِ رٔٹِتھ، تِمن ہٕنزِ سڑکہِ مَنٛز گژھِو تہٕ ونُن،\n11.\\tچانہِ شہرٕچ گرد تہِ، یُس اسہِ سٍتـ̡ ژٔٹِتھ چُھہ، أسـ̡ چُھہ ژے سٍتـ̡ ژٔٹِھتھ ژٔٹِھتھ تہِ ژٔٹِتھ ژٔٹِھتھ تہِ ژٔٹِتھ ژٔٹِھتھ تہِ ژٔلِتھ ژٔٹِتھ تہِ ژٔلِتھ ژٔلِتھ ژٔٹِتھ تہِ ژٔلِتھ\n12. مگر بہٕ چُھس ژےٚ ونان زِ تمہِ دۅہہ آسہِ سدوم خٲطرٕ تمہِ شہرٕ کھوتہٕ زیادٕ برداش۔\n13.\\tہا ہا ژے کُنہِ ہا ژے بیثسیدا! یێلہِ یێلہِ صور تہٕ صیدانس مَنٛز یِم زبردست کٲم آسہٕ کرنہٕ آمٕژ، یِم ژے سٍتـ̡ کرنہٕ آمٕژ آسہِ، تِمو آسہٕ واریاہ کالہٕ برونہہ توبہ کٔرِتھ، بۄٹہٕ کُلِس تہٕ سوٗرس منز بِہِتھ۔\n14.\\tمگر یہ گژھہِ تۅہہِ کھوتہ زیادہ برداش۔\n15.\\tتہٕ توے یُس آسمانس مَنٛز تھزراونہٕ آمُت چھُ، یُس جہنمَس کُن دِنہٕ یُن۔\n16. یُس تہِ بوزان چُھ، سُہ چُھ میہ بوزان۔ تہٕ یُس تۅہہ حقارت کران چُھ، سُہ چُھ میہ حقارت کران۔ تہٕ یُس مےٚ حقارت کران چھُ، سُہ چھُ أمِس حقارت کران یُس مےٚ سوزمُت چھُ۔\n17.\\tتہٕ ستتھ دُبارٕ خوشی سان واپس، وونُن، خداوند، شیطان تہِ چُھہ تُہندِ ناوٕ سٍتـ̡ اسہِ تابع ۔\n18. تہٕ تٔمۍ ووٚن تِمن زِ میہ وُچھ شیطان آسمانہٕ پیٹھٕ بجلی وسان۔\n19.\\tوُچھ، بہٕ چُھس ژے ناگن تہٕ بچھوَن تہٕ دُشمن سٕندِس سارِنٕے طاقتس پیٹھ قدم تھاونُک اختیار دِوان، تہٕ کُنہِ تہِ طریقہٕ ہیکہِ نہٕ تۅہہِ تکلیف دِتھ۔\n20. اَتھ مَنٛز گژھِو نہٕ خۅش گژھُن، زِ روحہٕ چُھہ تُہٕندِس تابع۔ بلکہ کرو شاد، تکیازِ تہند ناو چھہ جنتس منز لیکھنہ آمت۔\n21. اَتھ ساعتس مَنٛز گۆو عیسیٰ مسیح روحس سٍتـ̡ خۅش تہٕ وونُن، اے باپ، آسمانُک تہٕ زمینُک مالک، بہٕ چُھس تُہند شُکر ادا کران زِ ژے چُھکھ یِم چیز دانشمندن تہٕ ہوشیار نِش ژوٗرِ تھوومٕژ، تہٕ یِم بچن ہٕندِ خٲطرٕ ظٲہر کٔرۍمٕتۍ: توتہِ، بابا۔ تکیازِ یہ اوس تۅہہِ نظرِ منز اصل باسان۔\n22. سٲری چیز چھِ میٲنِس مٲلہِ سٕندِ طرفہٕ دِنہٕ آمٕژ، تہٕ کٲنسہ تہِ چھُنہٕ پتاہ زِ نیچو کُس چُھ، مگر مٲلِس سٕندِس سٍتـ̡ چُھ۔ تہٕ باپ کُس چُھ، مگر نیچو، تہٕ {سُہ} یُس نیچو ظٲہر کرِ۔ {واریاہ قدیم نسخہٕ چھ شعر کس شروعاتس منٛز یم لفظ شٲمل کران، تہٕ پننین شاگردن کُن پھیرِتھ وون}\n23.\\tتہٕ تمٔۍ کٔر سُہ پننین شاگردن نِش تہٕ وونُن خۅد پٲٹھۍ، بابرکت چھِ تِم أچھ یِم تم چیز وُچھان چھِ:\n24. بہٕ چُھس ژےٚ وَنُن زِ واریاہ پیغمبرن تہٕ بادشاہن چُھ تِم چیز وُچھنٕچ خواہش کٔرمٕژ یِم تہٕ تِم چِھہ نہٕ وُچھمٕتۍ۔ تہٕ تِم کتھٕ بوزنہٕ خٲطرٕ یِم تۅہہ بوزان چھِو، تہٕ بوزمُت چُھ نہٕ۔\n25.\\tتہٕ وُچھِتھ ووٚتھ اکھ وکیل ووٚتھ، تہٕ وونُن أمِس لالچ، مالک، بہٕ کیا کرٕ ابدی زندگی ہُند وارث۔\n26.\\tتٔمِس وَنُن زِ شریعت مَنٛز کیا چُھ لیکھنہٕ آمُت؟ ژیہ کتھہ پاٹھۍ چھکھ پران؟\n27. تہٕ تٔمۍ ووٚن جواب، تہٕ ژے کرٕ خداوند پنُن خدایہ پنہٕ نِس پوٗرٕ دِلہٕ سٍتۍ، تہٕ پنٕنِس پوٗرٕ طاقتہٕ سٍتـ̡ تہٕ پنہٕ نِس پوٗرٕ ذہنس سٍتـ̡ محبت کرٕنـ̡ ۔ تہٕ پنُن ہمسایہ تہٕ پنُن پان۔\n28. تہٕ تٔمۍ ووٚن أمِس زِ ژے چُھہ صحیح جواب دِژمُت: یہِ کرُن، تہٕ ژٕ روزٕ زندٕ۔\n29. مگر سُہ اوس عیسیٰ مسیحس ووٚنمُت، تہٕ میون ہمسایہ کُس چُھ؟\n30.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن جواب دِتھ زِ اَکھ {انسان} ووت یروشلم پیٹھٕ یریحو کُن، تہٕ ژوٗرن منز پیوٚو، یٔمۍ أمِس پَنُن پلو ژٔٹِتھ تہٕ زخمی کٔرِتھ ژٔل\n31.\\tتہٕ اتفاقاً آو اَکھ پادٕرۍ اَتھ کُن تہٕ ییلہ أمِس وُچھ، سُہ پوٚک دوٚیمہِ طرفہٕ۔\n32.\\tتہٕ یِتھے پٲٹھـ̡ یێلہِ سُہ اَتھ جایہِ وٲتِتھ، آو تہٕ أمِس کُن وُچھُن، تہٕ دوٚیمہِ طرفہٕ گٔیہِ۔\n33.\\tمگر اَکھ سامری ییلہ سُہ سفر کٔرِتھ ووت ییتہِ سُہ اوس، تہٕ ییلہ أمِس وُچھ، تس گٔیہِ رحمت،\n34.\\tتہٕ گٔیہِ أمِس نِش، تہٕ تٔمۍ سٕندِس زخمس بٔنِتھ، تیٖل تہٕ شراب، تہٕ تھووُن أمِس پننِس درندَس پیٹھ، تہٕ أنِن أکِس سراءِ منٛز، تہٕ کوٚرُن أمِس رٲچھ کٔرِتھ۔\n35.\\tتہٕ پگہہ ییلہ سُہ نیرِ، تٔمۍ کٔڈ زٕ پینس، تہٕ دِتُن میزبانس تہٕ وونُن أمِس رٲچھ کرُن۔ تہٕ ژٕ یُس تہِ زیادٕ خرچ کٔرِتھ، ییٚلہِ بہٕ دُبارٕ یِیہ، بہٕ کَرٕ ژےٚ واپس۔\n36.\\tتۅہہ چُھہ یِمو تریو منزٕ کُس ہمسایہ یُس چورن منز پیوٚو؟\n37. تہٕ ووٚن تٔمۍ سُہ یُس أمِس پیٹھ رحم کٔرِ۔ اَمہِ پتہٕ ووٚن عیسیٰ مسیحن أمِس ، گژھ تہٕ تہٕ تہٕ کٔرِو تِتھۍ پٲٹھۍ ۔\n38.\\tوۅنۍ سپد یہ سپد ییلہ تم گٔیہ، سہ ژاو اکس مخصوص گامس منز، تہ مارتھا ناوچ زنانہِ کٔر تس پننس گرس منز۔\n39.\\tتہٕ أمِس ٲس اکھ بینہِ مریم ناوٕ، یۄس عیسیٰ سٕندِس قدمن نِش بِہتھ تہٕ تٔمۍ سُند کلام بوز۔\n40.\\tمگر مارتھا ٲس واریاہ خدمت کرنہٕ خٲطرٕ مُشکِل، تہٕ آیہِ أمِس نِش تہٕ وونُن، خداوند، کیا ژیہ چھے نہٕ پرواہ کران زِ میانہِ بینہِ چھے مے کُنی خدمت کرنہٕ خٲطرٕ ترٲومٕژ؟ تَمہِ مۄکھٕ دِیُن أمِس زِ سُہ کٔرِو مےٚ مدد۔\n41. تہٕ حضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن أمِس مارتھا، مارتھا، تہٕ ژٕ چُھکھ واریاہن چیزن مُتلق محتاط تہٕ پریشان روزان:\n42. مگر اکھ چیز چُھ ضروری: تہٕ مریمن چُھ سُہ اصل حصہٕ ژٲرمُت، یُس نہٕ أمِس نِش نِنہٕ ییہِ۔","1. تہٕ سپد یہ زِ ییلہ سُہ أکِس خاص جایہِ عبادت کران اوس، ییلہ سُہ بند گوو، تٔمۍ سٕندِس أکۍ شٲگِرن ووٚن تٔمِس خدا، اسہِ ہیچھناوُن ہیچھناوُن، یِتھ کٔنۍ یوحنا تہِ پننین شاگردن ہیچھناوُن۔\n2. تہٕ تٔمۍ ووٚن تِمَن زِ یێلہِ یێلہِ تُہۍ دُعا کران چھِو، وَنُن زِ سٲنـ̡ باپ، یُس آسمانس مَنٛز چُھ، تُہند ناو گژھہِ پاک ۔ تُہٕنٛز بادشٲہی یِیہِ یِنہٕ۔ تُہٕنز مرضی گژھہِ پوٗرٕ کرنہٕ، یِتھ کٔنۍ زٔمیٖنس مَنٛز۔\n3. اسہِ دوہ دوہ دِیو سانہِ دۅہدش روٹی۔ {دۅہ پتہٕ دۅہہ: یا، دۅہہ}\n4. تہٕ سانہِ گۅناہ معاف۔ تکیازِ أسۍ چھہِ پریتھ کٲنسہِ تہِ معافی دِوان یُس اسہِ مقروض آسہِ۔ تہٕ اسہِ مہ کرو نہ فتنہ منز۔ مگر اسہِ بد نِش بچاو۔\n5. تہٕ تٔمۍ ووٚن تِمَن زِ تۄہہِ منٛزٕ کُس آسہِ یار، تہٕ نصف رٲژ گژھِ أمِس نِش، تہٕ أمِس وَنُن یار، مےٚ دِیُن ترےٚ روٹ۔\n6.\\tتکیازِ میون اکھ دوست چھہ میہ نش آمُت، تہٕ میہ چھہ نہ تس برونہہ کنہِ تھاوُن کانہہ تہِ؟ {منز...: یا، پننہِ وتہِ نِش نیبر}\n7. تہٕ سُہ دِیہِ أنٛدرِ سٍتـ̡ جواب تہٕ وَنُن، مے کٔرِو نہٕ پریشان: دروازٕ چُھ وۅنۍ بنٛد، تہٕ میٲنۍ شُرۍ چھِ میہ سٍتـ̡ بسترس منز۔ بہٕ ہیوٚک نہٕ ژےٚ تھوٚد تہٕ دِتھ۔\n8. بہٕ چُھس ژےٚ وَنُن، یودوَے سُہ تھوٚد تہٕ دِیہِ نہٕ أمِس دِنہٕ، کیازِ سُہ چُھ أمِس دوس، توتہِ چُھہ سُہ وۅتھان تہٕ دِیہِ تیوٗت تٔمِس ضروُرت۔\n9. تہٕ بہٕ چُھس ژےٚ وَنُن، پرژھہٕ تہٕ یہِ یِیہِ دِنہٕ۔ ژھانڈِو، تہٕ ژیہ لٔبِو؛ دستک دِیُو، تہٕ یہِ یِیہِ تۄہہِ خٲطرٕ یلہٕ کرنہٕ۔\n10.\\tپریتھ کٲنسہِ یُس منگان چُھ، سُہ چُھہ وصول کرُن؛ تہٕ یُس ژھانڈان چُھ، سُہ چُھ لبان۔ تہٕ یُس ٹاس دِیہِ تٔمِس خٲطرٕ یِیہِ یلہٕ کرنہٕ۔\n11.\\tاگر کانہہ نیچو تہِ یُس مول آسہِ، سہ دِیہ تس کنہِ کنہِ؟ یا اگر {سُہ گاڈٕ پرژھہِ}، کیا سُہ گاڈٕ خٲطرٕ دِیہ أمِس ناگ؟\n12.\\tیا اگر سُہ ٹھوٗل منگِہ، کیا سُہ دِیہِ أمِس بِچھوٗ دِنہٕ؟ {پیشکش: Gr. give}\n13. تێلہِ یێلہِ تہٕ یێلہِ تہٕ یێلہِ بُرٕ بٔرِتھ زانِو زِ پننین شُرین کِتھ کٔنۍ چُھ اصل تحفہٕ دِنہٕ: تُہُند آسمانی باپ کوتاہ دِیہِ تِمن ہُند روح القدس یُس أمِس منگان چُھ؟\n14. تہٕ سُہ اوس اکھ شیطان کڈان تہٕ سُہ اوس گونگ۔ تہٕ یہ سپد ییلہ شیطان نیبر گوو، گونگن کٔر کتھ۔ تہٕ لوٗکھ ٲسۍ حیران۔\n15.\\tمگر تِمو منزٕ کینہہ ووٚن زِ تٔمۍ کٔر شیطانن ہٕندِس سردار بیلزبوب سٕندِ ذریعہٕ شیطان کٔڑِتھ۔ {بیلزیبب: Gr. Beelzebul}\n16.\\tتہٕ باقیو لٔگِتھ أمِس آسمانہٕ نِش نشانہٕ ژھاران۔\n17.\\tمگر تِمن ہٕندِس خیالس زٲنِتھ ووٚن تِمن زِ پرٮ۪تھ کانہہ سلطنت یُس پانس خلاف تقسیم کرنہٕ آمُت چھُ، سُہ چُھ ویران کرنہٕ آمُت۔ تہٕ مکانس خلاف اکھ مکانہٕ {تقسیم} چُھ پیوان۔\n18.\\tاگر شیطان تہِ پانس خلاف تقسیم سپدِ، تٔمۍ سٕنز سلطنت کِتھہ پٲٹھۍ؟ تکیازِ تۅہہ چھہ ونان زِ میہ کٔر بیلزبوب سندِ ذریعہ شیطان کڈان۔\n19. تہٕ اگر میہ بیلزبوب سٍتۍ شیطان کٔڑِتھ کٔرِتھ، تہٕ کٔمۍ سٕندِ دٔسۍ چُھہ تُہند نیچو کٔڈِتھ؟ لہذا گژھن تم تہندِ جج بنن۔\n20. مگر اگر بہٕ خدایہ سٕنزِ اونگجہِ سٍتـ̡ شیطان کڈِتھ کٔرِتھ، تێلہِ چُھہ بێیہِ شَک زِ خدایہِ سٕنز بادشٲہی چُھہ توے سٍتـ̡ آمُت۔\n21.\\tییلہ اکھ طاقتور شخص پننِس محلس رژھراوان چُھ، تٔمۍ سُند مال چھُ امن آسان:\n22.\\tمگر ییلہ أمِس کھۅتہٕ زیادٕ طاقتور یُس أمِس پیٹھ یِوان تہٕ أمِس پیٹھ غالب گژھہِ، سُہ چھُ أمِس نِش پنُن سورُے ہتھیار نِوان یُس أمِس بھروسہٕ اوس تہٕ پنُن مال بٲگراوان۔\n23. یُس نہٕ میہ سٍتـ̡ چُھہ سُہ چُھہ میانہِ خلاف تہٕ یُس نہٕ میہ سٍتـ̡ جمع سپدان چُھ، سُہ چُھ منتشر سپدان۔\n24. یێلہِ کُنہِ انسانس سٍتـ̡ ناپاک روح نیران چُھ، سُہ چُھ خشک جاین مٔنزۍ پکان تہٕ آرام ژھاران۔ تہٕ کانٛہہ تہِ لٔبِتھ چھُس نہٕ سُہ وَنُن زِ بہٕ واپس، یَتہِ بہٕ نیبر نیران اوسس۔\n25. تہٕ ییلہ سُہ یِوان چُھ، سُہ چُھ وُچھان تہٕ سجاونہٕ آمُت۔\n26. اَمہِ پَتہٕ چُھ سُہ نیران، تہٕ پانس کھۅتہٕ زیادٕ بدکار سَتھ روحہٕ نِش نِوان۔ تہٕ تِم چھِ اژان تہٕ اَتہِ روزان: تہٕ تٔمِس انسان سٕنز ٲخری {حالت} چِھ گۄڈنِکہٕ کھوتہٕ بدتر آسان۔\n27.\\tتہٕ سپد یہ کتھ کرنہٕ وِزِ تٔمۍ سٕنزِ أکِس زنانہِ ہٕنز آواز تُلتھ تہٕ وونُن أمِس زِ سُہ رحم یُس ژے زیٚنہٕ چُھ، تہٕ یُس ژے چوسُن چُھس۔\n28.\\tمگر تٔمۍ ووٚن، آ، بٔلکہِ چھِ تِم بابرکت یِم خدایہِ سُند کلام بوزان چھِ، تہٕ یہِ رژھراوان چھِ۔\n29.\\tتہٕ ییلہ لُکھ اَکہٕ وٹہٕ جمع گٔیہِ، تٔمۍ ہیوٚتُن وَنُن زِ یہِ چھُ اکھ بدکار نسل، تِم چھِ اکھ نشانی ژھاران۔ تہٕ اتھ گژھہِ نہٕ کانہہ نشانہٕ دِنہٕ، مگر یونس پیغمبر سُند نشانہٕ۔\n30.\\tیِتھے پٲٹھـ̡ اوس یونس نینیوین ہٕندِ خٲطرٕ نشانہٕ، تِتھے پٲٹھـ̡ آسہِ یێمہِ نسلہٕ سٍتـ̡ انسانہٕ سُند فرزند تہِ۔\n31.\\tجنوبٕچ ملکہ گژھہِ امہِ زمانہٕ کین مردن سٍتـ̡ فٲصلس مَنٛز وۅتھنہٕ تہٕ تِمن ہٕنز مذمت کرٕن: تکیازِ سُہ ٲس سُلیمان سٕنز حکمت بوزنہٕ خٲطرٕ زمینہٕ کِس انتہٲیی حصس پیٹھٕ آمٕژ۔ تہٕ وچھو، یتہِ چھہ سلیمان کھوتہ بوڈ {is}۔\n32.\\tنَوُن ہٕندِس لُکھ یِمن سٍتـ̡ یێمہِ نسلہٕ سٍتـ̡ وُتھنہٕ تہٕ أمِچ مذمت کٔرٕن: کیازِ تِمو کٔر یونس سٕنزِ تبلیغس پیٹھ توبہٕ۔ تہٕ وُچھِو، یَتہِ چھُ جونس کھۅتہٕ بوٚڈ {چھُ}۔\n33.\\tکانہہ تہِ انسان ییلہ شمع زٲلِتھ آسہِ، سہ چھہ کُنہِ خفیہ جایہ تھووُن، نہ کُنہِ بُشلس تلہ کنہِ بلکہ شمعس پیٹھ، یُس اژان چھہِ تم گاش وُچھِتھ۔\n34.\\tجسمُک گاش چھُ أچھ: تێلہِ ییلہ چانۍ أچھ کُنی آسہِ، تُہند سورُے جسم تہِ چُھ گاشہٕ سٍتـ̡ بٔرِتھ آسان۔ مگر ییلہ {تہنز اچھ} بد آسہِ، تہند جسم تہِ چھہ اندپکۍ سٍتۍ بٔرتھ۔\n35. تَمہِ مۄکھٕ تھاوُن زِ یُس گاش تۅہہِ مَنٛز چُھ، سُہ گژھہِ نہٕ انہِ گوٚٹ۔\n36.\\tتێلہِ اگر تُہند سورُے جسم گاشہٕ سٍتـ̡ بٔرِتھ آسہِ، یێلہِ نہٕ کانہہ حصہٕ انہِ گوٚٹ آسہِ، سُہ گژھہِ گاشہٕ سٍتـ̡ بٔرِتھ، یِتھٕ پٲٹھۍ چُھہ شمعہٕ سٍتـ̡ گاشہٕ سٍتـ̡ گاش دِوان۔ {چمک...: Gr. اکھ شمع پننہِ چمکدار چمک}\n37.\\tتہٕ یێلہِ أمِس کتھ کٔرِتھ، أکۍ فریسی یَن کٔر أمِس سٍتـ̡ کھٮ۪نہٕ خٲطرٕ، تہٕ سُہ گوٚو اندر تہٕ بیوٹھ ماز کھٮ۪نہٕ۔\n38.\\tتہٕ ییلہ فریسی ین وُچھ، سُہ گوٚو حٲران زِ تٔمِس اوس نہٕ شامس برونہہ گۅڈنچہ لٹہِ واش کٔرمٕژ۔\n39. تہٕ خداوند ووٚن أمِس زِ وۅنۍ کٔرِو یێلہِ تہٕ تھالہِ ہٕندِس نیبرِمِس حصس صاف کٔرِو۔ مگر تہند اندرم حصہ چھہ بدکاری تہ شرارت سیتۍ بٔرتھ۔\n40.\\tبیوقوف، کیا چھہ نہ سہ بنوو یُس بوٚڈ چھہ سہ تہِ بناوان یُس اندر تہِ چھہ؟\n41.\\tمگر یِتھٮ۪ن چیزن ہٕندِس خیرات دِیُن۔ تہٕ وُچھو، سٲری چیز چھِ تۅہہِ خٲطرٕ پاکیزہ۔ {of...: یا، یتھ کٔنۍ تُہۍ قٲبل چھِو}\n42.\\tمگر فریسیو ہٕندِ خٲطرٕ افسوس! تکیازِ تم چھہِ پٔدنہ تہ پریتھ قسمہ کین جڑی بوٹین تہ فیصلہ تہ خدایہ سٕندِ محبتس پیٹھ قبضہ کرُن: یِم پزِ تہِ کرُن، تہٕ بییِس تراوُن نہٕ۔\n43. ہا ہا فریسیو! تکیازِ تم چھہِ یہودی عبادت خانن منز پیٹھمین نشستن تہ بازرن منز سلام پسند کران۔\n44.\\tہا ہا تم کاتب تہٕ فریسی، منافقو! تکیازِ تم چھہِ قبرن ہندۍ پاٹھۍ یم نہ ظٲہر سپدان چھہِ، تہ یمن پیٹھ پکان چھہِ تم چھہِ نہ تمن نش خبر۔\n45.\\tاَمہِ پتہٕ دِیُت أکِس وکیلَس جواب، تہٕ وونُن أمِس آقا، یِتھٕ پٲٹھۍ وَنُن زِ تُہۍ چھِو اسہِ تہِ ملامت کران۔\n46.\\tتہٕ ووٚن تۅہہ تہِ ہا ہا وکیل! تِکیازِ تُہۍ چھِو نفرن تُلنہٕ خٲطرٕ تکلیف دِنہٕ خٲطرٕ بوج، تہٕ تُہۍ چھِو نہٕ پانہٕ أکِس اونگجہِ سٍتۍ بور لاگان۔\n47.\\tافسوس! تکیازِ تم چھہِ پیغمبرن ہٕندِ قبر تعمیر کٔرۍمٕتۍ، تہٕ تہندیو مٲلو کٔر تم مار۔\n48. پٔزۍ پٲٹھۍ چھِو تُہۍ گواہ دِوان زِ تُہۍ چھِو پننین مٲلن ہٕندِس اعمال ہُند اجازت دِوان، تِکیازِ تِمو چھِ پٔزۍ پٲٹھۍ تِم مٲرِتھ تہٕ تِمن ہٕندِ قبر بناوان چھِ۔\n49.\\tتێلہِ چُھہ خدایہ سٕنز حکمت تہِ وۆن، بہٕ سوزٕ تِمن پیغمبرن تہٕ رسول، تہٕ یِمو منزٕ کینہہ مارن تہٕ ستاونہٕ یِن:\n50.\\tیُس سارِنٕے پیغمبرن ہُند خون، یُس دنیاہٕچ بنیادٕ سٍتـ̡ وُسنہٕ آمُت اوس، یێمہِ نسلہٕ سٍتـ̡ گژھہِ ضروری۔\n51.\\tہابیل سٕندِ خونہٕ پیٹھٕ زکریا سٕندِس خونس تام، یُس قربان گاہ تہٕ مندرس درمیان ختم گومُت: پٔزۍ پٲٹھۍ چُھس بہٕ ژے ونان زِ یێمہِ نسلہٕ خٲطرٕ گژھہِ یہِ ضروری۔\n52.\\tوکیلن ہٕندِ خٲطرٕ افسوس! تکیازِ تم چھیہ علمچ کُنز نِتھ ژٔٹۍمٕژ: تہٕ یِم اژان ٲسۍ، تم آیہ نہ رُکاوٹ۔ {رُکاوٹ: یا، فوربد}\n53. تہٕ یێلہِ تٔمِس یِم کتھ وَننہٕ یِوان، کاتب تہٕ فریسیو ہیوٚت أمِس سٍتـ̡ زور دِنہٕ تہٕ أمِس واریاہن کتھن ہٕنز کتھ کرنہٕ خٲطرٕ اِشارٕ دِنہٕ:\n54.\\tأمِس پیٛارُن تہٕ أمِس ٲسِس منزٕ کینہہ رٹُن یُتھ تِم أمِس پیٹھ الزام لگاونہٕ یِن۔","1. أتھۍ وقتس منز، ییلہ واریاہ لُکھ جمع گٔیہِ، یُتھ زن تِم اکھ أکِس پیٹھ لٔگِتھ، تٔمۍ ہیوٚت پننین شاگردن سارِوٕے کھۄتہٕ گۄڈٕ ونُن، یُس منافقت چھُ۔\n2. تکیازِ کانہہ تہِ چھہ نہ احاطہ کرنہ آمت، یُس نہ ظٲہر سپدِ۔ نہ چھپِتھ، یہ گژھہِ نہ پتاہ۔\n3. تێمہِ مۅکھہ یُس تہِ ژے اوندپِس منز کتھ کٔرمٕژ سُہ گژھہِ گاشس مَنٛز بوزنہٕ یُن۔ تہٕ یُس ژے المارن منز کنن منز کتھ کٔرمٕژ چھِ، سُہ گژھہِ گرن پیٹھ اعلان کرنہٕ۔\n4. تہٕ بہٕ چُھس ژےٚ میانین دوستو وَنُن زِ تِمن نِش گژھ نہٕ کھوژُن یِم جسمس ماران چھِ، تہٕ تمہ پتہٕ گژھن نہٕ تِمن ہٕندِس سٍتـ̡ تہٕ یِمن ہٕندِس سٍتـ̡ تہٕ یِمن ہٕندِس سٍ\n5. مگر بہٕ کرٕ ژے خبردار یُس ژے کھوژُن: تس کھوژُن، یُس مارنہٕ پتہٕ جہنمس منز تراونُک طاقت چُھ۔ آ، بہٕ چُھس ژےٚ ونان، أمِس کھوژُن۔\n6.\\tپانژھ چُھہ نہ دۅن فارٹینگن منز کٕننہٕ آمُت، تہٕ یِمو منزٕ چھُنہٕ اکھ تہِ خدایہ سٕندِ برونہہ کُن مشراونہٕ آمُت؟\n7.\\tمگر تہندس کلس تہِ چھہ گنزراونہ آمت۔ تَمہِ کِنۍ گژھِ نہٕ خوفہٕ: تُہۍ چھِو واریہو چُرِیو کھۅتہٕ زیادٕ قٲمِل ۔\n8. بہٕ چُھس تہِ وَنُن زِ یُس تہِ یُس میہ انسانن برونہہ کُن اقرار کرِ، سُہ کرِ خدایہ سٕندِس فرشتن برونہہ کُن اقرار کرُن:\n9.\\tمگر یُس میہ انسانس برونہہ انکار کرِ، سہ گژھہِ خدایہ سٕندِس فرشتن برونہہ کُن انکار کرنہٕ۔\n10. تہٕ یُس تہٕ یُس انسان سٕندِس فرزندس خلاف کتھ کرِ، سُہ گژھہِ معافی دِنہٕ، مگر یُس روح القدس خلاف کفر کرِ، سُہ گژھہِ نہٕ معاف۔\n11.\\tییلہ تۅہہِ عبادت خانن تہٕ مجسٹریٹن تہٕ طاقتن نِش انِن، تێلہِ گژھہِ نہٕ یہ خیال زِ توہہِ کِتھہ کٔنۍ تہٕ کیا جواب دِیُو، یا کیا ونُن:\n12.\\tتکیازِ روح القدس کرِ تۅہہِ امی ساعتہ ہیچھناوُن یُس ژیہ ونُن پزِ کرُن۔\n13.\\tتہٕ أکِس صحبتَس ووٚن أمِس مالک، میٲنِس بٲیِس کتھ کٔرِتھ زِ سُہ کٔرِن وَرث میانہِ سٍتـ̡ بٲگراونہٕ۔\n14.\\tتہٕ تٔمۍ ووٚن أمِس انسان، کٔمۍ بنوو میہ ژے پیٹھ قاضی یا تقسیم کرن وول۔\n15.\\tتہٕ تٔمۍ ووٚن تِمن خبردار تہٕ لالچ نِش ہوشیار روزُن، تکیازِ انسان سٕنز زندگی چھے نہٕ تِمن چیزن ہٕنزِ کثرت سٍتـ̡ آسان یِم أمِس نِش آسہِ۔\n16.\\tتہٕ تٔمۍ ووٚن تِمن سٍتـ̡ اکھ تمثیل تہٕ وونُن زِ أکِس خاص مالدار سٕندِ زمینہٕ سٍتـ̡ آو سٮ۪ٹھاہ سٍتـ̡ برونہہ کُن۔\n17.\\tتہٕ تٔمۍ سونچُن پانس اندر، بہٕ کیا کرٕ بہٕ، کیازِ مےٚ چُھنہٕ کانہہ گنجایش ییتہِ پنُن پھل دِنہٕ خٲطرٕ؟\n18. تہٕ تٔمۍ ووٚن، بہٕ کرٕ یۅہے کرُن: بہٕ کرٕ پنٕنۍ کوٹھہٕ والہ، تہٕ بٔڈ تعمیر کرٕ ۔ تہٕ اَتہِ دِیہٕ بہٕ پنٕنۍ سٲری مٮ۪وٕ تہٕ پنُن سامان۔\n19. تہٕ بہٕ وَنُن پننِس روحس سٍتـ̡ روح، ژے چُھس واریہن ؤرین ہُند مال تھاونہٕ آمُت۔ پنٕنۍ آسٲنی کرُن، کھیٛو، پییُن، {تہٕ} خۄش۔\n20.\\tمگر خداین ووٚن تمِس {ژے} بیوقوف، از رٲژ گژھہِ چانۍ روح ژے نِش ضرورت، تیلہِ کُس آسہِ تِم چیز یِم ژے فراہم کٔرۍمٕتۍ؟ {تُہٕندِ...: Gr. کیا تِمن چُھ تُہنزِ روحٕچ ضرورت}\n21. یێلہِ چُھ سُہ یُس پانس خٲطرٕ خزانہٕ تھاوان چُھ، تہٕ خدایہ سٕندِ طرفہٕ چُھ نہٕ امیر آسان۔\n22.\\tتہٕ تٔمۍ ووٚن پننین شاگردن زِ تێلہِ چُھس بہٕ ژے ونان، پننہِ زُوُک خیال کرُن نہٕ یُس تہٕ کیا کھٮ۪و۔ نہ جسمہٕ خٲطرٕ، یُس تہٕ ژیہ لاگُن۔\n23.\\tزندگی چھیہ مازہ کھوتہ زیادہ، تہ جسم چھہ پوشاک کھوتہ زیادہ۔\n24.\\tکۅکرِ پیٹھ غور کرُن: تکیازِ تم چھہِ نہ وونۍ تہ نہ لُٹان۔ یمن منٛز نہ گودام تہٕ نہ گودام چُھ۔ تہٕ خدا چُھ تِمن کھٮ۪وان: تُہۍ کوتاہ چھِو مرغو کھۅتہٕ بہتر۔\n25.\\tتہِ ژیہ منزٕ کُس ہیکہِ سونچِتھ تٔمۍ سٕندِس قدس اکھ کیوبِٹ ہُرراوِتھ؟\n26.\\tاگر نہ تیلہِ سۅ کٲم کٔرِتھ یُس کم از کم آسہِ، تیلہِ کیازِ کرو باقی چیزن متعلق سوچ۔\n27.\\tوچھو لِلہِ کِتھہ پاٹھۍ چھہِ کھسان: تم چھہِ نہ محنت کران، نہ چھہِ نژان۔ تہٕ توتہِ چُھس بہٕ ژےٚ ونان زِ سلیمان اوس نہٕ یِمو منزٕ أکِس ہٕندۍ پٲٹھۍ۔\n28.\\tیێلہِ یێلہِ خدایہِ گاسہٕ یُس از کھہس مَنٛز چُھ، تہٕ پگہہ دِیہِ تنورس مَنٛز تراونہٕ۔ اے کم ایمانہٕ والۍ، کوتاہ بییہ تہِ پلو دِیہِ۔\n29.\\tتہٕ کیا کھٮ۪وان چھِو، یا کیا چیٚو، تہٕ نہ گژھِو شک کٔرِتھ۔ {نہ تہِ...: یا، روزو نہ احتیاط سان سسپنس منز}\n30.\\tیِمن سارِنٕے چیزن خٲطرٕ چھِ دنیاہٕکۍ قومن ژھاران: تہٕ تُہند مٲل چُھ زانان زِ تۅہہِ چُھہ یِمن چیزن ہٕنز ضرورت۔\n31.\\tبلکہ کرو خدایہ سٕنز بادشٲہی ژھاران۔ تہٕ یِم سٲری چیز یِن توے سٍتـ̡ شٲمل کرنہٕ۔\n32.\\tخوفہٕ نہٕ کرُن، لۅکٹۍ ریو۔ تکیازِ یہ چُھہ تۅہہِ مٲلہِ سٕنز خوشی زِ ژےٚ بادشاہی دِنہٕ خٲطرٕ۔\n33.\\tیُس تہِ نِش چھُ، تہٕ کٔرِو خیرات دِنہٕ۔ پانس کٔرِو بیگ یُس نہ پرون آسہِ، آسمانس منز اکھ خزانہٕ یُس نہ ناکام آسہِ، ییتہِ نہ کانہہ چور واتان آسہِ، تہٕ نہ کیم کرِ بدکار۔\n34.\\tیَتھ تُہُند خزانہٕ آسہِ، تتہِ آسہِ تُہند دِل تہِ۔\n35.\\tپنہٕ نِس کمرس گٔنڈِتھ تہٕ گاش دزان۔\n36. تہٕ تُہۍ چھِو تِمن انسانن ہٕندۍ پٲٹھۍ، یُس پننِس مٲلکُک انتظار کران چُھ، ییلہ سُہ کھاندرٕ پیٹھٕ واپس۔ زِ ییلہ سُہ یِوان تہٕ دستک دِیہِ، تِم گژھن أمِس خٲطرٕ فوراً کھولنہٕ۔\n37.\\tتِم خادم، یِمن ہُند رب یِنہٕ وِزِ یِمن ہُند وُچھُن وُچھان آسہِ، یێلہِ بہٕ چُھس ژے ونان زِ سُہ کرِ پان لٲگِتھ تہٕ یِمن ماز کھٮ۪نہٕ خٲطرٕ بِہناوُن، تہٕ یِمن ہٕنز خدمت کرِ۔\n38.\\tتہٕ اگر سُہ دۆیمِس پَرِ مَنٛز یِیہ، یا تریمہِ پَرِ مَنٛز یِیہِ، تہٕ یِمن ہٕندِس مَنٛز یِیہ، تِم خادمَن چھِ بابرکت ۔\n39.\\tتہ یہ زان زِ اگر گرِ کس نیک انسانس پتاہ آسہِ ہے زِ ژوٗر کمہِ ساعتہ ییہ تیلہِ آسہِ ہے سہ وچھان، تہ پنن مکانہ ژٹُن آسہِ نہ۔\n40.\\tتێلہِ تہِ گژھِو تیار: تکیازِ انسان سُند فرزند چُھ تتھ وقتس پیٹھ یوان یێلہِ نہٕ تۅہہ سوچان چُھ۔\n41. پطرس ووٚن أمِس خداوند، کیا ژٕ چُھہ یہِ تمثیل اسہِ سٍتـ̡ یا سارِنٕے سٍتـ̡ وَنان۔\n42.\\tتہٕ خداوند ووٚن، تیلہِ کُس چُھ سُہ وفادار تہٕ دانا نگر، یُس {تٔمِس} خداوند پننِس گرس پیٹھ حکمران بناوِ، یُس تِمن مُقرر وقتس پیٹھ مازُک حصہٕ دِیہِ؟\n43. سُہ خادم، یُس تٔمۍ سُند آقا یِنہٕ سٍتـ̡ یێلہِ یێلہِ سُہ یێلہِ یێلہِ سُہ وُچھِتھ وُچھِ۔\n44. بہٕ چُھس پٔزۍ پٲٹھۍ ژےٚ ونان زِ سُہ بَناوِ أمِس سارِنٕے سارِنٕے چیزن پیٹھ حُکوٗم۔\n45.\\tمگر یێلہِ سُہ خادم پننِس دِلس مَنٛز وَنُن چُھ، میون آقا چُھ تٔمِس یِنُک ژیر کَران۔ تہٕ کرِ نوکروں تہٕ کورٮ۪ن مار دِنہٕ، تہٕ کھٮ۪نہٕ چیٚنہٕ تہٕ شرابہٕ روزُن شروع۔\n46.\\tتٔمِس خادمُک رب ییہِ تتھ دۅہس ییلہ نہٕ سُہ أمِس وُچھان آسہِ، تہٕ أکِس ساعتہ یُس نہٕ تس بے خبر آسہِ، تہٕ کرِ أمِس کُنٮ۪ن سٍتـ̡ پنُن حصہٕ دِنہٕ۔ {ژٹ...: یا کٔرِو أمِس ژٹ}\n47.\\tتہٕ سُہ خادم یُس پننِس آقا سٕنزِ مرضی زانان اوس، تہٕ یُس نہٕ پانس تیار کورمُت، تہٕ نہ کرُن پننہِ مرضی مطٲبق، یُس واریہو پٹیو سٍتـ̡ مارنہٕ یُن۔\n48.\\tمگر یُس نہٕ پتاہ آسہِ، تہٕ یُس نہٕ پتاہ آسہِ، تہٕ یُس کُنہِ سٍتـ̡ مارنہٕ یُن۔ یٔمِس سٍتـ̡ واریاہ زیادٕ دِنہٕ چُھ، تٔمِس سٍتـ̡ چُھہ أمِس سٍتـ̡ زیادٕ مُطالبہٕ۔\n49. بہٕ چُھس زمینس پیٹھ نار سوزنہٕ خٲطرٕ آمُت۔ تہٕ بہٕ کیا کرِ، اگر یہ گۅڈے دزنہٕ آسہِ؟\n50. مگر میہ چُھہ بپتسمہ دِنہٕ خٲطرٕ۔ تہٕ بہٕ کِتھہ کٔنۍ چھُس مُشکِل یوٚت تام یہ پوٗرٕ سپدِ! {straitened: or, pained}\n51. کیا تۅہہ چُھہ فرض کٔرِتھ زِ بہٕ چُھس زمینس پیٹھ امن دِنہٕ خٲطرٕ آمُت؟ بہٕ چُھس ژیہ وَنُن، نہ۔ بلکہ تقسیم:\n52.\\tتکیازِ امہ پتہ گژھن أکِس گرس منز پانژھ تقسیم کرنہٕ، تریہ دۅن خلاف تہٕ تریہ خلاف زٕ۔\n53.\\tمول گژھِ نیچوِس خٕلاف تہٕ نیچو مٲلِس خٕلاف۔ موج کورِ خلاف تہٕ کورِ ماجہ خلاف۔ موج پننہِ نۄشہِ خٕلاف، تہٕ نوٗر پننہِ ماجہِ خٕلاف۔\n54. تہٕ تٔمۍ ووٚن لُکن تہِ زِ ییلہ تم مغرب کِنۍ اکھ اوبُر وُچھان چھِو، سیدِ سیود وُچھِو، تتہِ چُھ روٗد یوان۔ تہٕ یہٕ چُھ تہٕ یہٕ چُھ۔\n55. تہٕ ییلہ {تم وُچھو} جنوبی واو چُھ، تہٕ تم چِھ ونان، تتہٕ گژھہٕ گرم۔ تہٕ یہٕ چُھ سپدان۔\n56. منافقو، تم ہیکو آسمانُک تہٕ زمینُک بُتھ وُچھِتھ۔ مگر یہ کتھہ پاٹھۍ چھہ نہ ژیہ یمہِ لٹہِ سمجھان۔\n57.\\tآ، تہٕ کیازِ چھِو نہٕ تۅہہ پانس تہِ فیصلہ کران زِ صحیح کیا چُھ؟\n58.\\tییلہ تہۍ پننِس مُخٲلفس سٍتـ̡ مجسٹریٹس نِش گژھِو، یێلہِ تہٕ تُہۍ گژھِو تٔمِس نِش نجات دِنہٕ۔ یِم نہٕ سُہ ژےٚ جَجَس نِش دِیہِ، تہٕ جج دِیہِ ژےٚ افسرَس حوالہٕ، تہٕ افسرَن دِیہِ تۄہہِ جیلَس منٛز۔\n59.\\tبہٕ چُھس ژے وَنُن زِ توٚت تام گژھِو نہٕ تتہِ نیرُن، یوٚت تام نہٕ ژے ٲخری مِٹ دِیہِ۔","1. اَتھ موسمس منز ٲسۍ کینہہ موجود یِمو أمِس گلیلیاہن مُتلق وَننہٕ آمُت، یِمن ہُند خوُن پیلاطس تِہٕندِس قۄربٲنی سٍتـ̡ رٔلِتھ اوس ۔\n2.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمن جواب دِتھ زِ یِم گلیلیائی ٲسۍ سارِنٕے گلیلیَن ہٕندِ کھۅتہٕ زیادٕ گۅنہگار، تِکیازِ تِمن ہٕندِس یِتھٕے مُتٲثِر گٔیہِ؟\n3. بہٕ چُھس ژےٚ وَنُن، نَہ: مگر، یوٚت تام نہٕ توبہ کرِو، تِتھۍ پٲٹھۍ گژھِو تُہۍ سٲری فنا گٔژھِو۔\n4. یا تِم ارداہ یِمن پیٹھ سیلومُک مینار پیوٚو تہٕ تِم مارِ، کیا تُہۍ چھِو باسان زِ تِم ٲسۍ یروشلمس مَنٛز روزن والٮ۪ن سارِنٕے انسانن کھوتہٕ زیادٕ گنہگار؟ {گۅنہگار: یا، قرضدار}\n5. بہٕ چُھس ژےٚ وَنُن، نہٕ: مگر، یوٚت تام نہٕ توبہٕ کرِو، تُہۍ گژھِو تِتھۍ پٲٹھۍ فنا گٔژھِو۔\n6.\\tتٔمۍ کٔر یہ تمثیل تہِ۔ اکس شخصس اوس پننس انگورس منز انجیر کُل لگٲومُت۔ تہٕ سُہ آو تہٕ اَتھ پٮ۪ٹھ پھل ژھانڈنہٕ، تہٕ لوٚبُن نہٕ کیٚنٛہہ۔\n7.\\tاَمہِ پتہٕ ووٚن تٔمۍ پننِس انگور کِس باغس منز، وُچھ، یِمن ترٮ۪ن ؤرین چھُس بہٕ یَتھ انجیر کُلِس پیٹھ پھل ژھانڈان تہٕ لٔبِتھ چھُس نہٕ کانہہ تہِ: ژٹُن ژٹُن۔ یہ کیازِ چھہ زمینس پیٹھ دباونہ آمت؟\n8.\\tتہٕ تٔمۍ ووٚن أمِس جواب دِتھ، خداوند، یێمہِ ؤریس تہِ تراوُن، یوٚت تام بہٕ اتھ کھٔنِتھ تہٕ گُرِ دِیہِ:\n9.\\tاگر یہ پھل دِیہِ، {اچھ}: تہٕ اگر نہ، تیلہِ ژٔٹِتھ ژٔٹِتھ ژٔٹِو۔\n10.\\tتہٕ سُہ اوس سبت دۅہہٕ أکِس عبادت خانس مَنٛز پرناوان۔\n11.\\tتہٕ وچھ اَکھ زنانہٕ یٔمِس ارداہ ؤری بیمارِ ہُند روح اوس، تہٕ ٲس رٔلِتھ رٔلِتھ تہٕ ہیوٚک نہٕ کُنہِ تہِ پٲٹھۍ۔\n12.\\tتہٕ یێلہِ عیسیٰ علیہ السلام وُچھ أمِس بُلوو، تہٕ وونُن أمِس زنانہٕ، تہٕ ژے چُھکھ پننہِ کمزوری نِش آزاد گومُت۔\n13. تہٕ تٔمۍ تھوو أمِس پیٹھ اتھہٕ، تہٕ یکدم گٔیہٕ سۄ سیدٕ تہٕ خدایہ سٕنز حمد کٔرٕنۍ۔\n14.\\tتہٕ یہِ عبادت خانہٕ ہٕندِس حاکمن دِژ شرارت سٍتـ̡ جواب، تکیازِ حضرت عیسیٰ علیہ السلام اوس سبت دۅہہٕ شفا دِژمُت، تہٕ وونُن لوکن زِ شیہ دۅہ چُھ یِمن منز انسانس کٲم کرٕنۍ، تێمہِ مۅکھہ گژھہِ یِمن منز یِن تہٕ شفا سپدُن، نہ کہ سبت دۅہہٕ۔\n15.\\tخداوند دِیُت أمِس جواب تہٕ وونُن، {ژے} منافق، کیا ژے منزٕ پرٮ۪تھ کانہہ سبت دوہ پنُن بیل یا گٔر دُکانہٕ پیٹھٕ تراوان تہٕ أمِس آب دِنہٕ خٲطرٕ نِوان چھُ؟\n16.\\tتہٕ یێمہِ زنانہِ یێمہِ سٍتـ̡ یێلہِ بێیہِ بێیہِ سٍتـ̡ یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ یێلہٕ بێیہِ دۅہہٕ یێلہ\n17.\\tتہٕ ییلہ تٔمۍ یِم کتھ وننہٕ آو، تٔمۍ سٕندِ سارِنٕے مُخٲلِف گٔیہِ شرمندٕ، تہٕ سارِنٕے لُکھ گٔیہِ تٔمۍ سٕندِ دٔسۍ کرنہٕ آمٕژ سارِنٕے شاندار کامہِ خٲطرٕ خۄش۔\n18.\\tاَمہِ پتہٕ ووٚن تٔمِس خدایہِ سٕنز بادشٲہی کِتھہٕ پٲٹھۍ؟ تہٕ بہٕ کتہِ کٔرٕ اتھ ہِش؟\n19.\\tیہِ چُھ سرسَن ہٕندِس دانہٕ ہٕندۍ پٲٹھۍ، یُس أکِس انسانس نِش تُلِتھ پننِس باغس مَنٛز ترٛاوُن۔ تہٕ یہٕ بڑیو، تہٕ اکھ بٔڑ کُلِس موم۔ تہٕ ہوہٕکۍ جاناوار ٲسۍ اَمہ چہ لنجہِ منز بٔرِتھ۔\n20. تہٕ بییہِ ووٚن میہ خدایہ سٕنزِ بادشٲہی کِس مشابہت سٍتـ̡ ۔\n21.\\tیہ چھہ خمیرکۍ پٲٹھۍ، یُس زنانہِ ترٮن پیمانن منز ژوٗرِ تھوان اوس، یوٚت تام سورے خمیر سپدِ۔\n22.\\tتہٕ سُہ گۆو شہرن تہٕ گامن مٔنزۍ پٲٹھۍ، پرناوُن تہٕ یروشلمس کُن سفر۔\n23.\\tاَمہِ پتہٕ ووٚن أمِس خداوند، کیا یِم نجات دِنہٕ یِنہٕ وٲلۍ؟ تہٕ تٔمۍ ووٚن تِمَن،\n24.\\tآبنائے دروازس پیٹھ اژنچ کوشش کرو بہ، بہٕ چُھس ژیہ ونان زِ واریاہ لوگ گژھن اژنچ کوشش کران، تہٕ تم گژھن نہٕ ہیکن۔\n25. ییلہ اکہ لٹہِ گرُک مٲلک تھوٚد چُھ، تہٕ دروازٕ بند کرُن، تہٕ تُہۍ چُھہ نیبر کھڑا گژھُن، تہٕ دروازٕ دستک دِوان تہٕ وَنُن، خداوند، خدا، اسہِ خٲطرٕ کھولہٕ۔ تہٕ سُہ دِیہِ جواب تہٕ وَنُن، بہٕ چُھس نہٕ ژےٚ پتاہ تہٕ تہٕ کتہِ چھِو:\n26. تیلہٕ کرو تۅہہ یہ ونُن شروع زِ أسۍ چُھہ چانہِ حضوری کھٮ۪وان تہٕ چُھکھ چُھکھ تہٕ ژے چُھکھ سانہِ سڑکن مَنٛز ہیچھناوُن۔\n27. مگر سُہ وَنُن، بہٕ چُھس ژےٚ وَنُن، بہٕ چُھس نہٕ پتاہ تہٕ ژٕ کتہِ چھِو۔ میہ نِش گژھ تمام بدکار کارکن۔\n28.\\tیێلہِ گژھہِ ابراہیم، اسحاق تہٕ یعقوب تہٕ سارِنٕے پیغمبرن خدایہ سٕندِس بادشٲہی مَنٛز وُچھِو، تہٕ تُہۍ کٔرِو کٔڈِتھ کڈنہٕ۔\n29. تہٕ تِم گژھن مشرقس پیٹھ، تہٕ مغرب پیٹھ، تہٕ شمالہٕ پیٹھ، تہٕ {جنوب} پیٹھ، تہٕ خدایہ سٕنزِ بادشٲہی مَنٛز بِہنہٕ۔\n30. تہٕ وُچھِو، تِم چھِ ٲخری یُس گۅڈٕ آسہِ، تہٕ گۅڈنِچ یُس ٲخری آسہِ۔\n31.\\tامی دۅہہ آو فریسیو سٍتـ̡ یقین تہٕ وونُن زِ ژے نیٖرِو تہٕ نیرُن، تکیازِ ہیرودیس کرِ ژے مٲرِتھ۔\n32.\\tتہٕ تٔمۍ ووٚن تِمَن پٲٹھۍ، گژھ تہٕ وَنُن زِ بہٕ کٔرِو شیطان کٔڑِتھ، تہٕ بہٕ چھُس دۅہس تہٕ پگہہ شفا دِوان، تہٕ تریمہِ دۅہہ گژھہِ بہٕ کٲمل۔\n33.\\tبہٕ چُھس دۅہس تام پَکُن، تہٕ پگہہ تہٕ یِنہٕ والہِ دۅہہٕ پَکُن، تکیازِ یِہ ہیکہِ نہٕ یُس کانہہ نبی یروشلمس منزٕ ختم سپدِ۔\n34. اے یروشلم، یروشلم، یُس پیغمبرن ماران چُھ، تہٕ یِم توے نِش سوزنہٕ آمٕتۍ چھِ، تِمن کٔرِتھ کٔرِتھ کٔرِتھ۔ میہ کٲژاہ لٹہِ آسہ ہا چانۍ شُرۍ جمع کٔرتھ، یتھہ پاٹھۍ کۅکُر پنن بچہٕ {پننِس} پکھہ تلہ جمع کٔرتھ، تہٕ ژیہ کرِ نہ!\n35.\\tوُچھِو تُہُند مکانہٕ چُھہ تۅہہِ خٲطرٕ ویران تہٕ بہٕ چُھس ژے وَنُن، توٚت تام یێلہِ نہٕ تُہۍ وُچھِتھ یُس خداوند سٕندِ ناوٕ سٍتـ̡ یِوان چھُ۔","1. تہٕ سپُد سبت دۅہہٕ أکِس اہم فریسی سٕندِس گرس منز روزنہٕ خٲطرٕ، تِمو اوس أمِس وُچھان۔\n2.\\tتہ وچھ تس برونہہ کنہِ اوس اکھ شخص یمۍ سُند قطرہ اوس۔\n3. تہٕ حضرت عیسیٰ علیہ السلامن وکیلن تہٕ فریسیین جواب دِتھ وونُن زِ کیا سبت دۅہہٕ چُھہ شفا دِنہٕ یُن جٲیز؟\n4. تہٕ تِمو روٗد پنُن امن۔ تہٕ تٔمۍ رٔٹِتھ تہٕ دِژُن أمِس شفا تہٕ دِژُن أمِس نیرُن۔\n5.\\tتہٕ دِتُن تِمن جواب دِتھ زِ تۄہہِ منزٕ کُس گَرٕ یا داند پییہِ کھۅڈس مَنٛز، تہٕ سبت دۅہہٕ کٔرِہ نہٕ سُہ سیدُے کُنہِ کُنہِ دۅہہٕ کُنہِ کُنہِ دۅہہٕ کُنہِ کُنہِ دۅہہٕ کُنہِ دۅہہٕ کُنہِ کھورِ\n6. تہٕ تِم ہیوٚک نہٕ أمِس یِمن چیزن ہُند جواب دِتھ۔\n7.\\tتہٕ تٔمۍ کٔر تِمن ہٕندِ خٲطرٕ اکھ تمثیل پیش یِمن ہُند حکم اوس دِنہٕ آمُت، ییٚلہِ تِمو کِتھہٕ کٔنۍ ٲسۍ اہم کمرٕ ژارنہٕ آمٕتۍ۔ تِمن وَنُن چُھ،\n8.\\tییلہ تہِ کٲنسہِ تہِ شخصس کھاندرس منز حکم دِنہٕ ییہِ، بِہتھ نہٕ تھدِس کمرس مَنٛز۔ متانکہٕ ژے کھوتہٕ زیادٕ معزز انسان ییہٕ أمس نِش حکم دنہٕ۔\n9.\\tتہٕ یُس تۅہہِ تہٕ أمِس حُکُم دِیُت تہٕ وَنُن یُس أمِس انسانس دِیُن جاۓ۔ تہٕ ژے چھکھ شرم سان شروع کران ساروے کھوتہ بٔنِم کمرہ رٹان۔\n10.\\tمگر ییلہ ژیہ حکم دِنہٕ ییہ، گژھ تہٕ بِہتھ بٔنِس کمرس مَنٛز۔ یێلہِ یِنُک حُکُم دِیہِ، سُہ وَنُن زِ یار، ہیوٚر تھوٚد گژھُن، تیلہِ کٔرِو تِمن ہٕندِس حضورس منز عبادت یِم ژے سٍتـ̡ مازس پیٹھ بِہِتھ چھِ۔\n11.\\tیُس تہِ پانس تھزرٲوِتھ آسہِ، سُہ گژھہِ ذلیل کرنہٕ۔ تہٕ یُس پانس عاجز کرِ، سُہ گژھہِ بلند۔\n12.\\tاَمہِ پتہٕ ووٚن أمِس تہِ یُس أمِس حُکُم دِیُت، ییٚلہِ تہٕ ژٕ کھٮ۪ن یا شامُک کھٮ۪ن بناوِو، تیٚلہِ کٔرِو نہٕ پَنٕنٮ۪ن یارن تہٕ بٲے تہٕ نہ پنٕنٮ۪ن رشتہٕ دارن تہٕ نہ پَنٕنٮ۪ن امیر ہمساین بُلاونہٕ۔ نتہٕ تِم تہِ دُبارٕ دِنہٕ تہٕ تۅہہِ ہُند بدلہٕ دِنہٕ۔\n13. مگر ییلہ تہۍ دعوت کرِ، غریب، معیوب، لنگڑ، انہِ بلاوُن:\n14. تہٕ ژے گژھہِ برکت حٲصل کرنہٕ۔ تِکیازِ تِم ہیکَن نہٕ تُہُند معاوضہٕ دِتھ: تِکیازِ یِیہِ تُہُند بدلہٕ دِنہٕ یِنہٕ۔\n15.\\tتہٕ یێلہِ أمِس سٍتـ̡ مازس پیٹھ بِہتھ أکِس یِم کتھٕ بوز، تٔمۍ ووٚن أمِس مُبارک، سُہ چُھ خدایہ سٕندِس بادشٲہی مَنٛز روٹی کھٮ۪وان۔\n16.\\tاَمہ پتہٕ ووٚن أمِس زِ أکِس نفرن بنوو اکھ زبردست کھٮ۪ن، تہٕ واریاہن ہُند حکم دِیُت:\n17.\\tتہٕ سوُزُن پنُن نوکر شامُک وِزِ تِمن وَنُن یِمن ہُند حکم دِنہٕ آمُت چھُ، یِمن ہُند حکم دِنہٕ آمُت چھُ۔ تکیازِ سٲری چیز چھہِ وۅنۍ تیار۔\n18.\\tتہٕ یِمو سارِوٕے ہیوٚت اَکہِ {رضامند} سٍتـ̡ بہانہ بناوُن۔ گۅڈنچہ لٹہِ ووٚن أمس زِ میہ چھہ زمینہِ ہند اکھ ٹُکرہ ہیوٚتمُت، تہٕ میہ گژھہِ یہ وُچھُن: بہٕ چھُس ژیہ دُعا کران زِ میہ کرِ معافی۔\n19.\\tتہٕ بییِس ووٚن، مے ہیوٚت پانژھ بیل تہٕ بہٕ چھُس یِم ثٲبت کرنہٕ خٲطرٕ نیران: بہٕ چھُس دُعا کران زِ بہٕ چھُس ژے معافی دِوان۔\n20.\\tتہٕ بییِس ووٚن زِ میہ چھہ زنانہِ سٍتۍ خاندر کورمُت، تہٕ امہ مۅکھہ چھُس نہٕ بہٕ یِتھ۔\n21.\\tیێلہِ آو سُہ خادم تہٕ ہٲوِن پننِس مٲلکَس یِم چیز۔ اَمہ پتہٕ ووٚن گرٕکۍ مٲلکَن شَرارتہٕ گٔژِھتھ پننِس خادمس زِ جلدی نیٚبر شہر کین سڑکن تہٕ سڑکن منٛز، تہٕ أنِن غریب، معذوٗر، تہٕ رُکُن تہٕ انہِ أنِن۔\n22.\\tتہٕ خادمَن ووٚن، خداوند، یہِ چُھ تِتھۍ کرنہٕ آمُت یُس ژے حُکُم چُھ، تہٕ توتہِ چُھ گنجایش۔\n23.\\tتہٕ خداوند ووٚن خادمَس زِ سڑکن تہٕ باڑن منز گژھ تہٕ یِمن اژنہٕ خٲطرٕ کرُن مجبور، یُتھ میون گرٕ گژھہِ بٔرِتھ۔\n24. تکیازِ بہٕ چُھس ژے ونان زِ یِمن نفرن ہُند حکم دِنہٕ آمُت چھُ، تِمن منز گژھِ نہٕ کانٛہہ تہِ میانہِ شامُک مزہ چکھنہٕ۔\n25.\\tتہٕ تٔمِس سٍتـ̡ گٔیہِ بٔڈۍ بٔڈِس سٍتـ̡ تہٕ سُہ پھیُر تہٕ وونُن تِمن سٍتـ̡\n26.\\tاگر کانہہ انسان میانہِ نِش یِیہ، تہٕ پننِس مٲلِس تہٕ ماجہ تہٕ زنانہٕ تہٕ شُرۍ، بٲے تہٕ بینہِ سٍتۍ تہِ نفرت کرِ، آ، تہٕ پننہِ زندگی سٍتـ̡ تہِ ہیکہِ نہٕ سُہ میون شٲگِر بٔنِتھ۔\n27. یُس نہٕ پَنُن صلیب تُلِتھ تہٕ میانہِ پتہٕ یِیہ، سُہ ہیکہِ نہٕ میون شٲگِر بٔنِتھ۔\n28.\\tژیہ منزٕ کُس تہِ چُھہ مینار بناونُک ارادہ تھاوان، گۅڈٕ چُھہ نہٕ بِہتھ تہٕ خرچہٕ گٔنزراوان زِ أمِس چھا {یہ} مکمل کرنہٕ خٲطرٕ {کٲفی}؟\n29.\\tیُس نہٕ تٔمۍ سٕنز بُنیاد تراونہٕ پتہٕ، تہٕ یُس نہٕ پوٗرٕ کٔرِتھ، یُس سارِوٕے وُچھان آسہِ تٔمِس ٹھٹھہٕ کرُن،\n30.\\tیہ ونِتھ زِ أمِس نفرن ہیوٚت تعمیر کرُن، تہٕ ہیوٚک نہٕ مُکمل کٔرِتھ۔\n31.\\tیا کُس بادشاہ یُس بییِس بادشاہس سٍتـ̡ جنگ کرُن، سُہ چُھہ نہٕ گۅڈٕ بِہتھ تہٕ مشورٕ کران زِ سُہ چھا دَہ ساس سٍتـ̡ أمِس سٍتـ̡ مُقابلہٕ کٔرِتھ یُس أمِس خلاف وُہن ساس ہیتھ یِنہٕ وٲلِس سٍتـ̡ یِنہٕ وٲلِس سٍتـ̡ سٍتـ̡ سٍتـ\n32.\\tنتہٕ ییلہ بیاکھ وُنہِ تہِ واریاہ دور آسہِ، سُہ چھُ اکھ سفیر سوزان تہٕ امن ہٕندۍ حالات یژھان۔\n33. یِتھے پٲٹھۍ، یُس تہِ تہِ آسہِ یُس نہٕ تٔمِس سٍتـ̡ سارِوٕے چیٖز تراوِ، سُہ ہیکہِ نہٕ میون شٲگِر بٔنِتھ۔\n34.\\tنوٗن چُھ اصل: مگر اگر نوُن چُھس مَزٕ راوُن، کَمہِ سٍتـ̡ ییہِ مَزٕ دِنہٕ؟\n35.\\tیہ چھہ نہ زمینہِ خاطرہ موزون تہ نہ ونہِ تہِ گُرِ ہندِ خاطرہ موزون۔ {مگر} مردو کٔر یہ کڈان۔ یُس بوزنہٕ خٲطرٕ کَن آسہِ، سُہ بوزُن۔","1.\\tامہ پتہ گٔیہ أمس نِش سارِنٕے پبلکن تہٕ گۅنہگار أمِس بوزنہٕ خٲطرٕ۔\n2. تہٕ فریسیو تہٕ کاتبو کٔر بڑبڑاوان زِ یہِ انسان چُھ گۅنہگار رٔٹِتھ تہٕ تِمن سٍتـ̡ کھیوان۔\n3.\\tتہٕ تٔمۍ ووٚن تِمن سٍتـ̡ یہِ تمثیل دِتھ ونُن،\n4.\\tژے منزٕ کُس انسان یُس ہتھ کۅکرِ آسہِ، اگر سُہ اکھ راوان آسہِ، سُہ چھُنہٕ نَتھ تہٕ نو بیابانن منز تراوُن، تہٕ یُس رٲومُت آسہِ، توٚت تام گژھِ نہٕ سُہ لبنہٕ۔\n5. تہٕ ییلہ أمِس لٔبِتھ چُھ، سُہ چُھ خۅش گٔژھِتھ پننِس پھیکس پیٹھ بٔرِتھ۔\n6. تہٕ ییلہ سُہ گَرٕ یِوان چُھ، سُہ چُھ پننین یارن تہٕ ہمساین یکوٹہٕ بُلاوان تہٕ تِمن ونان زِ میانہِ سٍتـ̡ کرو شاد ۔ تکیازِ میہ لوٚب پنُن دانٛد یُس رٲومُت اوس۔\n7. بہٕ چُھس ژےٚ ونان زِ یِتھے پٲٹھۍ گژھہِ أکِس گۅنہگارس سٍتـ̡ خوشی یُس توبہ کرِ، نَتھ تہٕ نَو کھۄتہٕ زیادٕ عادل شخصن سٍتـ̡ یِمن نہٕ توبہٕ کرنٕچ ضروُرت آسہِ۔\n8.\\tیا کُس زنانہِ آسہِ داہ رۅپہ رۅپہ تہ اگر اکھ ٹُکرہ راوان آسہِ، سہ کرِ نہ شمعدان زالان تہ گرہ صاف کٔرِتھ ژھانڈان یوٚت تام نہ تس لٔبِتھ تہِ۔ {ٹُکرٕ...: ڈراکما، یتہِ چُھ رۄپہٕ ہند اکھ ٹُکرُک ترجمہٕ کورمُت، چُھ اونسُک ٲٹھم حصہٕ، یوس ستھ پینس نصف پونسہٕ یوان چُھ، تہٕ رومن پونسہٕ برابر چُھ}\n9.\\tتہٕ ییلہ أمِس لٔبِتھ چُھ، سُہ چُھ [پننِس} یارن تہٕ ہمساین یکوٹہٕ بلاوان تہٕ ونان زِ میانہِ سٍتـ̡ کرو شاد ۔ تکیازِ میہ چھہ سہ ٹُکرہ لوٚبمت یُس میہ راوان اوس۔\n10. یِتھے پٲٹھـ̡ چُھس بہٕ ژے ونان زِ خدایہ سٕندِس فرشتن ہٕندِس حضورس مَنٛز چُھ خوشی یُس توبہ کٔرِتھ چُھ۔\n11.\\tتہٕ ووٚن أکِس شخصس زٕ نیچوۍ:\n12.\\tتہٕ یِمو منزٕ لۅکٹِس ووٚن مٲلِس مٲلِس ، بابا، مے دِیُن سُہ مال یُس میہ پیوان چھُ۔ تہٕ تٔمۍ کٔر تمن منز پنٕنۍ زندگی تقسیم۔\n13.\\tتہٕ واریاہ دۅہہ پَتہٕ لوٚکُٹ نیچو جمع گٔیہِ، تہٕ أکِس دوٗر مُلکس کُن سفر کٔرِتھ، تہٕ تتہِ کوٚرُن پنُن مال فساد زِندٕ سٍتـ̡ ضایع۔\n14.\\tتہٕ ییلہ تٔمۍ سورُے خرچ کٔر، تَتھ زمینس مَنٛز ووت زبردست قحط۔ تہٕ تس ہیوٚتُن محتاج۔\n15. تہٕ سُہ گوٚو تہٕ پانس سٍتـ̡ تمہِ ملکٕکِس أکِس شہرِس سٍتـ̡ رٔلِتھ ۔ تہٕ تٔمۍ سوٗز سُہ سورن کھیٚنہٕ خٲطرٕ پنٛنیٚن کھاہن منٛز۔\n16.\\tتہٕ سُہ اوس پنُن یٔڈ بٔرِتھ یُس سورن کھٮ۪وان اوس، تہٕ کٲنسہ تہِ دِژ نہٕ أمِس دِنہٕ۔\n17.\\tتہٕ ییلہ سُہ پانس کُن آو، تٔمۍ ووٚن زِ میٲنس مٲلہِ سٕندِس کٲتِس کرایہ دار نوکرس چھِ سٮ۪ٹھاہ روٹی تہٕ بٔرِتھ، تہٕ بہٕ چھُس فاقہٕ کٔرِتھ مران۔\n18.\\tبہٕ وُتھٕ تہٕ پننِس مٲلِس نِش گژھُن، تہٕ وَنُن زِ بابا، بہٕ چُھس آسمانس سٍتـ̡ تہٕ ژے برونہہ کُن گناہ کورمُت،\n19.\\tتہٕ بہٕ چُھس نہٕ پنُن نیچو وننس لایق: مے بناو پنٕنۍ کرایہ دار خادم۔\n20. تہٕ سُہ ووٚتھ، تہٕ آو پننِس مٲلِس نِش۔ مگر ییلہ سُہ وُنہِ تہِ واریاہ دور اوس، تٔمۍ سٕندِس مٲلہِ وُچھ أمِس تہٕ کوٚرُن رحم تہٕ ژوٚلُن تہٕ پیوٚو أمِس گردنہِ پیٹھ تہٕ بوسہ دِتھ۔\n21. تہٕ نیچو ووٚن أمِس باپ، میہ چُھ اسمانس خلاف تہٕ چانہِ نظرِ منز گۅناہ کورمُت، تہٕ بہٕ چُھس نہٕ تُہند نیچو وننس لایق۔\n22.\\tمگر مٲلہِ ووٚن پننین خدمتگارن زِ بہترین پوشاک أنِتھ تہٕ لٲگِن أمِس سٍتـ̡ ۔ تہٕ تٔمۍ سٕندِس اتھس پیٹھ وٲج تہٕ کھورِ کھور:\n23.\\tتہٕ موٚٹۍ بَچھرٕ أنِتھ تہٕ مارُن {یہ}۔ تہٕ أسۍ کھیوٚو تہٕ خۅش روزُن:\n24. امہ مۅکھہ اوس میون نیچو موٗدمُت، تہٕ چُھ دُبارٕ زندٕ۔ سُہ اوس رٲومُت، تہٕ آو لبنہٕ۔ تہٕ تِم ہیوٚتُن خۅش گژھن۔\n25.\\tوۅنۍ اوس تٔمۍ سُند بوٚڈ نیچو کھاہس منز: تہٕ ییلہ سُہ آو تہٕ گرس نزدیک ووت، تس بوز موسیقی تہٕ نژُن۔\n26.\\tتہٕ تٔمۍ بُلوو أکِس نوکرس تہٕ پرژھُن یِمن چیزن ہُند مطلب کیا چھُ۔\n27. تہٕ تٔمۍ ووٚن أمِس زِ تُہند بٲے آو آمُت۔ تہٕ تہندِ مٲلہِ چھُ موٚٹۍ بَچھرٕ مٲرِمُت، تِکیازِ أمِس چُھ سُہ محفوٗظ تہٕ صحت مند روٚٹمُت۔\n28.\\tتہٕ أمِس گوٚو شَرارتہٕ، تہٕ ژاو نہٕ اژُن، تێمہِ کِنۍ آو پنُن مول نٮ۪بر، تہٕ کوٚرُن أمِس گُزٲر۔\n29.\\tتہٕ تٔمۍ ووٚن پننِس مٲلِس جواب دِتھ، یِمن ؤرین چُھس بہٕ تۅہہِ ہٕنز خدمت کران، تہٕ کُنہِ تہِ وِزِ چُھس نہٕ چانہِ حُکمٕچ خلاف ورزی کٔرمٕژ، تہٕ توتہِ دِژ نہٕ میہ زانہہ شُر، یُتھ بہٕ پننین یارن سٍتـ̡ خۅش کٔرِتھ:\n30. مگر یێلہِ یێلہِ تُہُند نیچو آو یُس تۅہہِ ہُند زِندٕ کھٮ۪وان چُھ، ژے کٔر أمِس خٲطرٕ موٚٹۍ بَچھرٕ مٲرِتھ۔\n31.\\tتہٕ تٔمۍ ووٚن أمِس زِ نیچو، ژٕ چُھکھ ہمیشہ میانہِ سٍتـ̡ سٍتـ̡ تہٕ یُس میہ نِش چُھ، سُہ چُھہ تُہُند۔\n32.\\tیہ اوس مُلاقات زِ اسہِ گژھہِ خۅش گژھُن، تہٕ خۅش گژھُن، تکیازِ تُہند بوے اوس موٗدمُت، تہٕ چُھہ دُبارٕ زندٕ۔ تہٕ آو رٲومُت، تہٕ لبنہٕ آمُت۔","1. تہٕ تٔمۍ ووٚن پننین شاگردن تہِ زِ اَکھ امیر شخص اوس، یٔمِس سٍتـ̡ اوس۔ تہٕ أمِس اوس یۅہے الزام لگاونہٕ آمُت زِ تٔمۍ اوس پنُن مال ضایع کوٚرمُت۔\n2.\\tتہٕ تٔمۍ بُلوو تہٕ ووٚننس زِ بہٕ کِتھہ کٔنۍ چُھس ژےٚ یہِ بوزان۔ پننہِ سرپرستی ہُند حساب دِیُن؛ تکیازِ ژیہ آسہِ نہ وۅنۍ نگراں روزان۔\n3.\\tاَمہ پتہٕ ووٚن سِٹیورڈس پانس اندر، بہٕ کیا کرٕ بہٕ؟ تکیازِ میون رب چُھ میہ نِش نِوان: بہٕ ہیٛکہٕ نہٕ کھٔنِتھ کٔرِتھ۔ منگنہٕ خٲطرٕ چُھس بہٕ شرمندٕ۔\n4. بہٕ چُھس طے کورمُت زِ کیا کرُن، یێلہِ بہٕ یێلہِ بہٕ نگرٲنی نِش نیرنہٕ یِیہ، تِم گژھن میہ پنہٕ نِس گرس مَنٛز رٔٹِتھ۔\n5.\\tتێلہِ بُلوو تٔمۍ پننِس آقا سٕندِس پرٮ۪تھ أکِس مقروض سٍتـ̡ تہٕ وونُن گۅڈنِکِس سٍتـ̡ کوتاہ چُھکھ میٲنِس آقا سُند مقروض۔\n6.\\tتہِ ووٚن ہتھ پیمانہ تیل۔ تہٕ تٔمۍ ووٚن أمِس پنُن بل رٔٹِتھ تہٕ بِہتھ جلدی تہٕ لیکھِو پنژاہ۔ {پیمائش: اصلس منز چُھ لفظ Batus منز نو گیلن تریہ کوارٹ}\n7.\\tتَمہِ وۆنُن بییِس سٍتـ̡ تہٕ کوتاہ چُھہ تۅہہِ دِژمُت؟ تہٕ أمۍ ووٚن، ہتھ پیمانہٕ کٕنُک۔ تہٕ تٔمۍ ووٚن أمِس پنُن بل رٔٹِتھ تہٕ لیکھِو ژور سکور۔ {پیمائش: یتہِ لفظچ ترجمانی چھیہ اصلس منز اکس پیمانس پیٹھ تقریباً ژۅداہ بشل تہ زہ کوارٹ}\n8.\\tتہٕ خداوند کٔر ناانصافی سٕندِس تعریف، تکیازِ تٔمۍ اوس دانشمندی سان کٲم کٔرمٕژ: تکیازِ دنیاہٕکۍ شُرۍ چھِ پننہِ نسلہِ منز گاشہٕ کین بچن کھوتہٕ زیادٕ عقلمند آسان۔\n9. تہٕ بہٕ چُھس ژے ونان زِ پانَس سٍتـ̡ بنٲیِو ناپاکیزگی ہٕندِس مَمنَس سٍتـ̡ یار۔ یُتھ زن تُہۍ ناکام گٔژھِو، تِم ہیکن تۅہہِ ابدی بستن منز حٲصِل کٔرِتھ۔ {میمون: یا، دولت}\n10. یُس کم از کم چیزس مَنٛز وفادار آسہِ، سُہ چُھ واریاہ زیادٕ وفادار تہٕ یُس کم از کم ناانصافی کران چُھ، سُہ چُھ واریاہ زیادٕ ناانصافی تہِ۔\n11.\\tتێلہِ یێلہِ نہٕ تۅہہِ ناپاکیزہ میمونس سٍتـ̡ وفادار رودمُت، کُس کرِ تُہٕندِس بھروسس سٍتـ̡ پٔزۍ {دولت} سٍتـ̡ دِنہٕ؟ {میمون: یا، دولت}\n12. تہٕ یێلہِ نہٕ تۅہہ بییِس انسانس سٍتـ̡ وفادار آسہِ، تێلہِ کُس دِیہِ تۅہہِ سُہ یُس تُہند پنُن چُھ؟\n13.\\tکانہہ تہِ خادم ہیکہِ نہ دۅن مالکن ہنز خدمت کٔرِتھ، تکیازِ یا تہِ کرِ سُہ أکِس سٍتـ̡ نفرت، تہٕ بییِس سٍتـ̡ محبت کرِ۔ نتہٕ کرِ سُہ أکِس تھپھ کٔرِتھ، تہٕ بییِس حقارت کرِ۔ تُہۍ ہیکِو نہٕ خدایہ تہٕ میمونٕچ خدمت کٔرِتھ۔\n14. تہٕ فریسیو تہِ یِم لالچ ٲس، بوز یِم سٲری کتھ: تہٕ تِمو کٔر أمِس طنز کرنہٕ۔\n15.\\tتہٕ تٔمۍ ووٚن تِمن سٍتـ̡ یُس انسانس برونہہ کنہِ پنُن پان انصاف کران چھِ۔ مگر خدا چُھ تُہند دِل زانان: یُس چیز انسانن مَنٛز واریاہ زیادٕ ماننہٕ یوان چُھ، سُہ چُھ خدایہِ سٕندِ نظرِ منز مُنفرت۔\n16.\\tشریعت تہٕ پیغمبرن {ٲس} یوحنا ہس تام: تَمہِ وقتہٕ پیٹھٕ چُھ خدایہِ سٕنزِ بادشٲہی ہٕنز تبلیغ کرنہٕ آمٕژ، تہٕ پرٮ۪تھ کانہہ انسان چُھ اتھ مَنٛز زور دِوان۔\n17. تہٕ شریعت کہِ اکہِ لٹہِ ناکام گژھنہٕ کھۅتہٕ چُھ آسمانس تہٕ زمینہِ خٲطرٕ گزرُن سہل۔\n18.\\tیُس پننہِ زنانہِ سٍتـ̡ خاندر کٔرِتھ بییِس سٍتـ̡ خاندر کرِ، سُہ چُھ زنا کٔرِتھ۔\n19.\\tاَتھ اوس اَکھ امیر شخص، یُس واگن رنٛگہٕ تہٕ عمدہ کُن لٲگِتھ اوس، تہٕ اوس پرٮ۪تھ دۅہہٕ شاہانہٕ پٲٹھۍ کٲم کران۔\n20.\\tتہٕ اوس اَکھ گدٲر یُس لزارس ناوُک اوس، یُس أمۍ سٕندِس دروازس پیٹھ لٔگِتھ اوس، یُس زخم سٍتـ̡ بٔرِتھ اوس،\n21.\\tتہٕ یِم امیر سٕندِس میزس پیٹھٕ پییہِ تِمن ٹُکرٕ کھٮ۪نہٕ خٲطرٕ یِم کھٮ۪نہٕ یِنہٕ خٲطرٕ: امہِ علاوٕ آو ہونۍ تہٕ لوٚگ تٔمۍ سٕندِس زخمس لٔٹِتھ۔\n22.\\tتہٕ سپُد یہِ زِ گدٲر مٔرِتھ تہٕ فرشتہٕ نِش نِنہٕ آمُت ابراہیم سٕندِس چھۅکہٕ سٍتـ̡ ۔\n23.\\tتہٕ جہنمس مَنٛز چُھ سُہ عذابس مَنٛز پنٕنۍ أچھ تُلِتھ تہٕ ابراہیم دوٗر تہٕ لزارس پننِس سینس مَنٛز وُچھان۔\n24.\\tتہٕ تٔمۍ ووٚن وۆنُن، فادر ابراہیم، میانہِ پیٹھ رحم کرُن، تہٕ سوز لازارس، یُتھ سُہ کرِ پننہِ اونگجہِ ہُند نوک آبس مَنٛز ڈباونہٕ تہٕ میانہِ زبان ٹھنڈٕ کرٕنۍ۔ تکیازِ میہ چھہ اتھ نارس منز عذاب۔\n25.\\tمگر ابراہیم ووٚن، نیچو، یاد تھاوُن زِ ژے چُھہ پننہِ زندگی مَنٛز پنٕنۍ اصل چیز حٲصل کٔرمٕژ، تہٕ یِتھے پٲٹھۍ چُھہ لزارس بد چیز، مگر وۅنۍ چُھہ تس تسلی دِنہٕ آمُت، تہٕ تۅہہِ چُھہ عذاب۔\n26. تہٕ اتھ سارِنٕے سٍتـ̡ چُھہ اسہِ تہٕ تۅہہِ درمِیان اکھ بۆڈ خلیج طے کرنہٕ آمُت: یُس تُہٕندِس نِش یِنہٕ وٲلِس نِش یِنہٕ وٲلِس سٍتـ̡ ہێکہٕ نہٕ یِتھ۔ نہ ہیکن تِم اسہِ نِش وٲتِتھ، یُس {یِیہ} تتہِ پیٹھ۔\n27. اَمہِ پتہٕ ووٚن تٔمۍ سُہ دُعا کَرُن، اَمہِ مۄکھٕ چُھس ژٕ سُہ میٲنِس مٲلہِ سٕندِس گَرٕ سٍتـ̡ سوزُن:\n28.\\tکیازِ میہ چھہِ پانژھ بٲے۔ تاکہ سُہ کرِ تِمن گوٲہی دِنہٕ، نتہٕ یِم تہِ یِن اتھ عذابٕچ جایہِ منٛز۔\n29. ابراہیم چُھ أمِس ونان زِ تِمن نِش چھِ موسیٰ تہٕ پیغمبر۔ تِم بوزٕنۍ۔\n30.\\tتہٕ ووٚن نہ، باپ، ابراہیم، مگر اگر کانہہ تِمن نِش مرنہٕ پتہٕ گژھہِ، تِم گژھن توبہٕ۔\n31. تہٕ تٔمۍ ووٚن أمِس زِ اگر تِم موسیٰ تہٕ پیغمبرن ہٕنز بوزان آسہِ، تہٕ یێلہِ یێلہِ یِم مُردٕ منزٕ زندٕ سپدِ۔","1.\\tاَمہِ پتہٕ ووٚن تٔمۍ شاگردن زِ یہِ چُھ ناممکن مگر یِمن ہٕندِ ذٔریعہ یِم یِنہٕ وٲلِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ دِنہٕ آمٕتۍ۔\n2.\\tیہ اوس تٔمِس خٲطرٕ بہتر زِ أمۍ سٕندِس گردنہِ منز ییہ اکھ مِلہٕ کٔنہِ لٹاونہٕ، تہٕ سُہ تراوُن سمندرس منز، امہِ کھوتہٕ زِ سُہ کرِ یِمو منزٕ أکِس لۄکٹِس شُرِس ناراض۔\n3.\\tپان ہوشیار کرُن: اگر تُہند بٲے تۅہہِ خلاف زیادتی کرِ، تمِس کٔرِو ملامت ۔ تہٕ اگر سُہ توبہ کرِ، تمِس کرِ معاف۔\n4. تہٕ اگر سُہ أکِس دۅہس منز ستھ لٹہِ تہٕ أکِس دۅہس منز ستھ لٹہِ تہٕ دۅہس منز ستھ لٹہِ تہِ دُبارٕ توبہ کرِ، بہٕ چُھس توبہ کران۔ ژے کٔرِو أمِس معاف۔\n5. تہٕ رسولو ووٚن خداوند سٕندِس عقیدس سٍتـ̡ ہُریر۔\n6. تہٕ خداوند ووٚن زِ اگر ژے سرسٕہ کُلِس پٲٹھـ̡ پى۪ٹھـ� تہٕ یہ گژھہِ تۅہہِ اطاعت کرُن۔\n7.\\tمگر ژیہ منزٕ کُس نوکر یُس چارہ چُھہ دِوان تہٕ چارہ دِوان آسہِ، ییلہ سُہ کھہٕ پیٹھٕ یِنہٕ وِزِ گژھ تہٕ بِہتھ ماز کھٮ۪نہٕ؟\n8.\\tتہٕ یێلہِ نہٕ أمِس وَنُن، یێمہِ سٍتـ̡ بہٕ کھٮ۪نہٕ تہٕ پَنُن تیار کٔرِتھ، تہٕ یێلہِ بہٕ کھٮ۪نہٕ تہٕ شراب۔ تہٕ پتہٕ کٔرِو کھٮ۪وان چیٚنہٕ؟\n9. کیا سُہ چُھ أمِس خادمُک شُکر ادا کران تکیازِ تِم کٔرِتھ یِم أمِس حکم دِنہٕ آمٕتۍ ٲسۍ۔ بہٕ چُھس نہٕ ترومُت۔\n10.\\tیِتھے پٲٹھـ̡ ییلہ تۅہہ تِم سٲری کٲم کٔرِتھ یِم تۅہہِ حکم دِنہٕ آمٕتۍ چھِ، ونِو زِ أسۍ چھِ ناکارہ خادم: أسۍ چھِ سُہ کٲم کٔرمٕژ یُس سانہِ فرض اوس۔\n11.\\tتہٕ ییلہ سُہ یروشلم گۆو، سُہ گۆو سامریہ تہٕ گلیل کِس وسطس منز۔\n12.\\tتہٕ ییلہ سُہ أکِس أکِس گامس مَنٛز ژایہِ، تتہِ سمکھیوو أمِس دَہ نفر یِم کوڑھ ٲسۍ، یِم دوٗر کھڑا ٲسۍ۔\n13. تہٕ تِمو تُل تُلِتھ تہٕ وونُن، عیسیٰ مسیح، آقا، اسہِ پیٹھ رحم کر۔\n14.\\tتہٕ ییلہ تٔمۍ تِمن وُچھ، تٔمۍ ووٚن تِمن وُچھِو، گٔژھِو پادٕرین نِش ہٲوِو۔ تہٕ یہ سپد یہ زِ ییلہ تم گٔیہ، تم گٔیہ پاک۔\n15. تہٕ یِمو منزٕ اَکھ ییلہ أمِس وُچھ زِ سُہ چُھ ٹھیٖک گومُت، پٔرِتھ دِژ خدایہ سُند حمد تہٕ بَڑِ آوازٕ سٍتـ̡ کٔرٕن خدایہِ سُند حمد کرنہٕ،\n16.\\tتہٕ پیوٚو تٔمِس بُتھِس پٲٹھۍ، شُکریہ ادا کٔرِتھ تہٕ سُہ اوس سامری۔\n17. تہٕ حضرت عیسیٰ علیہ السلام ووٚن جواب دِتھ زِ کیا دَہ ٲسِکھ نہٕ پاک گٔمٕتۍ؟ مَگَر نَوَن کَتہِ چھِ؟\n18.\\tتِم چُھہ نہٕ لبنہٕ آمُت یُس خدایہ سُند جلال دِنہٕ خٲطرٕ واپس آو، أمِس اجنبی سٕندِس سٍتـ̡ بچاو۔\n19.\\tتہٕ تٔمۍ ووٚن أمِس وَتھ، وَتھ پٔکِو، پَنٕنـ̡ وَتہٕ پۯاوٕنـ̡ چُھہ تُہٕندِس ایمانس سٍتـ̡ ژے پوٗرٕ پٲٹھـ̡ بنوومُت۔\n20. تہٕ ییلہ أمِس فریسیَن ہُند منگ آو کرنہٕ، یێلہِ خدایہِ سٕنز بادشٲہی ییہِ یِنہٕ، تٔمۍ دِژ تِمن جواب تہٕ وونُن، خدایہِ سٕنز بادشٲہی چھے نہٕ مشاہدس سٍتـ̡ یِوان: {سٍت...: یا ظاہری ظٲہر سٍتـ̡\n21.\\tنہ چھہ تم ونن، لو! یا، لو تتہِ! کیازِ، وُچھو، خدایہِ سٕنز بادشٲہی چِھ توے اندر۔ {توے اندر: یا، توے منز}\n22.\\tتہٕ تٔمۍ ووٚن شاگردن زِ سُہ دۅہ یِنہٕ یِنہٕ، یێلہِ تُہۍ یێلہِ تُہۍ اِنسان سٕندِس نیٚچوِس سُند اکھ دۅہ وُچھنُک خواہش، تہٕ تُہۍ ہێکہِ نہٕ یہِ وُچھِو۔\n23.\\tتہٕ تِم وَنَن تۅہہِ وُچھِو، یێلہِ وُچھِو۔ یا وُچھِو: {تِم} پَتہٕ گژھِو نہٕ {تِم} پَتہٕ۔\n24.\\tیِتھٕ پٲٹھـ̡ بجلی یُس آسمانس تَل أکِس حصس سٍتـ̡ گاش نیران چُھ، بێیِس حصس سٍتـ̡ چُھہ آسمانس تَل چمکان۔ یتھے پاٹھۍ گژھہِ انسان سُند فرزند تہِ پننِس زمانس منز آسُن۔\n25.\\tمگر گۅڈہ گژھہِ تس واریاہ چیز برداشت کرُن، تہٕ یێمہِ نسلہٕ سٍتـ̡ گژھہِ رد کرنہٕ یُن۔\n26.\\tیِتھے پٲٹھـ̡ نوے سٕندِس دۅہس مَنٛز تہِ آسہِ، تِتھے پٲٹھـ̡ آسہِ یہِ انسان سٕندِس فرزندس سٕندِس دۅہس مَنٛز تہِ۔\n27.\\tتِمو کھیوٚو کھٮ۪وان، تِمو کٔر خانٛدر، تِمو کٔر خانٛدر، تِمو دِژ تِم دِنہٕ آمٕتۍ، یوتام نوے صندوقس منز اژِتھ تہٕ سٔہلاب آو تہٕ تِم سارِنٕے تباہ کٔرِتھ۔\n28.\\tیتھے پاٹھۍ لوط سٕندِس زمانس منز تہِ اوس۔ تِمو ٲسۍ کھٮ۪وان، تِمو چیٚن، تِمو ہیوٚت، تِمو کٕنُن، تِمو کٔرِکھ پودٕ، تِمو بنٲو۔\n29.\\tمگر ییمہ دۅہہ لوط سدوم منزہ نیبر نیرِ، اسمانس منز ووت نار تہٕ گندھم تہٕ تِم سارِنٕے تباہ کٔرِتھ۔\n30. یێلہِ تہِ گژھہِ تمہِ دۅہہ یێلہِ انسان سُند فرزند ظٲہر سپدِ۔\n31.\\tتمہِ دۅہہ یُس گرس پیٹھ آسہِ، تہٕ گرس منز آسہِ تٔمۍ سُند سامان نِنہٕ خٲطرٕ گژھہِ نہٕ بۄن یُن، تہٕ یُس کھاہس منز آسہِ، سُہ گژھہِ نہٕ واپس یُن۔\n32. لوط سٕنز زنانہٕ یاد تھاوٕنۍ۔\n33. یُس تہِ پنُن زُو بچاونٕچ کوشش کرِ، سُہ گژھہِ ضایع۔ تہٕ یُس پَنُن جان ضایع کرِ، سُہ کرِ سُہ رژھراوُن۔\n34. بہٕ چُھس ژےٚ وَنُن زِ اَتھ رٲژ آسہِ أکِس بسترس منز زٕ {نفر}۔ اکھ یِن نِنہٕ، تہٕ بیٛاکھ یِن تراونہٕ۔\n35.\\tزٕ زنانہٕ گژھن اکوٹہٕ رٔٹِتھ رٔٹِتھ۔ اکھ یِن نِنہٕ تہٕ بیٛاکھ تراوُن۔\n36.\\tزٕ {نفر} آسن میدانس منز۔ اکھ یِن نِنہٕ تہٕ بیٛاکھ تراوُن۔ {یہٕ آیت چُھ نہٕ زیادٕ تر یونٲنی نسخن منٛز لبنہٕ یوان}\n37.\\tتہٕ تِمو دِژ جواب تہٕ وونُن أمِس کتہِ، خداوند؟ تہٕ تٔمۍ ووٚن تِمَن زِ یَتھ تہِ لاش آسہِ، تتہِ یِن عقاب جمع کرنہٕ۔","1. تہٕ تٔمۍ کٔر تِمن خٲطرٕ اکھ تمثیل زِ انسانس پزِ ہمیشہٕ دُعا کرُن، تہٕ گژھِ نہٕ بے ہوش گژھُن۔\n2.\\tیہ ونِتھ زِ أکِس شہرس مَنٛز اوس اکھ قاضی یُس نہٕ خدایس کھوژان اوس، تہٕ نہ اوس انسانس سٍتـ̡\n3. تہٕ اَتھ شہرس منز ٲس اکھ بیواہ۔ تہٕ سۄ آیہِ أمِس نِش، وَنُن زِ میانہِ دُشمن ہُند بدلہٕ کٔرِ۔\n4.\\tتہٕ سُہ اوس نہٕ کینژس کالس تام مگر امہ پتہ ووٚن تٔمۍ پانس اندر، حالانکہ بہٕ چُھس نہٕ خدایس کھوژان، تہٕ نہ چُھس انسانس سٍتـ̡ خیال تھاوان۔\n5.\\tتوتہِ کیازِ یہِ بیواہ چھے میہ پریشان کران، بہٕ کرٕ أمس انتقام، متانکہٕ تٔمۍ سٕندِ مسلسل یِنہٕ سٍتۍ گژھہِ سُہ میہ تھکان ۔\n6.\\tتہٕ خداوند ووٚن زِ بُزٲرِس مُنصِف سُند کیا چُھ وَنان۔\n7.\\tتہٕ کیا خدایہ کرِ نہ پننین ژٲرن ہُند انتقام، یُس أمس دۅہ راتس فریاد کران چُھ، یُس سُہ تِمن سٍتـ̡ واریاہس کالس برداشت کران چُھہ؟\n8. بہٕ چُھس ژےٚ ونان زِ سُہ کرِ جلدٕے تِمن ہُند انتقام۔ بہر حال ییلہ انسان سُند فرزند یِیہ، کیا سُہ میلہِ زمینس پیٹھ ایمان؟\n9.\\tتہٕ تٔمۍ کٔر یہ تمثیل یُس پانس پیٹھ پژھ کران اوس زِ تم چھہِ نیک تہ باقین حقارت کران ٲسۍ: {یہ...: یا، نیک آسنک پٲٹھۍ}\n10.\\tزٕ نَفر گٔیہِ عبادت کرنہٕ خٲطرٕ مندرس مَنٛز۔ اکھ فریسی، تہٕ بیاکھ پبلکن۔\n11. فریسی اوس کھڑا تہٕ پانس سٍتـ̡ دُعا کٔرِتھ، خدایہ، بہٕ چُھس تُہند شُکر ادا کران زِ بہٕ چُھس نہٕ باقٕے نفرن ہٕندۍ پٲٹھۍ، زٲژ خور، ناانصاف، زناکار، یا یِہ پبلکن ہٕندۍ پٲٹھۍ۔\n12.\\tبہٕ چھُس ہفتس منز دۅیہ لٹہِ روزٕ تھاوان، بہٕ چُھس سارِنٕے چیزن ہُند دٔسہٕ دِوان۔\n13.\\tتہٕ دوٗر کھڑا اوسُس نہٕ تُلِتھ آسمانس کُن أچھ تُلِتھ بلکہ دِژُن پننِس سینس پیٹھ تھپھ دِتھ ونان زِ خدایہ کرِ میانہِ خٲطرٕ رحم کرُن، أکِس گۅنہگار۔\n14.\\tبہٕ چُھس وَنُن زِ یہِ شخٕص گۆو پننِس گَرَس مَنٛز بٔنِتھ یُس پانس تٔرِتھ دِوان چُھ، یێلہِ سُہ گژھِ بێعزتی کرنہٕ یُن۔ تہٕ یُس پانس عاجز کرِ، سُہ گژھہِ بلند۔\n15.\\tتہٕ تِمو أنۍ أمِس نِش شُرۍ تہِ زِ سُہ کرِ تِمن اَتھٕ لاگُن، مگر ییلہ تٔمۍ سٕندٮ۪و شٲگِرِیو وُچھ، تِمو کٔر تِمن ملامت ۔\n16. مگر حضرت عیسیٰ علیہ السلام بُلوو تِم تہٕ وونُن، لۄکٹٮ۪ن شُرین دِیُن میانہِ نِش یِن، تہٕ تِمن کٔرِن نہٕ منع کرنہٕ، کیازِ یِمن ہٕنز بادشاہی چھے خدایہِ سٕنز بادشاہی۔\n17. بہٕ چُھس ژےٚ ونان زِ یُس نہٕ لۄکٹِس شُرۍ سٕندِ پٲٹھی خدایہِ سٕنز بادشٲہی حٲصل کرِ، سُہ گژھِ نہٕ اَتھ مَنٛز دٲخل گژھُن۔\n18.\\tتہٕ أکۍ حُکُمران ووٚن أمِس زِ اَکھ حُکُمران ووٚن زِ بہٕ کیا کرٕ ابدی زندگی ہُند وٲرث۔\n19. تہٕ حضرت عیسیٰ علیہ السلام ووٚن أمِس زِ ژٕ کیازِ چُھکھ مےٚ نیک وَنان۔ کانہہ تہِ {چُھ} اصل، بغٲر اکھ {یعنی}، خدایہ۔\n20. توے چھکھ حُکمن ہُند علم زِ زنا کرُن نہٕ، قتل مہٕ کرُن، ژوٗرِ نہٕ کرُن، اپُز گوٲہی مہٕ دِیُن، پننِس مٲلِس تہٕ ماجہِ ہٕنز عزت۔\n21.\\tتہٕ تٔمۍ ووٚن، یِم سٲری چھِ میہ پننہِ جوانی پیٹھٕ تھٲومٕتۍ۔\n22. یێلہِ یێلہِ عیسیٰ علیہ السلام یِم کتھ بوٗزِ، تٔمِس وۆنُن، توتہِ چُھہ ژے اَکھ کتھ کٔرِتھ: یُس تہٕ یێلہِ تہٕ بێیہِ غریبن مَنٛز بٲگراونہٕ، تہٕ یێلہِ میلہِ اسمانس مَنٛز خزانہٕ۔\n23.\\tتہٕ ییلہ أمِس یہِ بوٗزِ، سُہ گوٚو سٮ۪ٹھاہ غم، تکیازِ سُہ اوس سٮ۪ٹھاہ امیر ۔\n24. تہٕ یێلہِ عیسیٰ علیہ السلام وُچھ زِ سُہ چُھ سٮ۪ٹھاہ غمگسار گومُت، تٔمۍ ووٚن زِ یِم کٲژاہ مشکل چُھہ خدایہ سٕندِس بادشاہتس مَنٛز دٲخل گٔژھِتھ!\n25.\\tتکیازِ اونٹِس خٲطرٕ چُھ سٕژنہِ ہٕنزِ أچھ منزٕ نیرُن آسان یُس أکِس امیر شخصہٕ سٕندِ خٲطرٕ خدایہ سٕندِس بادشٲہی مَنٛز اژُن چُھ۔\n26.\\tتہٕ یِمو بوزِو تِمو ووٚن، تیلہِ کُس ہیکہِ نجات دِتھ؟\n27.\\tتہٕ ووٚن تِم چیز یُس انسانس سٍتـ̡ ناممکن چُھ، تم چِھ خدایہ سٍتـ̡ ممکن۔\n28. پطرس ووٚن زِ أسۍ چھِ سارِوٕے ترٲوِتھ تہٕ ژےٚ پٲٹھۍ۔\n29. تہٕ تٔمۍ ووٚن تِمَن زِ بہٕ چُھس تہٕ یێلہِ تہِ چُھہ نہٕ کانہہ تہِ مرد یُس خدایہِ سٕندِ خٲطرٕ گَر، مٲلِس ماجہ، یا بٲے یا خانٛدارِن، یا بچہٕ ترٲومُت چُھ،\n30.\\tیُس نہٕ اتھ موجودٕ وقتس مَنٛز تہٕ آخرت چہ زندگی مَنٛز واریاہ زیادٕ میلہِ نہٕ۔\n31.\\tتێلہِ نِش نِش بہہ تہٕ وونُن تِمن وۆنُن، وُچھو أسۍ یروشلمس کُن نیران، تہٕ یُس سُہ چیز پیغمبرن ہٕندِ دٔسۍ انسان سٕندِس فرزندس مُتلق لیکھنہٕ آمُت چھُ، تِم گژھن پورٕ سپدٕنۍ۔\n32. تکیازِ سُہ یِیہِ غیر قومن نِش حوالہٕ کرنہٕ، تہٕ یِیہِ طنز کرنہٕ، تہٕ بد نیتی سٍتـ̡ التجا کرنہٕ یِن، تہٕ تھوکاونہٕ یِن:\n33. تہٕ تِم کرِ أمِس کوٹھہٕ تہٕ مارُن، تہٕ تریمہِ دۅہہ گژھہِ سُہ دُبارٕ زندٕ۔\n34.\\tتہٕ تِمو ٲس نہٕ یِمو منزٕ کانہہ تہِ کتھ سمجِتھ، تہٕ یہ کتھ ٲس تِمن نِش پوشیدٕ، تہٕ تِمن ٲس نہ خبرے زِ یِم کتھ ٲس وننہٕ آمٕژ۔\n35.\\tتہٕ سپُد یہِ زِ یێرِیکوَس نِش ووت اَکھ اَنِہ شخٕص وتہِ نِش بِہتھ منگان۔\n36.\\tتہٕ ہجوم بوزِتھ پرژھ اَمیُک مطلب کیا چھُ۔\n37.\\tتہٕ تِمو ووٚن أمِس زِ عیسیٰ مسیح چُھ نیران ۔\n38.\\tتہٕ وۆنُن عیسیٰ مسیح، {تو} داؤد سُند نیچو، میانہِ پیٹھ رحم کر۔\n39. تہٕ یِمو یِمو برونہہ کُن گٔیہِ، تٔمِس کٔر أمِس ملامت زِ سُہ گژھہِ خاموش روزُن، مگر سُہ روُن تیوٗت زیادٕ، اے داؤد سُند نیچو، میانہِ سٍتـ̡ رحم کرُن۔\n40. تہٕ عیسیٰ علیہ السلام ووٚتھ تہٕ دِتُن أمِس نِش اننُک حُکُم، تہٕ ییلہ سُہ نزدیک آو تٔمِس پرژھن،\n41.\\tیہ ونِتھ، ژے کیا کرٕ بہٕ ژے سٍتـ̡ کٔرِتھ؟ تہٕ تٔمۍ ووٚن، خداوند، یُتھ بہٕ ہیٛکہٕ پنُن گاش حٲصل کٔرِتھ۔\n42. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تٔمِس زِ پَنُن گاش رٔٹِو، تُہُند ایمانن چُھ ژے بچاومُت۔\n43.\\tتہٕ یێلہِ أمِس گاش رٔٹِتھ تہٕ لوٚگ خدایہِ سٕنز حمد کٔرِتھ أمِس پٲٹھۍ۔","1. تہٕ {عیسیٰ مسیح} ژاو تہٕ یریحہ کِنۍ گٔیہِ۔\n2. تہٕ وُچھِو زکییس ناوُک اَکھ شخٕص، یُس پبلِکنن مَنٛز سارِوٕے کھۄتہٕ بٔڈ اوس، تہٕ سُہ اوس امیر۔\n3. تہٕ سُہ اوس عیسیٰ مسیح وُچھنٕچ کوشش کٔرِتھ زِ سُہ کُس اوس۔ تہٕ ہیوٚک نہٕ پریس خٲطرٕ ہیوٚک نہٕ، تکیازِ سُہ اوس کم قد ۔\n4.\\tتہٕ سُہ ژوٚل برونہہ کُن، تہٕ ووت أمِس وچھنہٕ خٲطرٕ أکِس کُلِس پیٹھ، تکیازِ أمِس اوس اَتھ وتہِ نیرُن۔\n5. تہٕ ییلہ عیسیٰ مسیح اتھ جایہ ووت، تٔمۍ وُچھ تھوٚد تہٕ وُچھُن تہٕ وونُن زکیوس، جلدی کرو تہٕ بۄن بۄن۔ تکیازِ از کل پزِ میہ چانہِ گرس منز روزُن۔\n6. تہٕ تٔمۍ کٔر جلدی تہٕ ووت بۄن تہٕ خوشی سان استقبال کٔرِتھ۔\n7.\\tتہٕ ییلہ تِمو وُچھ، تِمو سارِوٕے وُچھِتھ وَنُن زِ سُہ چُھ أکِس گۅنہگارس سٍتـ̡ مہمان کرنہٕ آمُت۔\n8. تہٕ زکیئس ووٚتھ تہٕ ووٚنُن خداوند؛ وُچھو، خداوند، میون نصف مال چھُس بہٕ غریبن دِوان۔ تہٕ اگر میہ کٲنٛسہِ شخصس نِش اپُز الزام لگٲوِتھ کانہہ چیز نِیومُت چھُ، بہٕ چھُس ژۅن گنہٕ دِوان۔\n9. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تٔمِس زِ یێمہِ دۅہہٕ چُھ نجات یێتھ گرس مَنٛز، تکیازِ سُہ تہِ چُھ ابراہیم سُند نیٚچُو۔\n10.\\tیُس انسان سُند فرزند چُھ یُس رٲومُت اوسُس ژھانڈنہٕ تہٕ بچاونہٕ خٲطرٕ آمُت چھُ۔\n11.\\tیێلہِ یێلہِ تِمو یِم کتھٕ بوٗزِ، تِمو کٔر اکھ تمثیل تہٕ تِکیازِ سُہ اوس یروشلمس نزدیک، تہٕ تِمن ہُند خیال اوس زِ خدایہِ سٕنز بادشٲہی گژھہِ فوراً ظٲہر سپدٕنـ̡ ۔\n12.\\tتٔمۍ ووٚن اَمہِ مۄکھٕ زِ اَکھ رٔعیٖس گۆو أکِس دورِ مُلکس مَنٛز پانس خٲطرٕ اکھ بادشاہت حٲصل کرنہٕ خٲطرٕ، تہٕ واپس یِنہٕ خٲطرٕ۔\n13.\\tتہٕ تٔمۍ بُلوو پننین دہن نوکروں تہٕ دِتُن تِمن داہ پاؤنڈ، تہٕ وونُن توٚت تام رٔٹِتھ روزُن یوٚت تام بہٕ یِنہٕ۔ {پاؤنڈ: مینا، ییتہِ ترجمہٕ کٔرِتھ اکھ پاؤنڈ، چُھ باہ اونس ساڑ: یُس پانژھ شلنگ مطٲبق چُھ اونس تریہ پاؤنڈ زٕ شلنگ تہٕ شیہ پینس}\n14.\\tمگر تٔمۍ سٕندِس شہریو کٔر أمِس نفرت، تہٕ سوُزُن أمِس پَتہٕ اکھ پٲغام، زِ اسہِ آسہٕ نہٕ یہِ {انسان} پانس پیٹھ راج کرنہٕ خٲطرٕ۔\n15.\\tتہٕ سپُد یہِ زِ ییلہ أمِس واپس آو تہٕ بادشاہت حٲصل کٔرِتھ دِیُت تٔمۍ یِمن نوکرَن أمِس نِش بُلاونُک حُکُم، یٔمِس أمِس پٲنسہٕ دِژمٕتۍ، یُس تٔمِس زانہِ زِ پرٮ۪تھ أکِس انسانس کوتاہ اوس تجارتہٕ سٍتـ̡ حٲصل کورمُت۔ {پٲنسہٕ: Gr. silver}\n16.\\tپتہٕ آو گۄڈنیُک وَنُن، خداوند، تۅہہِ چُھہ داہ پاؤنڈ ہیوٚتمُت۔\n17.\\tتہٕ تٔمۍ ووٚن أمِس، خٲر، اے نیک خادم: کیازِ ژے چُھکھ واریاہ کم وفادار روزمُت، تہٕ چُھہ ژے دہن شہرن پیٹھ اختیار۔\n18.\\tتہٕ دۆیِم آو وَنُن، خداوند، تۅہہِ ہُند پونڈ ہیوٚت پانژھ پاؤنڈ۔\n19. تہٕ تٔمۍ ووٚن أمِس یِتھے پٲٹھۍ پانژن شہرن پیٹھ تہِ روزُن۔\n20. تہٕ بیاکھ آو ونان، خداوند، وچھ تُہند پونڈ یُس میہ نیپکنس منز تھوومُت چُھ:\n21. کیازِ بہٕ اوسُس ژے کھوژان، تکیازِ ژٕ چُھکھ اکھ پرہیزگار انسان: تہٕ ژے چُھکھ تُلُن یُس نہٕ ژے ووومُت اوس۔\n22. تہٕ سُہ چُھ أمِس ونان زِ بہٕ کَرٕ چانہِ پننہِ چُھنہٕ سٍتـ̡ ژے بدکار خادم۔ ژے ٲس پتاہ زِ بہٕ اوسُس اکھ کفایت شعار انسان، یہ رٹُن زِ میہ اوس نہٕ ترٲومُت، تہٕ لُٹُن زِ مے اوس نہٕ وونمُت:\n23.\\tتیلہِ کیازِ دِژ نہٕ ژے میون پونسہٕ بینکَس منز، یُتھ میانہِ یِنہٕ وِزِ بہٕ آسہٕ سود خوری ہٕندِس سٍتـ̡ پنُن پونسہٕ ضروُر؟ {پٲنسہٕ: Gr. silver}\n24.\\tتہٕ تٔمۍ ووٚن تِمن یِمن نِش یُس دَہ پاؤنڈ آسہِ، أمِس نِش رٔٹِو تہٕ دِیُن أمِس دَہ پاؤنڈ۔\n25. (تہٕ تمو ووٚن أمِس خداوند، أمِس چھُ داہ پاؤنڈ۔)\n26. تکیازِ بہٕ چُھس ژے ونان زِ یُس پرتھ کانہہ دِنہٕ یُس دِنہٕ یُن۔ تہٕ یٔمِس نِش یُس نہٕ آسہِ، سُہ تہِ یِیہِ أمِس نِش نِنہٕ۔\n27.\\tمگر تِم دُشمن یِم نہٕ بہٕ تِمن پیٹھ راج کرُن، أنِتھ تہٕ مٲرِن میہ برونہہ کُن۔\n28.\\tتہٕ ییلہ تٔمۍ یِتھٕ پٲٹھۍ کتھ کٔر، سُہ ووت برونہہ، یروشلمس کُن کھسنہٕ۔\n29.\\tتہٕ سپُد ییلہ سُہ بیتھفیج تہٕ بیتھانی نِش ووت، زیتونُک پہاڑ نِش ووت، تٔمۍ سوٗزۍ پنٕنۍ زٕ شٲگِر،\n30.\\tیہ ونِتھ زِ تم گٔژھ گامس منز اژُن۔ یتھ منز ژیہ اژنہٕ وِزِ ژیہ اکھ کۅکر بٔنِتھ وُچھِتھ، یتھ پیٹھ نہٕ زانہہ انسان بِہتھ اوس، تس یلہٕ تراوُن تہٕ أنِو سُہ یور ۔\n31.\\tتہِ اگر کانہہ انسان ژیہ پرژھہِ، تہِ کیازِ چھکھ ژیہ تراوان؟ یِتھٕ پٲٹھۍ کٔرِو تٔمِس وَنُن، کیازِ خداوند چُھ أمِس سٕنز ضرورت۔\n32. تہٕ یِم سوزنہٕ آمٕتۍ ٲسۍ، تِم گٔیہِ تِمن وَتھ تہٕ لٔبِتھ یِتھٕ پٲٹھۍ تٔمۍ تِمن وَننہٕ آمُت۔\n33.\\tتہٕ ییلہ تِم گُرِ راوان ٲسۍ، اَمہ کِس مٲلکَن ووٚن تِمَن زِ ژیہ کیازِ چھِو کُلہٕ کٔرِتھ؟\n34.\\tتہٕ تِمو ووٚن، خداوند چُھ أمِس سٕنز ضرورت۔\n35. تہٕ تِمو أنۍ سُہ عیسیٰ ہس نِش۔ تہٕ تِمو ترٛٲوۍ پنٕنۍ پلو کُلِس پیٹھ، تہٕ تِمو ترٛٲو عیسیٰ سٕندِس اَتھ پیٹھ۔\n36.\\tتہٕ ییلہ سُہ گٔیہ، تِمو پھٔہلٲوۍ وتہِ پَنٕنۍ پلو۔\n37.\\tتہٕ ییلہ سُہ نزدیک ووت، وُنہِ تہِ زیتون کِس پہاڑس پیٹھ ووسنہٕ وِزِ، سارِوٕے شٲگِرِیو ہیوٚت خدایہ سٕندِس سارِنٕے بٔڈِس کامہِ سٍتـ̡ خوش تہٕ خدایہ سٕنز حمد کرنہٕ شروع۔\n38.\\tیہ ونُن، بابرکت گژھہِ بادشاہ یُس خداوند سٕندِ ناوٕ سٍتـ̡ یِوان چُھہ: آسمانس مَنٛز امن تہٕ تھزرس مَنٛز جلال حٲصل۔\n39.\\tتہٕ بٔڈِس مَنٛز کینہہ فریسی ووٚن أمِس زِ آقا، پَنٕنـ̡ پَنٕنـ̡ شٲگِرـ̡ دِیُو۔\n40.\\tتہٕ تٔمۍ دِژ جواب تہٕ وونُن تِمن زِ بہٕ چُھس ژےٚ وَنُن زِ اگر یِم ژھۄپہٕ رٔٹِتھ روزن تیلہِ گژھن کٔنہِ کٔنہِ دِنہٕ۔\n41.\\tتہٕ ییلہ سُہ نزدیک ووت، تٔمۍ وُچھ شہر تہٕ رووُن اَتھ سٍتـ̡\n42.\\tیہ ونُن، اگر ژیہ زانہِ آسہِ، کم از کم پننِس دۅہس منز، تِم چیز {یُس} تُہٕندِس امنس سٍتـ̡ چُھہ! مگر وۅنۍ چھہِ تم چانہِ اچھن نِش پوشید۔\n43. تِکیازِ تۅہہِ دۅہ یِن تہٕ تۅہہِ دُشمن ژٔلِتھ تہٕ ژےٚ رٔلِتھ تہٕ ژےٚ رٔٹِتھ رٔٹِتھ روزِ۔\n44. تہٕ کرٕ ژے زمینہٕ سٍتـ̡ تہٕ تُہٕندِس شُرِس پانس اندر دِنہٕ۔ تہٕ تِم تراوَن نہٕ توے أکِس کٔنِس پیٹھ أکِس کٔنِس پیٹھ۔ تکیازِ ژیہ ٲس نہ پننہِ ملاقاتک وق زانان۔\n45.\\tتہٕ سُہ گوٚو مندرس مَنٛز، تہٕ یِم اتھ منز کٕننہٕ آمٕتۍ تہٕ یِم ہیوٚتـ̡ ہیوٚتـ̡ کٔرِتھ کٔڈِتھ کٔرِتھ۔\n46.\\tتِمن وَنُن چُھہ لیکھِتھ زِ میون گرٕ چُھ نمازُک گرٕ مگر تۅہہ چھُ یہِ چورن ہُند گۅپھ بنوومُت۔\n47.\\tتہٕ سُہ اوس مندرس مَنٛز پرناوان۔ مگر سردار پادٕرۍ تہٕ کاتب تہٕ لُکن ہٕندِس سردارَن کٔر أمِس تباہ کرنٕچ کوٗشش،\n48.\\tتہٕ ہیوٚک نہٕ لٔبِتھ زِ تِم کیا کٔرِتھ، تِکیازِ سارِنٕے لُکھ ٲسۍ أمِس بوزنہٕ خٲطرٕ سٮ۪ٹھاہ توجہ دِوان۔ {ٲس...: یا، أمِس پھانسی دِنہٕ}","1.\\tتہٕ سپُد تِمو منزٕ أکِس دۅہٕ، یێلہِ تٔمِس مندرس مَنٛز لُکن ہیچھناوُن، تہٕ انجیل ہٕنز تبلیغ کٔرٕن، بٔڈۍ پادٕرۍ تہٕ کاتب گٔیہِ بزرگن سٍتـ̡ أمِس سٍتـ̡ ۔\n2.\\tتہٕ وَنُن أمِس سٍتـ̡ وَنُن زِ ژے کمہِ اِختِیارٕ سٍتـ̡ چُھہ یِم کتھ کٔرِتھ؟ یا سُہ کُس چُھ یٔمۍ ژےٚ یہِ اختیار دِژمُت؟\n3.\\tتہٕ تٔمۍ دیُت جواب تہٕ وونُن تِمن تہِ اکھ کتھ پرژھہٕ۔ تہٕ مےٚ جواب دِیُن:\n4. یوحنا سُند بپتسمہ اوسا اسمانہٕ سٍتـ̡ یا انسانو سٍتـ̡ ؟\n5.\\tتہٕ تِمو کٔر پانس سٍتـ̡ استدلال کٔرِتھ، یێلہِ أسـ̡ وَنُن، اسمانہٕ پى۪ٹھ۔ سُہ وَنُن چھُ، تیٚلہِ کیازِ چھُنہٕ تٔمِس پیٹھ یقین کٔرِتھ؟\n6.\\tمگر اگر اسۍ ونو زِ انسانس متعلق۔ سارِنٕے لُکھ کٔرِن اسہِ پٲٹھۍ، تِکیازِ تِم گژھن قایل کرنہٕ زِ یوحنا اوس پیغمبر۔\n7.\\tتہٕ تِمو دِژ جواب زِ تِم ہیوٚک نہٕ ؤنِتھ زِ یہِ کتہِ چھُ۔\n8. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمَن زِ بہٕ کمہِ اِختِیار سٍتـ̡ یِم کٲم کران چھُس۔\n9.\\tتمہِ پتہ لُکن سٍتـ̡ یہ تمثیل کتھ کرٕنـ̡ شروع أکۍ نفرن ووت انگور باغ تہٕ دِژُن زٔمیٖن دارن نِش، تہٕ روٗد واریاہس کالس دور دراز ملکس منٛز۔\n10.\\tتہٕ یێمہِ وِزِ سوٗز تٔمۍ کٔرِن زمیندارن نِش اکھ نوکر، زِ تِم دِن أمِس انگورُک مٮ۪وٕ دِن، مگر زمیندارو دِژ أمِس مار، تہٕ سوٗزُن خٲلی ۔\n11.\\tبییہِ سوٗز تٔمۍ بیاکھ نوکر، تہٕ تِمو دِژ أمِس تہِ مار، تہٕ کٔرٕن أمِس شرم سان التجا تہٕ سوزُن خٲلی کٔرِتھ۔\n12.\\tبییہِ سوز تٔمۍ تریم تہ تمو تہِ زخمی کٔرِتھ کٔرِتھ ژٔٹِتھ کٔرِتھ۔\n13.\\tاَمہِ پتہٕ ووٚن انگورُک مالک، بہٕ کیا کرٕ بہٕ؟ بہٕ سوز پنُن ٹٲٹھ نیچو: یہ ہیکہِ تِم أمِس وُچھِتھ احترام۔\n14.\\tمگر ییلہ زمیندارو أمس وُچھ، تِمو کٔر پانہٕ پانہٕ وٲرِث، یہِ چُھ وٲرِث: یِمو أسۍ أمِس مٲرِتھ یُتھ وَراثت اسہِ آسہِ۔\n15.\\tتہ کٔرِکھ سُہ انگور منزٕ کٔڈِتھ تہٕ مٲرِتھ مٲرِتھ۔ تیلہِ کیا کرِ تِمن سٍتـ̡ انگورُک مالک؟\n16.\\tسُہ یِمن زمیندارن تباہ کٔرِتھ دِیہِ تہٕ دِیہِ باقیَن دِنہٕ۔ تہٕ ییلہ تمو بوز، تمو ووٚن، خدا نہ کر۔\n17.\\tتہٕ تٔمۍ وُچھِتھ وُچھِتھ وونُن، یہِ کیا چُھ لیکھنہٕ آمُت، سُہ کٔنہِ یُس معمارو رد کٔرِمُت، سُہ چُھ کونہٕ ہُند کلہٕ بنیومُت؟\n18.\\tیُس تہِ اتھ کنہِ پیٹھ پیوٚو سُہ گژھہِ پھُٹُن۔ مگر یٔمِس تہِ پیٚیہِ، سُہ کرِ أمِس پٔرِتھ پٔرِتھ۔\n19.\\tتہٕ اَمی ساعتہ کٔر بٔڈۍ پادٕرۍ تہٕ کاتبو أمِس پیٹھ اتھہٕ تراونٕچ کوٗشش۔ تہٕ تِم ٲسۍ لُکن کھوژان، تِکیازِ تِمو اوس سمجھان زِ تٔمۍ ٲس تِمن خلاف یہِ تمثیل بولمٕژ۔\n20.\\tتہٕ تِمو وُچھِتھ تہٕ سوٗزِکھ جاسوس، یِم پانس عادل نفر بناوٕن، یُتھ تِم تٔمۍ سٕندِس کلامَس رٔٹِتھ، یُتھ زن تِم أمِس گورنر سٕندِس اقتدارس تہٕ اختیارس حوالہٕ کٔرِتھ۔\n21.\\tتہٕ تِمو پرژھ أمِس زِ آقا، اسہِ چھیہ پتاہ زِ تہٕ چُھہ صحیح پٲٹھـ̡ ونان تہٕ ہیچھناوان چُھ، تہٕ چُھہ نہٕ کُنہِ تہِ شخصس قبوٗل کران، بلکہ چُھہ خدایہ سٕنز وتھ پٔزۍ پٲٹھـ̡ ہیچھناوٕنـ̡ {پٔزۍ: یا، حقیقتہٕ}\n22. کیا اسہِ خٲطرٕ چھا قیصرس خراج دیُن حلال کِنہ نہ؟\n23.\\tمگر تٔمۍ وُچھ تِہٕنزِ چالاکی تہٕ وونُن تِمن کیازِ چُھکھ میہ لالچ؟\n24. مے ہاو اکھ پونسہٕ۔ یہٕ کٔمۍ سٕنٛز تصویر تہٕ منظرنامہٕ چِھ؟ تِمو دِژ جواب تہٕ وونُن سیزر سُند۔\n25.\\tتہٕ تٔمۍ ووٚن تِمَن سٍتـ̡ یِم چیز قیصر سٕندِس سٍتـ̡ تہٕ خدایہِ سٕندِس سٍتـ̡ دِیِو تِم چیز یِم خدایہِ سٕندِ آسن۔\n26.\\tتہٕ تِم ہیوٚک نہٕ تٔمۍ سٕندِس جوابس پیٹھ حٲران تہٕ رٔٹِتھ رٔٹِتھ تہٕ رٔٹِتھ تہٕ رٔٹِتھ رٔٹِتھ ۔\n27.\\tاَمہ پتہٕ آو صدوقین مَنٛز کینہہ یِم انکار کران چھِ زِ قیامتُک امکان چھُ۔ تہٕ تمو پرژھ أمس،\n28.\\tیہ ونِتھ زِ موسیٰ ین لیوکھ اسہِ زِ اگر کٲنسہِ مرد سُند بٲے مرِ، زنانہٕ آسہِ، تہٕ سُہ بچہٕ ورٲے مرُن، تٔمۍ سُند بٲے گژھہِ پننہِ زنانہٕ نِن، تہٕ بٲے سٕندِس بٲیِس سٍتـ̡ بیول دِنہٕ۔\n29. اَمہِ مۄکھٕ ٲسۍ سَتھ بٲے: تہٕ گۄڈنِکِس بٲے رٔٹِتھ گٔیہِ خانٛدارِن، تہٕ مٔرِو بچہٕ ورٲے ۔\n30. تہٕ دوٚیِم نیو أمِس خانٛدارِنۍ تہٕ سُہ موٗد بےٚ بچہٕ۔\n31.\\tتہٕ تریم نیو سُہ ۔ تہٕ یِتھے پٲٹھۍ ٲسۍ ستھ تہِ: تہٕ تِمو ترٲوۍ نہٕ کانٛہہ شُر، تہٕ موٗدۍ۔\n32.\\tٲخری زنانہ تہِ مٔرۍ۔\n33. تَمہِ مۄکھٕ قیامتس مَنٛز کٔمۍ سٕنز زنانہٕ چھے ؟ تکیازِ ستھ ٲس أمس زنانہٕ۔\n34. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمن جواب دِتھ زِ دُنیاہٕکۍ شُرۍ چھِ خانٛدر کٔرِتھ، تہٕ یِم چھِ خانٛدر کرنہٕ آمٕتۍ:\n35. مگر یِم سُہ دُنیا حٲصِل کرنہٕ خٲطرٕ تہٕ مُردن ہٕندِس قیامتس لایق قرار دِنہٕ یِن، تِم چِھ نہٕ خاندر کٔرِتھ، تہٕ نہ چِھ خاندر کرنہٕ آمٕتۍ:\n36. نہ ہیکن تم مزید مرِتھ: کیازِ تم چِھ فرشتن برابر ۔ تہٕ چِھ خدایہِ سٕندِ بچہٕ، یِم قیامتٕکۍ اولاد چھِ۔\n37.\\tوۅنۍ ییلہ مردہ زندہ سپدِ، موسیٰ تہِ ہٲو کُنہِ\n38.\\tکیازِ سُہ چُھ نہٕ مُردن ہُند خدا بلکہ زندٕ سُند خدا، تکیازِ سٲری چِھ أمِس خٲطرٕ زندٕ روزان۔\n39.\\tاَمہ پتہٕ ووٚن کینہہ کاتب جواب دِنہٕ وٲلۍ، مالہ، ژے چھُکھ رٔژ وَنُن۔\n40.\\tتہ تمہ پتہ چھہ نہ تس کانہہ {سوال} پرژھنک ہمت کران۔\n41. تہٕ تٔمۍ ووٚن تِمَن زِ تِم کِتھہٕ پٲٹھۍ چھِ ونان زِ مسیح چُھ داؤد سُند نیٚچُو؟\n42. تہٕ داؤد چُھ پانہٕ زبور کِس کتابہِ مَنٛز ونان، خداوند چُھ میٲنِس آغس ووٚنمُت، تہٕ بہٕ بِہِتھ میانہِ دچھنہِ اتھس پیٹھ،\n43.\\tیوٚت تام نہ بہٕ چانۍ دُشمن پنُن کھۅر بنوو۔\n44. تَمہِ کِنۍ چُھ داؤد أمِس رب وَنان، تیلہِ کِتھہٕ چُھ سُہ پنُن نیٚچُو؟\n45.\\tپَتہٕ سارِنٕے لُکن ہٕندِس سامنس مَنٛز ووٚن تٔمۍ پننین شٲگِرن سٍتـ̡\n46.\\tکاتبن نِش گژھہِ ہوشیار روزُن، یِم زیٖٹھۍ پوشہٕ لٲگِتھ پکُن یژھان چھِ، تہٕ بازرَن مَنٛز خوش آمدید کَرُن، تہٕ یہودی عبادت خانن مَنٛز تھدِ تھدِ نشستہٕ تہٕ دعوتن مَنٛز اہم کمرن ہٕندِس بارس مَنٛز پکان چھِ۔\n47.\\tیُس بیواہ ہٕندِس گرس کھٮ۪وان چُھ، تہٕ أکِس مۅکھہٕ زیٖٹھۍ دُعا کران چھِ: یێمِس سٍتـ̡ زیادٕ سزا میلہِ۔","1. تہٕ تٔمۍ وُچھ تھوٚد تہٕ وُچھن امیر لوٗکھ پنٕنۍ تحفہٕ خزانس منٛز ترٛاوان۔\n2.\\tتہِ وُچھ اکھ بیچارہ بیواہ تہِ یۅسہٕ اتہِ دۅن لۅتہٕ کٔرِتھ۔\n3.\\tتہٕ وۆنُن، بہٕ چُھس پٔزۍ پٲٹھۍ ژےٚ ونان زِ أمِس بیواہ بیواہ چھے یِمو سارِوٕے کھۅتہٕ زیادٕ دِژمٕژ۔\n4.\\tیِمن سارِنٕے سٍتـ̡ چُھہ خدایہ سٕندِس نذرانہٕ سٍتـ̡ دِنہٕ آمُت، مگر سُہ چُھہ پننہِ غریبی ہٕندِس سارِنٕے زندس مَنٛز ترٲومُت۔\n5.\\tتہٕ یُتھ زن کینہہ مندرس متعلق وَنُن زِ یہ کِتھہ پٲٹھـ̡ اوس اصل کنیو تہٕ تحفو سٍتـ̡ سجاونہٕ آمُت، تٔمۍ ووٚن،\n6.\\tیِم چیز یِم تۅہہ وچھان چھِو، تِم دۅہ یِن یِمن منز اکھ کٔر ییہ نہٕ تراونہٕ، یُس نہٕ تراونہٕ یِن۔\n7.\\tتہٕ تِمو پرژھ أمِس زِ مالک، مگر یِم چیز کر بنہِ؟ تہٕ ییلہ یِم چیز سپدن تیلہِ کیا نشانہٕ آسہِ؟\n8. تہٕ ووٚن تٔمۍ ووٚن، ہوشیار گژھ نہٕ دھوکہٕ دِنہٕ، تکیازِ واریاہ یِن میانہِ ناوٕ سٍتـ̡ یِن، بہٕ چُھس مسیح۔ تہٕ وقت آو نزدیک: لہذا گژھ نہٕ تمن پتہٕ۔ {تہٕ وقت: یا، تہٕ، وقت}\n9.\\tمگر ییلہ جنگن تہٕ ہنگامہ آرایی ہٕنز خبر بوزِو، تیٚلہِ گژھہِ نہٕ خوفزدہ گژھُن، تکیازِ یِم چیز گژھہِ گۅڈٕ سپدٕنۍ۔ مگر اند {چُھ} نہٕ اَتھ سٍتۍ تہٕ اَتھ سٍتـ̡ ۔\n10.\\tتێلہِ ووٚن تِمن زِ قوم گژھہِ قومس خلاف تہٕ بادشٲہی کٔرِن بادشاہتس خٕلاف۔\n11. تہٕ بٔڈۍ زلزلہٕ یِن مختلف جاین تہٕ قحط تہٕ وباہن ہٕندِ۔ تہٕ آسمانہٕ پیٹھہٕ گژھن خوفناک نظارٕ تہٕ عظیم نشانہٕ۔\n12.\\tمگر یِمو سارِوٕے برونہہ کُن تِم تۅہہِ پیٹھ اتھہٕ تھٲوِتھ، تہٕ تۅہہِ کٔرِن یہودی عبادت خانن تام تہٕ جیلن مَنٛز، میانہِ ناوٕ خٲطرٕ بادشاہن تہٕ حکمرانن برونہہ کُن اننہٕ۔\n13. تہٕ یہِ گژھہِ توے کُن گوٲہی دِنہٕ۔\n14.\\tتَمہِ کِنۍ کٔرِو پننِس دِلَس مَنٛز بٔرِتھ، یُس جواب دِیُو، تَمہِ برونہہ کُن کٔرِو نہٕ غور کرنہٕ:\n15. تکیازِ بہٕ دِیہ ژےٚ اکھ ٲس تہٕ حکمت یُس نہٕ تُہند سٲری دُشمن ہێکہِ انکار کٔرِتھ تہٕ نہ مزاحمت کٔرِتھ۔\n16.\\tتہٕ یِمن ہٕندِس مٲلِس ماجہ تہٕ بٲے تہٕ رشتہٕ دار تہٕ یارن ہٕندِ دٔسۍ دھوکہ دِنہٕ۔ تہٕ تم گژھن مارنہٕ۔\n17.\\tتہٕ میانہِ ناوٕ خٲطرٕ گژھِ سارِنٕے نفرتَس سٍتـ̡ نفرت۔\n18.\\tمگر تۅہہِ ہُند اکھ مس تہِ گژھہِ نہ ختم سپدُن۔\n19.\\tپننِس صبرس مَنٛز تھاوُن پَنُن روح۔\n20. تہٕ ییلہ تم یروشلمس لشکر سٍتـ̡ ؤلِتھ وُچھِو، تیلہِ گژھہِ زٲنِتھ زِ اَمہ ہُند ویران چُھ نزدیک۔\n21. تیلہٕ یِم یہوداہس مَنٛز چھِ تِم پہاڑن کُن ژلٕنۍ۔ تہٕ یِم اتھ منز موجود چھِ، تِم گژھن نیبر نیرُن۔ تہٕ تِم گژھن نہٕ تِمن مُلکن منٛز دٲخل گژھن۔\n22.\\tیِم چھِ انتقامٕکۍ دۅہہ، یُتھ سارِنٕے چیز یِم لیکھنہٕ آمٕتۍ چھِ پوٗرٕ سپدٕنۍ۔\n23. مگر یِمن دۅہن بچہٕ آسہِ تِمن تہٕ یِمن دۅہن دِنہٕ والٮ۪ن ہٕندِس دۅہس سٍتـ̡ افسوس چھُ! تکیازِ زمینس منز گژھہِ سٮ۪ٹھاہ مصیبت تہٕ یِمن لوکن پیٹھ غصہٕ۔\n24. تہٕ تِم گژھن تلوار ہٕندِس اندس سٍتـ̡ پۯاونہٕ، تہٕ یِن سارنٕے قومن مَنٛز قٲد کرنہٕ، تہٕ یروشلم یِن غیر قومن ہٕندِس زمانس مُکمل گژھنس تام یِنہٕ۔\n25.\\tآفتابس منز، زونہِ منز تہٕ ستارن منز آسن نشانہٕ۔ تہٕ زمینس پیٹھ قومن ہٕنز پریشانی، پریشٲنی سٍتۍ؛ سمندر تہٕ لہرٕ گڑبڑ؛\n26.\\tانسانن ہٕندِ دِل چھِ تِمن خوفہٕ سٍتـ̡ ناکام گٔژھان، تہٕ یِمن چیزن ہٕنز رٲچھ کرنہٕ خٲطرٕ یِم زمینس پیٹھ یِوان چھِ: تکیازِ آسمانٕچ طاقتہٕ گژھہِ ہلاونہٕ۔\n27. تہٕ پَتہٕ وُچھن تِم اِنسان سُند نیٚچُو یُس طاقت تہٕ بٔڈ جلال سٍتـ̡ یِوان چھُ۔\n28. تہٕ ییلہ یِم چیز سپدن شروع گژھن، تیلہِ تھوٚد کٔرِو تہٕ کلہٕ تُلِتھ تُلِو۔ تکیازِ تُہند نجات چھُ نزدیک۔\n29.\\tتہٕ تٔمۍ کٔر تِمن سٍتـ̡ اکھ تمثیل۔ وُچھِو انجیر کُلِس تہٕ سارِنٕے کُلۍ۔\n30.\\tییلہ تم وۅنۍ گولہ چلاوان چھہِ، توے چھہ پننین پانن وچھان تہ زانان زِ وۅنۍ چھہ موسم گرما نزدیک یوان۔\n31. یِتھے پٲٹھـ̡ یێلہِ یێلہِ یێلہِ یِم چیز سپدان وُچھِو، تێلہِ زانِو زِ خدایہِ سٕنز بادشٲہی چھِ نزدیک۔\n32. بہٕ چُھس ژےٚ وَنُن زِ یہِ زمانہٕ گژھِ نہٕ توٚت تام زِ یِہ زمانہٕ گژھِ نہٕ پوٗرٕ سپدِ۔\n33.\\tآسمانس تہٕ زمینہٕ گژھن ژٔلِتھ مگر میٲنۍ کلام گژھِ نہٕ ژٔلِتھ۔\n34.\\tتہٕ پَنُن پَنُن ہوشیار روزُن، نتہٕ کُنہِ ساتہٕ گژھہِ تُہُند دِل یِمن ہٕندِس دِلَس سٍتـ̡ زیادٕ شراب، تہٕ یێلہِ سُہ دۅہ یِیہِ بے خبری سٍتـ̡ یِنہٕ۔\n35.\\tیِہ چُھہ سارِنٕے سارِنٕے سٍتـ̡ یُس سارِنٕے زمینہِ ہٕندِس بُتھِس پیٹھ روزان چُھہ، تِمن سارِنٕے سٍتـ̡ یِمن ہٕندِس\n36. تێمہِ کِنۍ تھٲوِو تہٕ ہمیشہٕ دُعا کٔرِو، یُس یِمن سارِنٕے چیزن نِش بچنہٕ خٲطرٕ تہٕ انسان سٕندِس نیٚچوِس برونہہ کُن کھڑا گژھُن۔\n37. تہٕ دۅہلہٕ اوس سُہ مندرس مَنٛز پرناوان ۔ تہٕ رٲژ دراو سُہ نیبر، تہٕ روزُن تتھ پہاڑس مَنٛز یتھ {زیتونُک پہاڑ} ونان چھِ۔\n38.\\tتہٕ سارِوٕے لُکھ آیہِ سُلہِ سُلہِ مندرس مَنٛز أمِس نِش بوزنہٕ خٲطرٕ۔","1. وۅنۍ آو خمیر روٚس روٹی ہُند عید نزدیک، یتھ فسح ونان چھِ۔\n2. تہٕ سردار پادٕرۍ تہٕ کاتب ژھانڈان زِ تِم کِتھ کٔنۍ ہیکن أمِس مٲرِتھ۔ تکیازِ تم ٲسۍ لوکن کھوژان۔\n3. پَتہٕ ژاو شیطان یہوداہَس مَنٛز یُس اِسکریوٹ ناو اوس، یُس بہَن ہُند تعداد اوس۔\n4. تہٕ سُہ پوٚک پنٕنۍ وَتھ، تہٕ کٔرٕن بٔڈۍ پادٕرین تہٕ کپتانن سٍتـ̡ کتھ باتھ، کِتھہ کٔنۍ کرِ سُہ تِمن سٍتـ̡ دھوکہٕ۔\n5. تہٕ تِم گٔیہِ خۄش، تہٕ کوٚرُکھ أمِس پٲنسہٕ دِنُک وعدٕ۔\n6. تہٕ تٔمۍ کوٚر وعدٕ تہٕ ہجوم ہٕنٛزِ غٲر موجودگی منٛز کوٚرُن أمِس دھوکہٕ دِنُک موقعہٕ۔ {منز...: یا، ہنگامہ ورٲے}\n7. پَتہٕ آو خمیرٕ روٚس روٹی ہُند دۅہ، یێلہِ فسح گژھہِ مارنہٕ یُن۔\n8. تہٕ تٔمۍ سوٗزۍ پطرس تہٕ یوحنا تہٕ وونُن، گژھ تہٕ اسہِ فسح تیار کرُن، یُتھ أسۍ کھٮ۪تھ ہیکو۔\n9.\\tتہٕ تِمو ووٚن أمِس زِ أسۍ کتہِ کَتہِ تیار کٔرِو؟\n10.\\tتہٕ تٔمۍ ووٚن تِمَن زِ یێلہِ یێلہِ شہرس مَنٛز اژِو، تتہِ گژھہِ اَکھ شخٕص یُس آبہٕ ہُند جَگ ہٮ۪تھ آسہِ۔ أمِس پَتہٕ پَتہٕ گٔژھِو تَتھ گَرَس منٛز یَتھ منٛز سُہ اژان چھُ۔\n11.\\tتہٕ تُہۍ وَنُن گرٕ کِس نیک شخصس سٍتـ̡ وَنُن، آقا چُھہ ژے ونان زِ مہمان خانہٕ کتہِ چُھہ، ییتہِ بہٕ پننین شاگردن سٍتـ̡ فسح کھٮ۪یہِ؟\n12. تہٕ سُہ ہٲوِو تۅہہِ اکھ بوٚڈ پیٹھم کمرہٕ یُس سجاونہٕ آمُت چھُ، تتہِ کرو تیار۔\n13. تہٕ تِمو گٔیہِ تہٕ لٔبِتھ یِتھہٕ پٲٹھۍ تٔمۍ تِمن ووٚنمُت اوس، تہٕ تِمو کٔر فسح تیار۔\n14. تہٕ ییلہ وق آو سُہ بیوٹھ تہٕ باہ رسول۔\n15.\\tتہٕ تٔمۍ ووٚن تِمَن زِ بہٕ چُھس یہِ فسح ژے سٍتـ̡ کھٮ۪نُک خواہش: {خواہشٕ سٍتـ̡ ...: یا، بہٕ چُھس دِل دِلہٕ سٍتـ̡ یژھان}\n16. تکیازِ بہٕ چُھس ژےٚ ونان زِ بہٕ چُھس نہٕ اتھ سٍتـ̡ کھٮ۪وان، یوتام نہٕ یہِ خدایہ سٕنزِ بادشٲہی مَنٛز پوٗرٕ سپدِ۔\n17.\\tتہٕ تٔمۍ رٔٹِتھ پیالہ تہٕ شُکریہ ادا کٔرِتھ وونُن، یہ رٔٹِتھ تہٕ پانَس مَنٛز تقسیٖم کٔرِو:\n18. تکیازِ بہٕ چُھس ژے ونان زِ بہٕ چُھس نہٕ توٚت تام زِ خدایہِ سٕنز بادشاہی یِنہٕ توٚت تام بہٕ چُھس نہٕ بیلہٕ سٕندِ پھلہٕ سٍتـ̡ چیٚوان۔\n19. تہٕ تٔمۍ روٚٹ روٹ، تہٕ شُکریہ ادا کٔرِتھ دِژُن تہٕ دِتُن تِمن دِژُن، یہِ چُھ میون جسم یُس تۅہہِ خٲطرٕ دِنہٕ آمُت چُھ، یہِ کرُن میانہِ یاد پٲٹھۍ۔\n20. یِتھے پٲٹھـ̡ چُھہ شامُک پیالہ تہِ ونان زِ یہِ پیالہ چُھہ میانہِ خونس مَنٛز نۆو عہد نامہٕ، یُس تۅہہِ ہٕندِ خٲطرٕ چُھہ تراونہٕ آمُت۔\n21.\\tمگر وچھ یُس میہ دھوکہ دِوان سُہ چھہ میہ سٍتۍ میزس پیٹھ۔\n22. تہٕ پٔزۍ پٲٹھـ̡ چُھ انسان سُند فرزند نیران، یُتھ زن أمِس طے کرنہٕ آمُت چُھ، مگر تٔمِس انسانس ہُند افسوس چُھہ یُس أمِس دھوکہٕ دِوان چُھ!\n23.\\tتہٕ تِمو ہیوٚت پانہٕ وٲنۍ پرژھنہٕ زِ یِمو منزٕ کُس چُھ یہِ کٲم کرُن۔\n24.\\tتہٕ تِمن مَنٛز اوس اکھ جھگڑا تہِ، یِمو منزٕ کُس کُس سارِوٕے کھۄتہٕ بوٚڈ شمار گژھہِ کرنہٕ یُن۔\n25. تہٕ تٔمۍ ووٚن تِمن زِ غیر قومن ہٕندِ بادشاہ چِھ تِمن پیٹھ ربوبیت کران۔ تہٕ یِم تِمن پیٹھ اختیار استعمال کران چھِ، تِمن چھِ محسن وننہٕ یِوان۔\n26.\\tمگر یُس تہِ بٔڈ آسہِ، سُہ گژھہِ لۅکٹِس ہیوٗ آسُن۔ تہٕ سُہ یُس سردار چُھ، یُس خدمت کران چُھ۔\n27.\\tکیازِ کیا {چُھ} بوڈ سُہ یُس مازس پیٹھ بِہتھ چُھ، یا سُہ یُس خدمت کران چُھ؟ {کیا سُہ چھُنہٕ مازس پیٹھ بِہتھ؟ مگر بہٕ چُھس توے منز، یُس خدمت کران چُھ۔\n28.\\tتم چھہِ تم یم میانین فتنن منز میہ سیتۍ جٲری رودۍ۔\n29. تہٕ بہٕ چُھس ژےٚ خٲطرٕ اکھ بادشاہت مقرر کٔرمٕژ، یِتھہٕ کٔنۍ میانہِ مٲلہِ مُقرر کٔرمٕژ چھِ۔\n30. یُتھ تُہۍ میانہِ بادشٲہی مَنٛز میٲنِس دسترس پیٹھ کھٮ۪تھ چیٚو، تہٕ تختن پیٹھ بِہِتھ اسرٲیلٕکۍ بہن قبیلن ہُند فیصلہ کٔرِتھ۔\n31.\\tتہٕ خداوند ووٚن، شمعون، وُچھ، شیطان چُھ ژے یژھان، یُتھ سُہ کٕنکہٕ پٲٹھـ̡ ژٔٹِھتھ ژٔٹِھہِ:\n32.\\tمگر میہ کٔر چانہِ خٲطرٕ دُعا زِ تُہند ایمان گژھہِ نہٕ ناکام تہٕ ییلہ تہٕ یێلہِ تہٕ ژے بدلٲوِو، پَنٕنـ̡ بٲے کٔرِو مضبوط۔\n33. تہٕ تٔمۍ ووٚن أمِس خداوند، بہٕ چُھس ژےٚ سٍتـ̡ جیلس مَنٛز تہٕ مرنہٕ خٲطرٕ تیار۔\n34. تہٕ تٔمۍ ووٚن، بہٕ چُھس ژےٚ وَنُن، پطرس، کۅکُر گژھِ نہٕ از دۅہہ کۅکُر کۅکُر، امہ برونہہ زِ ژٕ کرِ تریہ لٹہِ انکار زِ ژٕ چھُکھ مےٚ زانان۔\n35.\\tتہٕ تٔمۍ ووٚن تِمَن زِ ییٚلہِ مے ژےٚ پرس تہٕ کھورِ تہٕ کھورِ ورٲے سوزمُت، تہٕ اوسُکھ نہٕ کُنہِ تہِ کُنہِ چیزٕچ کٔمی؟ تہٕ تِمو ووٚن نہٕ کیٚنٛہہ۔\n36.\\tاَمہِ پتہٕ ووٚن تِمن مَگَر، مگر یُس پرس آسہِ، سُہ نِش تہٕ یِتھٕ پٲٹھۍ چھُ سُہ نِش تہٕ یِتھٕ پٲٹھۍ چھُ سُہ نِش تٔمِس پَنُن پَلَو کٕنُن تہٕ اَکھ مٔلِتھ۔\n37.\\tکیازِ بہٕ چُھس ژے ونان زِ یُس لیکھنہٕ آمُت چُھ، سُہ گژھہِ وُنہِ تہِ میانہِ مَنٛز پورٕ سپدُن، تہٕ سُہ اوس گُننہٕ والٮ۪ن مَنٛز شمار کرنہٕ آمُت: تکیازِ میانہِ سٍتـ̡ چُھہ یێلہِ ہُند خاتمہٕ سپدُن۔\n38.\\tتہٕ تِمو ووٚن، خداوند، وُچھ، یِتھے چھِ زٕ تلوار۔ تہٕ تٔمۍ ووٚن تِمن کٲفی۔\n39.\\tتہٕ سُہ دراو نیبر، تہٕ ووت زیتون کِس پہاڑس کُن۔ تہٕ تٔمۍ سٕندۍ شٲگِر تہِ گٔیہِ أمِس پتہٕ۔\n40. تہٕ ییلہ سُہ اتھ جایہ اوس، تٔمۍ ووٚن تمن دُعا زِ تم گژھ نہٕ فتنس منٛز اژنہٕ۔\n41.\\tتہٕ سُہ آو تِمن نِش کٔنہِ کٔنہِ کُ\n42.\\tیہ ونُن، بابہ، اگر ژیہ یژھان چھیہ، یہ پیالہ کڈُن میانہِ نِش، بہرحال گژھہِ نہ میٲنۍ مرضی بلکہ تۅہہ کرُن۔ {رضامند، ہٹاوُن: Gr. ہٹاونہٕ خٲطرٕ تیار}\n43.\\tتہٕ آسمانہٕ پیٹھٕ آو أمِس نِش اکھ فرشتہ ظٲہر، یُس أمِس مضبوٗط کٔرِتھ۔\n44.\\tتہٕ تٔمۍ کٔر دُعا دُعا تہٕ تٔمۍ سُند پسینہٕ اوس تِتھۍ زٔمیٖنس پیٹھ وسان خونٕکۍ بٔڈۍ قطرہٕ۔\n45.\\tتہٕ ییلہ سُہ دُعا پٲٹھـ̡ تھوٚد تہٕ پنہٕ نِس مریدن نِش آو، تٔمۍ وُچھ تِم غمس سٍتـ̡ شوٚنگِتھ،\n46.\\tتہٕ تِمن وونُن، کیازِ چھِو شوٚنگِتھ؟ تھوٚد تہٕ دُعا کٔرِو، نِش گژھِ فتنہٕ منٛز۔\n47. تہٕ ییلہ سُہ وُنہِ تہِ کتھ کران اوس، وُچھ اکھ بٔڈ، تہٕ یُس یہوداہ ناو اوس، یُس بہو منزٕ اکھ اوس، گوٚو تمن برونہہ کُن تہٕ ووت عیسیٰ ہس نِش بوسہ دِنہٕ خٲطرٕ۔\n48.\\tمگر حضرت عیسیٰ علیہ السلام ووٚن أمِس زِ یہوداہ، کیا ژے چُھکھ انسان سٕندِس نیچوِس بوسہ دِتھ دھوکہٕ دِوان؟\n49.\\tییلہ تِمو یِمو أمِس اندۍ پکھۍ وُچھ زِ امہِ پتہٕ کیا سپدِ، تِمو ووٚن أمِس خدا، کیا أسۍ تلوار سٍتـ̡ مار دِنہٕ؟\n50.\\tتہٕ یِمو منزٕ لوٚگ أکۍ پادٕرۍ سٕندِس خادمس تہٕ ژٹُن تٔمِس دٔچھُن کَن۔\n51.\\tتہٕ حضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن، وُنیُک تام چُھہ مُشکِل۔ تہٕ تٔمۍ کٔر پننس کنس تھپھ، تہٕ کوٚرُن أمس ٹھیٖک۔\n52. اَمہِ پَتہٕ ووٚن حضرت عیسیٰ علیہ السلامن تہٕ مندرٕکۍ سردار تہٕ بُزرگَن یِم أمِس نِش آمٕتۍ ٲسۍ، کیا تُہۍ کٔرِو أکِس چورس خٕلاف، تلوار تہٕ لورِ ہٮ۪تھ؟\n53.\\tییلہ بہٕ روزانہٕ ژے سٍتـ̡ مندرس مَنٛز اوسس، تہٕ ژے کٔرِو نہٕ میانہِ خلاف اتھہٕ پٲٹھۍ، مگر یہِ چُھہ تُہند وق تہٕ انہِ گٹہِ ہُند طاقت۔\n54.\\tتِمو رٔٹِتھ رٔٹِتھ تہٕ أنِکھ سُہ بڈِ پادٕرۍ سٕندِس گَرَس مَنٛز۔ تہٕ پطرس پوٚت دور پوٚت۔\n55.\\tتہٕ ییلہ تِمو ہالس منز نار زال، تہٕ یکوٹہ بٔٹھۍ، پطرس بیوٹھ تمن منز۔\n56.\\tمگر أکۍ دٲرِ وُچھ أمِس نارس نِش بِہتھ تہٕ وُچھن أمِس کُن تہٕ وونُن زِ یہِ نفر تہِ اوس أمِس سٍتۍ۔\n57.\\tتہٕ تٔمۍ کٔر أمِس انکار کٔرِتھ ونان زِ زنانہٕ، بہٕ چھُس نہٕ أمِس زانان۔\n58.\\tتہٕ کینژَس کالس پَتہٕ وُچھ بییِس أمِس تہٕ وُچھُن تہٕ وونُن تہٕ تُہۍ تہِ چھُکھ تِمن منز۔ تہٕ پیٹر ووٚن، انسان، بہٕ چُھس نہٕ۔\n59.\\tتہٕ اکہ گھنٹہٕ پتہٕ بییِس گھنٹہٕ کس وقفس منز کوٚرُن یقین سان تصدیق کٔرِتھ ونان، أکِس حقیقتس مُتلق اوس یہِ {ساتھی} تہِ أمِس سٍتۍ: کیازِ سُہ چُھ اکھ گلیلی۔\n60. تہٕ پطرس ووٚن، انسان، بہٕ چُھس نہٕ پتاہ ژے کیا چُھ وَنان۔ تہ فورا، ییلہ سہ وُنہِ تہِ کتھ کٔرتھ، کۅکر عملہ۔\n61.\\tتہٕ خداوند پھیُر تہٕ پطرس کُن نظر۔ تہٕ پطرس اوس رب سُند کلام یاد، یِتھ کٔنۍ تٔمۍ أمِس ووٚنمُت زِ کۅکر کۅکرِ برونہہ کُن، ژے کٔرِکھ میہ تریہ لٹہِ انکار۔\n62.\\tتہٕ پطرس دراو نیبر، تہٕ ووٚتھ وُنُن۔\n63.\\tتہٕ یِمو لُکھ عیسیٰ مسیحس رٔٹِتھ أمِس ٹھٹھہٕ کٔرِتھ تہٕ دِژُکھ أمِس مار۔\n64.\\tتہٕ ییلہ تمو أمس أچھ پٔٹِتھ تھپھ کٔر، تہٕ پرژھکھ أمس بٔتھِس پیٹھ تہٕ پرژھن، پیشن گوئی، کُس چُھ ژےٚ مارمُت؟\n65.\\tتہٕ باقٕے واریاہ کتھٕ چھِ تٔمِس خٕلاف کُفر کٔرِتھ۔\n66.\\tتہٕ یُتھُے دۅہ آو لُکن ہٕندِ بزرگ تہٕ بٔڈۍ پادٕرۍ تہٕ کاتب اِکہٕ وٹہٕ تہٕ وونُکھ أمِس پننہِ مجلسس مَنٛز،\n67. کیا تُہۍ چھوا مسیح؟ اسِہ وَن. تہٕ تٔمۍ ووٚن تِمَن زِ اگر بہٕ ژےٚ ؤنِتھ تہٕ تُہۍ کٔرِو نہٕ یٔقیٖن:\n68.\\tتہِ اگر میہ تہِ پرژھہِ، تہِ کرِ نہ میہ جواب تہ نہ تراوِ میہ تہِ۔\n69.\\tامہِ پتہٕ گژھہِ انسان سُند فرزند خدایہ سٕندِس طاقتس دچھنہِ اتھس پیٹھ بِہتھ۔\n70.\\tاَمہ پتہٕ ووٚن سارِوٕے یِمو سارِوٕے خدایہِ سُند نیٚچُو؟ تہٕ تٔمۍ ووٚن تِمَن زِ بہٕ چھُس۔\n71.\\tتہٕ تِمو ووٚن، اسہِ کیا چُھ مزید گواہ آسنٕچ ضرورت؟ تکیازِ اسہِ چھہ پانہ تہِ بوزمُت۔","1. تہٕ تِمو ہُند سورُے بٔڈ ووٚتھ، تہٕ نِیوُن سُہ پیلاطس نِش۔\n2. تہٕ تِمو لوگُکھ أمِس پیٹھ الزام لگاوُن، یہِ ونُن زِ اسہِ اوس یہِ {نفر} قومس بگاڑان تہٕ قیصرس خراج دِنس منع کران تہٕ یہِ ؤنِتھ زِ سُہ چُھ پانہٕ مسیح بادشاہ۔\n3.\\tتہٕ پیلاطس پرژھ أمِس زِ کیا تُہۍ چھُکھ یہودین ہُند بادشاہ؟ تہٕ تٔمۍ دیُت أمس جواب تہٕ وونُن، تہٕ تُہۍ چُھ وَنان۔\n4.\\tپَتہٕ ووٚن پیلاطس بٔڈۍ پادٕرین تہٕ لُکن سٍتـ̡، مے چُھنہٕ أمِس شخصس مَنٛز کانہہ عیب باسان۔\n5.\\tتہٕ تِم ٲسۍ زیادٕ سخٕت تہٕ ونان زِ سُہ چُھ لُکن ہٕندِس سٍتـ̡ ہٕندِس سارِنٕے یہودی سٍتـ̡ ہٕندِس سٍتـ̡ پرناوان یُس گلیل پیٹھٕ یێتھ جایہ تام ہیچھناوان چُھ۔\n6.\\tییلہ پیلاطس گلیلِس متعلق بوز، تٔمۍ پرژھ زِ یہِ نفر چھا گلیلی۔\n7. تہٕ یێلہِ أمِس پتاہ زِ سُہ چُھ ہیرودس سٕندِس دٲیرس سٍتـ̡ تعلق تھاوان، تٔمۍ سوٗز سُہ ہیرودیس نِش، یُس تمہِ وِزِ یروشلمس مَنٛز اوس۔\n8. تہٕ ییلہ ہیرودین عیسیٰ وُچھ، سُہ گوٚو سٮ۪ٹھاہ خۄش، تکیازِ سُہ اوس أمِس واریاہس کالس وُچھنُک خواہش، تکیازِ أمِس ٲس أمِس متعلق واریاہ کتھ بوزمٕژ۔ تہٕ تس ٲس وۅمید زِ سہ آسہ کانہہ معجزہ وچھمُت۔\n9.\\tامہ پتہ کٔر تمس سٍتۍ واریاہن لفظن منز سوال۔ مگر تمۍ دیت نہ تس کانہہ جواب۔\n10.\\tتہٕ سردار پادٕرۍ تہٕ کاتب کھڑا تہٕ لوٚگ أمِس پٮ۪ٹھ سخٕت الزام لگاونہٕ۔\n11. تہٕ ہیرودس کٔر پننین جنگی نفرن سٍتـ̡ سُہ ٹھٹھہٕ تہٕ کوٚرُن أمِس خوٗبصوٗرت پوشہٕ لٲگِتھ تہٕ سوٗزُن سُہ دُبارٕ پیلاطس نِش۔\n12. تہٕ امی دۅہہ گٔیہِ پیلاطس تہٕ ہیرودیس اِکہٕ وٹہٕ یار، تکیازِ امہ برونہہ ٲس تِم پانہٕ أکِس درمیان دُشمنی۔\n13. تہٕ پیلاطس، یێلہِ تٔمۍ بٔڈۍ پادٕرین تہٕ حُکُمران تہٕ لُکن یکوٹہٕ بُلوو،\n14.\\tتِمن وَنُن زِ تہٕ ژے چُھہ یہِ شخٕص میانہِ نِش أنِمُت، یُس لُکن ہُند غلط استعمال کران چُھ، تہٕ وُچھِو، میہ چُھہ نہٕ تۅہہِ برونہہ کُن أمِس شخصس سٍتـ̡ تِمن چیزن ہُند کانہہ عیب لبنہٕ آمُت، یِمن ہُند تُہۍ الزام لگاوان چھِو۔\n15. نہٕ تہٕ ہیرودس: کیازِ مے سوٗزۍ تۅہہ أمِس نِش۔ تہٕ لو، أمِس چھُنہٕ موتُک لایق کانٛہہ تہِ کرنہٕ آمُت۔\n16.\\tبہٕ کٔرٕ تس سزا تہٕ یلہٕ تراوُن۔\n17. (ضرورتہٕ مۅکھہٕ پزِ سُہ یِمن خٲطرٕ دعوتس مَنٛز یلہٕ تراوُن۔)\n18.\\tتہٕ تِمو دِژ اَکہٕ وِزِ یہِ {انسان} ژٔلِتھ تہٕ اسہِ برابن یلہٕ تراوُن:\n19. (یُس شہرس منز کرنہٕ آمُت أکِس خاص بغاوت خٲطرٕ تہٕ قتلہٕ خٲطرٕ آو جیلس منز تراونہٕ۔)\n20. تَمہِ کِنۍ کٔر پیلاطس عیسیٰ سٕندِ یلہٕ تراونہٕ خٲطرٕ تیار، تِمن سٍتـ̡ دُبارٕ کتھ کرنہٕ۔\n21.\\tمگر تِمو دِژ وَنُن زِ صلیب دِیُن، صلیب دِیُن۔\n22.\\tتہٕ تٔمۍ ووٚن تِمن تریمہِ لٹہِ زِ کیازِ، تٔمۍ کیا بد کار کورمُت؟ میہ لوٚب نہ تس منز مرنُک کانہہ وجہ: لہذا کرٕ بہٕ تس سزا، تہٕ تراوٕ أمس تراون۔\n23.\\tتہٕ تِم گٔیہِ بَڑِ آوازٕ سٍتـ̡ یُس سُہ صلیب دِنہٕ یُن۔ تہٕ تِمن تہٕ بٔڈۍ پادٕرین ہٕنز آواز گٔیہِ غالب۔\n24. تہٕ پیلاطس دِژ سزا زِ یہِ گژھہِ تِمن ہٕندِس ضروُرتس مُطٲبِق آسُن۔ {دِژمُت...: یا، منظوٗر}\n25.\\tتہٕ تٔمۍ دِژ تِمن نِش یلہٕ زِ بغاوت تہٕ قتلہٕ کِس مۅکھٕ آو قٲد خانس مَنٛز تراونہٕ، یُس تِمو یژھان اوس۔ مگر تٔمۍ واتنوو عیسیٰ مسیح تہنزِ مرضی تام۔\n26. تہٕ یێلہِ تِمو أمِس نِش نیران، تِمو تھوو أکِس شمعون یُس مُلکہٕ منزٕ نیران اوس، تہٕ تٔمِس پیٹھ تھووُکھ صلیب ، یُس عیسیٰ سٕندِ پتہٕ رٔٹِتھ روزِ۔\n27.\\tتہٕ تٔمِس پَتہٕ لُکن تہٕ زنانن ہٕنز اکھ بٔڈ جمٲژ یِمو أمِس ماتم تہٕ ماتم تہٕ ماتم کٔرۍ۔\n28. مگر عیسیٰ علیہ السلام یِمن کُن پھیُرِتھ وونُن، یروشلمٕچ کورِ، میانہِ خٲطرٕ روو نہٕ بلکہ روو پانس خٲطرٕ تہٕ پننین شُرین خٲطرٕ۔\n29.\\tتکیازِ وچھو تم دۅہ چھہِ یِوان، یتھ منز تم ونان چھہِ، بابرکت چھہِ بنجر، تہٕ رحم یم نہٕ زانہہ ننگے چھہِ، تہٕ تِم دۅہ یِم نہٕ زانہہ چوس دِنہٕ آمٕتۍ۔\n30. تیلہٕ گژھن تِم پہاڑن وَنُن شروع کٔرِتھ، اسہِ پیٹھ پیوٚو۔ تہٕ بالن تام، اسہِ کور کرُن۔\n31.\\tیێلہِ یێلہِ یِم کُلِس منز یِم کٲم کٔرِن، خشک کُلِس منز کیا ییہِ کرنہٕ؟\n32.\\tتہٕ بییہ زٕ بدکار تہِ ٲسۍ، یِم أمِس سٍتۍ مارنہٕ آیہ۔\n33.\\tتہٕ ییلہ تِم تتھ جایہِ وٲتِتھ یتھ کلوری ونان چھِ، تتہِ کٔرِکھ تمِس تہٕ بدکار دٔچھنِس طرفہٕ تہٕ بیاکھ کھوورِ طرفہٕ۔ {کلوری : یا، کھوپڑی ہنز جاے}\n34. اَمہِ پتہٕ ووٚن عیسیٰ مسیح، بابا، تِمن معافی دِیُن۔ تکیازِ تم چھہِ نہ خبرے زِ تم کیا چھہِ کران۔ تہٕ تِمو ترٛٲوۍ أمۍ سُنٛد پلو تہٕ ترٛٲوٕکھ لاٹ۔\n35.\\tتہٕ لُکھ وُچھِتھ وُچھان۔ تہٕ یِمن سٍتـ̡ حُکُمرو تہِ کٔر طنز کٔرِتھ یہِ ونان زِ تٔمۍ بچٲوۍ باقٕے سُہ گژھہِ پنُن پان بچاوُن، اگر سُہ مسیح آسہِ، یُس خدایہِ سُند منتخب آسہِ۔\n36.\\tتہٕ سپاہیو تہِ کٔر أمِس ٹھٹھہٕ تہٕ أمِس نِش یِوان تہٕ أمِس دِژ سرکہٕ،\n37.\\tتہٕ ونُن، اگر تہٕ یہودین ہُند بادشاہ بٔنِو، پنُن پان بچٲوِو۔\n38.\\tتہٕ یِمن پیٹھ تہِ چھُ یونانی، لاطینی تہٕ عبرانی خطن مَنٛز اکھ تحریر لیکھنہٕ آمُت، یہِ چُھ یہودین ہُند بادشاہ۔\n39.\\tتہٕ یُس أکِس بدکار سٍتـ̡ پھٲنسی دِنہٕ آو، تٔمِس سٍتـ̡ وونُن زِ اگر تہٕ ژٕ مسیح بٔنِتھ پَنُن پان تہٕ أسـ̡ بچاو۔\n40.\\tمگر بییِس جواب دِنہٕ وٲلِس دِژ أمِس ملامت کٔرِتھ وونُن، کیا تُہۍ چھِو نہٕ خدایہِ سٕندِس سٍتـ̡ خوفزدہ سپدان۔\n41. تہٕ أسۍ چھِ پٔزۍ پٲٹھۍ انصاف کٔرِتھ؛ تکیازِ اسہِ چھہ پننین اعمالن ہند معاوضہ میلان مگر أمس چھہ نہ کانہہ غلط کٲم کٔرمژ۔\n42. تہٕ تٔمۍ ووٚن عیسیٰ مسیحس زِ خداوند، ییلہ تہٕ ژٕ پننہِ بادشٲہی منٛز یِنہٕ وِزِ مے یاد تھاوُن۔\n43. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تٔمِس زِ بہٕ چُھس ژے وَنُن، از تہٕ ژٕ آسُن میہ سٍتـ̡ جنتس مَنٛز۔\n44.\\tتہٕ یہ اوس لگ بھگ شیمہِ گھنٹہٕ، تہٕ نٔومہِ گھنٹس تام اوس سارِنٕے زمینس پیٹھ انہِ گوٚٹ۔ {زمین: یا، زمین}\n45.\\tتہٕ آفتاب گۆو انہِ گوٚٹ، تہٕ مندرُک پردہ گۆو درمِس منز۔\n46. تہٕ یێلہِ حضرت عیسیٰ علیہ السلام وۆن بَڑِ آوازِ سٍتـ̡ وۆن، تٔمۍ ووٚن، بابا، بہٕ چُھس پنُن روح تُہندس اتھس مَنٛز حوالہٕ کران، تہٕ یِتھٕ پٲٹھۍ ونِتھ ترووُن تٔمۍ ترووُن بھوت۔\n47.\\tوۅنۍ ییلہ وُچھ یہ کیا سپُد، تٔمۍ کٔر خدایہ سُند حمد تہٕ وونُن زِ یقینا اوس یہِ اکھ نیک انسان۔\n48.\\tتہٕ سارِوٕے لُکھ یِم اَتھ وُچھِتھ یِم کامہِ وُچھِتھ گٔیہِ، تِمو کٔرِکھ سینس تھپھ کٔرِتھ واپس۔\n49.\\tتہٕ تٔمۍ سٕندِ سارِنٕے واقف، تہٕ یِم زنانہٕ یِم گلیل پٮ۪ٹھٕ أمِس پَتہٕ یِنہٕ واجنہِ زنانہٕ گٔیہِ یِم چیز وُچھِتھ دوٗر کھڑا گٔیہِ۔\n50.\\tتہٕ وُچھِو، {اتہِ} اوس یوسف ناوُک اکھ شخٕص یُس اکھ مُشیر اوس۔ {تہٕ سُہ اوس} اکھ اصل انسان، تہٕ منصفانہ:\n51.\\t(تِمن ہٕندِس وکیلس تہٕ عملس سٍتۍ اوس نہٕ رضامندی دِژمٕژ؛) {سُہ اوس} یہودین ہُند شہر اریمتھاہُک: یُس پانہٕ خدایہ سٕنزِ بادشٲہی ہُند انتظار کران اوس۔\n52. یہِ {انسان} گۆو پیلاطس نِش تہٕ کوٚرُن عیسیٰ سٕندِس جسمس منگان۔\n53.\\tتہٕ تٔمۍ کٔر سُہ بۄن تہٕ لٔٹِتھ کٔرِن أکِس قبرس مَنٛز یُس کنن سٍتـ̡ ژٔٹِتھ اوس، یَتھ مَنٛز نہٕ اَمہِ برونہہ زانہہ انسان دِنہٕ آمُت اوس۔\n54.\\tتہٕ سُہ دۅہ اوس تیٲری تہٕ سبت آو شروع کرنہٕ۔\n55.\\tتہٕ زنانہٕ تہِ، یۅسہٕ أمِس سٍتـ̡ گلیل پیٹھٕ آمٕژ ٲس، تمہ پتہٕ وُچھکھ قبر تہٕ تٔمۍ سٕنز لاش کِتھہ پٲٹھـ̡ دِنہٕ آمٕژ۔\n56.\\tتہٕ تِم آیہ واپس، تہٕ کٔرٕکھ مسالہٕ تہٕ مرہم تیار۔ تہٕ حُکمَس مُطٲبِق کٔرٕن سبت دۅہہٕ آرام ۔","1.\\tوۅنۍ ہفتہٕ کس گۅڈنچہ دۅہہ، صُبحس سُلہِ آیہ تِم قبرس کُن، تِم مسالہٕ یِم تمو تیار کٔرۍمٕتۍ ٲسۍ، تہٕ کینہہ {باقی} پانس سٍتۍ۔\n2. تہٕ تمو لٔب قبرٕ نِش کٔنہِ ؤلِتھ۔\n3.\\tتہٕ تِمو اژِتھ اژِتھ تہٕ لٔبِکھ نہٕ خداوند عیسیٰ سُند لاش۔\n4.\\tتہ سپد یہ سپد ییلہ تم اتھ متعلق سیٹھا پریشان ٲسۍ، وچھ زٕ نفر چمکدار پلون منز تمن نش کھڑا۔\n5.\\tتہٕ ییلہ تِم کھوژِتھ تہٕ زمینس کُن بُتھ نمُت، تِمو ووٚنُن تِمن زِ تم کیازِ چھِو مُردن منز زندٕ ژھاران۔ {زندٕ: یا، سُہ یُس زندٕ چُھ}\n6. سُہ چُھ نہٕ یتہِ ، مگر سُہ چُھ زندٕ گومُت: یاد تھاوُن زِ سُہ کِتھہ پٲٹھـ̡ اوس تۅہہِ سٍتـ̡ کتھ کٔرمٕژ ییلہ سُہ وُنہِ تہِ گلیلِس مَنٛز اوس،\n7. یہ ونِتھ زِ انسان سُند فرزند گژھہِ گۅنہگارن ہٕندِس اتھس مَنٛز دِنہٕ یُن، تہٕ گژھہِ صلیب دِنہٕ یُن، تہٕ تریم دۅہہ گژھہِ دُبارٕ زندٕ۔\n8.\\tتہٕ تِمن ٲس تٔمۍ سٕندِ کلامٕچ یاد،\n9.\\tتہٕ قبرٕ پیٹھٕ واپس، تہٕ وونُن یِم سٲری کتھ کاہَن تہٕ باقین سارِنٕے تام۔\n10. یہ ٲس مریم مگدلینی تہٕ جوانا تہٕ یعقوب سٕنز موج تہٕ باقٕے {زنانہٕ} یِمو رسولن یِم کتھ ونان ٲسۍ۔\n11.\\tتہٕ تِہٕندِ کلامَس ٲس تِمن بیکار دٔلیلہٕ باسان۔\n12. پطرس ووٚتھ، تہٕ ژوٚل قبرس کُن۔ تہٕ بوٚن کٔرِتھ وُچھِتھ وُچھِتھ کُنہِ\n13.\\tتہٕ وُچھِتھ گٔیہِ تِمو منزٕ زٕ امی دۅہہ ایماوس ناوٕ أکِس گامس منز، یُس یروشلم پیٹھٕ تریہ تریہ فرلانگ دور اوس۔\n14.\\tتہٕ تِمو کٔر یِمن سارِنٕے چیزن مُتلق کتھ کرنہٕ۔\n15. تہٕ سپُد یہِ زِ یێلہِ تِمو رٔلِتھ تہٕ استدلال کٔرِتھ، عیسیٰ سٕندِ پانَے ووت نزدیک، تہٕ گۆو تِمن سٍتـ̡ ۔\n16.\\tمگر تہنز نظر ٲس تھپھ کٔرتھ زِ تم گژھن نہ تس زانن۔\n17.\\tتہٕ تٔمۍ ووٚن تِمَن زِ یِم کَمہِ قٕسمٕچ کتھ چھِ یِم اَکھ أکِس سٍتـ̡ پکان چھِو، تہٕ تُہۍ چھِو غمگیٖن آسان۔\n18.\\tتہٕ یِمو منزٕ أکِس، یٔمۍ سُند ناو کلیوپاس اوس، ووٚن أمِس جواب دِتھ، کیا تُہۍ چھُکھ یروشلمس مَنٛز اَکھ اجنبی تہٕ تِم چیز چھُنہٕ زانان یِم ازکل سپدان چھِ؟\n19.\\tتہٕ تٔمۍ ووٚن تِمَن کُس چیز؟ تہٕ تِمو ووٚن عیسیٰ مسیحس متعلق، یُس خدایہ تہٕ سارِنٕے لوکَن برونہہ کُن عملس تہٕ کلامَس مَنٛز طاقتور پیغمبر اوس۔\n20. تہٕ کِتھہ کٔنۍ دِژ سُہ بٔڈۍ پادٕرۍ تہٕ سانٮ۪و حکمرانو سُہ سُہ سزائے موت دِنہٕ خٲطرٕ دِنہٕ، تہٕ کِتھہٕ کٔنۍ دِژکھ أمِس صلیب دِنہٕ۔\n21.\\tمگر اسہِ اوس پژھ زِ یہ اوس سہ یُس اسرٲیلِس نجات دِنہٕ یُن، تہٕ امہ سارِوٕے کتھہِ علاوٕ چُھہ از تریم دۅہہ۔\n22.\\tآ، تہٕ سانہِ صحبتٕچ کینہہ زنانہٕ تہِ کٔر اسہِ حٲران، یِم سُلہٕ قبرس پیٹھ ٲسۍ۔\n23.\\tتہٕ ییلہ نہٕ تٔمۍ سُند لاش لوٚب، تِمو آو یہ ؤنِتھ زِ تِمو اوس فرشتن ہُند اکھ وژن تہِ وُچھمُت، یُس ونان اوس زِ سُہ چُھ زندٕ۔\n24.\\tتہٕ یِمو منزٕ کینہہ یِم اسہِ سٍتـ̡ ٲسۍ، گٔیہِ قبرس کُن، تہٕ لٔبـ̡ تِتھے پٲٹھۍ زنانہِ ہٕندِس وَننہٕ سٍتـ̡ تہٕ لٔبـ̡ تِمو وُچھمُت۔\n25.\\tاَمہِ پَتہٕ ووٚن تِمَن بیوقوف، تہٕ دِل سُہ یُس پیغمبرن ہٕندِس کُنہِ کتھہِ پیٹھ یقین کرُن:\n26. کیا مسیحس پزِ نہٕ یِمن چیزن ہُند شکار سپدُن، تہٕ پنہٕ نِس جلال سٍتـ̡ دٲخل گژھُن؟\n27.\\tتہٕ موسیٰ تہٕ سارِنٕے پیغمبرن پى۪ٹھ، تِمو کٔر تِمن سارِنٕے صحیفن مَنٛز پانس مُتلق کتھ بیان کرنہٕ۔\n28.\\tتہٕ تِم وٲتِتھ گامس کُن، ییتہِ تِم گٔیہِ، تہٕ تٔمۍ کٔر تِتھہ پٲٹھۍ زِ سُہ آسہ برونہہ کُن نیران۔\n29.\\tمگر تِمو کٔر سُہ مجبور، یہ ؤنِتھ زِ اسہِ سٍتـ̡ روزُن، تکیازِ شامس تام چُھ، تہٕ دۅہ چُھ واریاہ زیادٕ گُزاران۔ تہٕ سُہ گوٚو تمن سۭتۍ روزنہٕ خٲطرٕ۔\n30.\\tتہٕ سپُد یِمن سٍتـ̡ مازس پیٹھ بِہتھ، تٔمۍ نِش روٹی تہٕ دِژُن بریک تہٕ دِژُن تِمن دِنہٕ۔\n31.\\tتہٕ تِمن ہٕنزِ أچھ گٔیہٕ یلہٕ، تہٕ تِمو ٲس أمِس زانان۔ تہٕ سُہ گوٚو تِہٕنٛزِ نظرِ نِش غٲب۔ {غٲب...: یا، تِمن ہُند وُچھُن بند گٔیہِ}\n32.\\tتہٕ تِمو ووٚن اَکھ أکِس سٍتـ̡ ، یێلہِ سُہ اسہِ سٍتـ̡ کتھ کٔرِتھ تہٕ یێلہِ سُہ اسہِ سٍتـ̡ صحیفہٕ کھولنہٕ وِزِ اوسُس نہٕ سانہِ دِل دزان۔\n33. تہٕ تِم ووٚتھ أتھۍ ساتہٕ، تہٕ یِم یِمن سٍتـ̡ یِمن سٍتـ̡ وٲتِتھ واپس، تہٕ وُچھِکھ کاہ جمع تہٕ یِم تِمن سٍتـ̡ ٲسۍ۔\n34. یہ ونِتھ زِ خداوند چُھ پٔزۍ پٲٹھـ̡ زندٕ گومُت، تہٕ چُھہ شمعون سٍتـ̡ ظٲہر گومُت۔\n35.\\tتہٕ تِمو وَنُن زِ وتہِ کُس چیز آیہ کرنہٕ، تہٕ کِتھہ کٔنۍ اوس سُہ تِمن ہٕندِس بارس منز زانان۔\n36.\\tیێلہِ یێلہِ تِمو کتھ کٔرِتھ، عیسیٰ مسیح اوس پانَے تِمن مَنٛز کھڑا تہٕ تِمن وَنُن تِمن سٍتـ̡ امن ۔\n37.\\tمگر تِم گٔیہِ خوفزدہ تہٕ خوفزدہ تہٕ خیال زِ تِمو چُھ اکھ روح وُچھمُت۔\n38.\\tتہٕ تٔمۍ ووٚن تِمَن زِ تُہۍ کیازِ پریشان چھِو؟ تہٕ کیازِ چھہِ تۅہہِ دلن منز خیالات پٲدٕ سپدان؟\n39.\\tمیانہِ اتھہٕ تہٕ کھۅر وُچھِو، زِ یہ چھُس بہٕ پانہٕ: میہ تھپھ کٔرِتھ، تہٕ وُچھ۔ تکیازِ روحس چھہ نہ ماز تہ اڈجہ آسان، یتھہ پاٹھۍ ژیہ میہ وچھان چھیہ۔\n40.\\tتہٕ ییلہ تٔمۍ یِتھٕ پٲٹھۍ کتھ کٔر، تٔمۍ ہٲوۍ تِمن اتھہٕ تہٕ کھۅر ہٲوِتھ۔\n41.\\tتہٕ ییلہ تِم وُنہِ تہِ خوشی ہُند یقین اوس نہٕ تھاوان، تہٕ حیران گٔیہِ، تٔمۍ ووٚن تِمن ، کیا تۅہہ چھا یتہِ کانہہ ماز؟\n42.\\tتہٕ تِمو دِژ أمِس گاڈٕ ہُند اکھ ٹُکر، تہٕ ماچھہِ ہُند اکھ ٹُکر۔\n43.\\tتہٕ تٔمۍ رٔٹِتھ تہٕ کھیوٚن تِمن برونہہ کُن۔\n44.\\tتہٕ تٔمۍ ووٚن تِمن یِم لفظ یِم میہ تۅہہِ سٍتـ̡ کٔرۍمٕتۍ، یێلہِ بہٕ وُنہِ تہِ تہِ اوسس، زِ سٲری چیز گژھہِ پورٕ سپدُن، یُس موسىٰ سٕندِس شریعتس مَنٛز تہٕ پیغمبرن تہٕ زبورن مَنٛز میانہِ مُتلق لیکھنہٕ آمُت چھُ۔\n45.\\tتێلہِ کھولن تِمن ہٕنز سمجھ، یُتھ زن تِم صحیفہٕ سمجِتھ،\n46.\\tتہٕ وونُن تِمن یِتھٕ پٲٹھۍ چُھ یہِ لیکھنہٕ آمُت، تہٕ یِتھٕ پٲٹھۍ چُھ عیسیٰ مسیحس مُتٲثِر تہٕ تریمہِ دۅہہ مُردٕ سٍتـ̡ زندٕ روزُن:\n47. تہٕ یێمہِ سٕندِس ناوٕ سٍتـ̡ یێلہِ یروشلم پیٹھٕ شروع گژھِہ تٔمۍ سٕندِس ناوٕ سٍتـ̡ تٔمۍ سٕندِس ناوٕ سٍتـ̡ توبہ تہٕ گۅنہن ہٕنز معافی دِنہٕ یُن۔\n48.\\tتہٕ تُہۍ چھِو یِمن چیزن ہٕندِس گواہ سٍتـ̡ ۔\n49. تہٕ وُچھ، بہٕ چُھس پننِس مٲلہِ سُند وعدٕ توے سٍتـ̡ سوزان: مگر یروشلم کِس شہرس مَنٛز روزُن، یوتام نہٕ تۅہہ تھزرٕ پیٹھٕ اقتدار حٲصل سپدِ۔\n50. تہٕ سُہ نِیہِ تِم بیتھنی تام تہٕ تٔمۍ تُلِن پنٕنۍ اتھہٕ تہٕ دُعا دِژٕنۍ۔\n51.\\tتہٕ سپُد یہِ سپُد، یێلہِ تٔمۍ تِمن دُعا دِژ، سُہ آو تِمن نِش الگ تہٕ جنتس مَنٛز نِنہٕ۔\n52. تہٕ تِمو کٔر أمِس پوٗزا تہٕ گٔیہِ سٮ۪ٹھاہ خوشی سان یروشلم واپس۔\n53.\\tتہٕ ٲسٕس لگاتار مندرس مَنٛز خدایہ سٕنز حمد تہٕ برکت دِوان۔ آمین۔"];
